window.LST_MISSIONS={"updated":"2026-10-08","world":{"members":17887212,"congregations":32046,"missionaries":78596,"seniorServiceMissionaries":31613,"languages":188,"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/","growth":[[1830,22740],[1831,28893],[1832,28833],[1833,35329],[1834,45369],[1835,50761],[1836,59899],[1837,69567],[1838,79482],[1839,88585],[1840,95223],[1841,102166],[1842,112231],[1843,121327],[1844,136872],[1845,153674],[1846,171223],[1847,188419],[1848,203548],[1849,220798],[1850,237292],[1851,254941],[1852,271530],[1853,287982],[1854,308671],[1855,333018],[1856,359771],[1857,391034],[1858,422841],[1859,460687],[1860,499576],[1861,540130],[1862,578944],[1863,621448],[1864,666508],[1865,692273],[1866,736701],[1867,791837],[1868,849568],[1869,933511],[1870,1046270]]},"areas":[{"id":"africa","name":"Africa","members":1046270,"congregations":3220,"missions":54,"temples":8,"asOf":"2025-12-31","source":"https://www.churchofjesuschrist.org/learn/facts-statistics/africa?lang=eng"},{"id":"asia","name":"Asia","members":1343071,"congregations":2192,"missions":51,"temples":11,"asOf":"2025-12-31","source":"https://www.churchofjesuschrist.org/learn/facts-statistics/asia?lang=eng"},{"id":"europe","name":"Europe","members":528704,"congregations":1280,"missions":38,"temples":14,"asOf":"2025-12-31","source":"https://www.churchofjesuschrist.org/learn/facts-statistics/europe?lang=eng"},{"id":"north-america","name":"North America","members":9807340,"congregations":18501,"missions":187,"temples":135,"asOf":"2025-12-31","source":"https://www.churchofjesuschrist.org/learn/facts-statistics/north-america?lang=eng"},{"id":"oceania","name":"Oceania (Pacific)","members":629697,"congregations":1306,"missions":17,"temples":12,"asOf":"2025-12-31","source":"https://www.churchofjesuschrist.org/learn/facts-statistics/oceania?lang=eng"},{"id":"south-america","name":"South America","members":4517233,"congregations":5547,"missions":104,"temples":31,"asOf":"2025-12-31","source":"https://www.churchofjesuschrist.org/learn/facts-statistics/south-america?lang=eng"}],"places":[{"name":"Antigua and Barbuda","members":366,"congregations":1,"wards":0,"branches":1,"missions":0,"temples":0,"capital":"Saint John's","languages":"English","continent":"North America","summary":["The Church has had a presence in Antigua since 1984, and a branch was established the following year in St. John’s."],"history":["The government of Antigua and Barbuda gave permission for Latter-day Saint missionaries to teach on the islands starting in 1984. That same year, the first Latter-day Saint baptism in the country took place. A Church branch was organized in St. John’s in January 1985.","Early branch records include accounts of service projects, branch socials, and activities for children and youth. In 1992, Gloria Joseph, a Latter-day Saint and radio news broadcaster, helped introduce listeners around the country to the Church’s heritage of service by celebrating the 150th anniversary of the Relief Society and describing local members’ service projects. Over the years, members in the St. John’s branch worked together, shared their musical and literary talents, endured life challenges, and laid a foundation for the branch to remain strong. In November 2023, when Elder Ulisses Soares became the first apostle to visit Antigua, the branch hosted a special devotional broadcast to Church members around the Caribbean."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/antigua-and-barbuda?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":1,"id":"antigua-and-barbuda","kind":"country","firstMissionaries":{"year":1984,"said":"The government of Antigua and Barbuda gave permission for Latter-day Saint missionaries to teach on the islands starting in 1984."},"began":null,"lat":17.223472,"lng":-61.955461},{"name":"Aruba","members":686,"congregations":2,"wards":0,"branches":2,"missions":0,"temples":0,"capital":"Oranjestad","languages":"Dutch","continent":"North America","summary":["Missionaries arrived in Aruba in 1987. By 2004, there was a Church district in Oranjstad."],"history":["Missionaries Clay Jorgensen and Julio Gonzalez were sent to Aruba in January 1987 from the Venezuela Caracas Mission. When they arrived Jose Gonzalez was the only member on the island. He had joined the Church in Venezuela and had come to work in Caracoa. The missionaries began meetings with Gonzalez, which provided the nucleus that led to the formation of the Aruba Branch (a small congregation). Selections of the Book of Mormon were translated into Papiamento in 1987. The San Nicolas Branch was formed in June 1991.","Church President Gordon B. Hinckley and Elder Dallin H. Oaks of the Quorum of the Twelve visited Aruba in March 2001 while on their way to dedicate the temple in Uruguay. They met in the Aruba San Nicolas Branch chapel with about 180 Latter-day Saints. This is believed to be the first time a Church president had visited the island.","For Journalist Use Only","William G. Buckley National Director of Communication (297) 568-2080 E-mail"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/aruba?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":2,"id":"aruba","kind":"country","firstMissionaries":{"year":1987,"said":"Missionaries arrived in Aruba in 1987."},"began":null,"lat":12.501363,"lng":-69.961848},{"name":"Bahamas","members":1125,"congregations":3,"wards":0,"branches":3,"missions":0,"temples":0,"capital":"Nassau","languages":"English","continent":"North America","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","A group of Latter-day Saints began meeting in Nassau in 1979. English-speaking members and members who spoke Haitian Creole and French developed a local Church culture together. Bahamian Latter-day Saints have served their communities, and the Church has contributed to disaster relief efforts."],"history":["Latter-day Saints in the Bahamas hail from many different walks of life, including those with ancestral ties to the islands and those from other countries, such as Haiti and the United States. Early converts such as Clarence Newry, Helene and Alexandre Paul, and Antoine and Leona Ferrier threw themselves into the work of establishing the Church. Forming strong ties of sisterhood and brotherhood, Latter-day Saints worked together to share the restored gospel and contribute to their communities.","Latter-day Saints’ civic contributions and moral examples have been particularly important in the face of many years of government restrictions. By sharing language talents, developing a reputation for healthy living, and helping neighbors in the aftermath of hurricanes, Latter-day Saints have helped overcome local prejudices and establish the Church as a fully recognized institution in the Bahamas.","In a setting surrounded by nature’s beauty as well as its most destructive forces, Latter-day Saints have labored to establish the Church, diligently rebuilding structures and institutions when they require repair. Latter-day Saint meetinghouses have provided places of physical as well as spiritual refuge, withstanding many storms. Latter-day Saint congregations have been places where people of diverse backgrounds and native tongues can come together to find fellowship and faith. Through their creativity and diligence, Bahamian Saints have gathered “together upon the land of Zion” and created fellowship “for a defense, and for a refuge from the storm” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/bahamas?lang=eng","asOf":"2025-12-31","id":"bahamas","kind":"country","firstMissionaries":null,"began":{"year":1979,"said":"A group of Latter-day Saints began meeting in Nassau in 1979."},"lat":24.773655,"lng":-78.000055},{"name":"Barbados","members":1082,"congregations":3,"wards":0,"branches":3,"missions":1,"temples":0,"capital":"Bridgetown","languages":"English","continent":"North America","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","The first Latter-day Saint branch in Barbados was established in Christ Church in 1979. Latter-day Saints are regular contributors to community projects to fight drug abuse, restore the environment, help the poor, and respond to natural disasters."],"history":["The island of Barbados has long been home to people from many different walks of life. The first Latter-day Saints on the island were foreign expatriates. Beginning in 1978, local Barbadians, including some who had encountered the gospel overseas, joined the Church.","The earliest branch was established in Christ Church in 1979. Branches were subsequently organized in Black Rock in 1983 and Oistins in 1985. From 1984 to 1994, the headquarters of the West Indies Mission was located in Barbados. In 2002, the Christ Church Barbados District was organized.","For many years, significant local opposition to the Church existed, within both society and government. Full-time missionary work was often limited. As a result, local Latter-day Saints shouldered the burden of sharing the gospel and establishing a positive reputation for the Church. Latter-day Saints are regular contributors to community projects to fight drug abuse, restore the environment, help the poor, and respond to natural disasters.","In the multicultural society of Barbados, Latter-day Saints have worshipped Christ and shared the gospel, receiving God’s gift “unto all nations, of their own nation and tongue, to teach his word” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/barbados?lang=eng","asOf":"2025-12-31","id":"barbados","kind":"country","firstMissionaries":null,"began":{"year":1978,"said":"Beginning in 1978, local Barbadians, including some who had encountered the gospel overseas, joined the Church."},"lat":13.150033,"lng":-59.52503},{"name":"Belize","members":5741,"congregations":12,"wards":0,"branches":12,"missions":0,"temples":0,"capital":"Belmopan","languages":"English","continent":"North America","summary":["The first Latter-day Saint branch in Belize was organized in 1980. Today, Church members worship in several branches throughout the small country, and the service they have rendered to their community has been recognized by local leaders."],"history":["On May 11, 1980, Samuel Flores, president of the Honduras Tegucigalpa Mission, met with five young missionaries in a hotel room in Belize City. After holding a short sacrament service, President Flores organized the Belize City Branch, calling Elder Merlin Mikkelson to serve as the first branch president. The missionaries quickly went to work preaching throughout Belize City. On June 1, Ernesto Alay, the first local convert, was baptized. Others followed soon after. By the end of 1980, branches had been organized in Belize City, Corozal, Orange Walk, Dangriga, and San Ignacio. A district was organized in Belize City in April 1983, and meetinghouses were completed in Orange Walk and San Ignacio in 1987.","Latter-day Saints in Belize have served their communities, preached the gospel, and shared their love with others in need. In April 1991, the young women from the Belize City Branch received special recognition from the mayor of Belize City for their participation in an Earth Day project. In May 2003, members throughout the country contributed enough books and educational materials to fill two 40-foot containers, which were donated to the Ministry of Education in Belize.","Although the Church has only been established for a short time in Belize, the local Saints are strong and faithful. In Belize, “the harvest truly is great, but the labourers are few” (Luke 10:2). With such a small group, many have been called upon multiple times to lead."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/belize?lang=eng","asOf":"2025-12-31","id":"belize","kind":"country","firstMissionaries":{"year":1980,"said":"On May 11, 1980, Samuel Flores, president of the Honduras Tegucigalpa Mission, met with five young missionaries in a hotel room in Belize City."},"began":null,"lat":17.120494,"lng":-88.685903},{"name":"Canada","members":211581,"congregations":501,"wards":359,"branches":142,"missions":6,"temples":9,"capital":"Ottawa","languages":"French","continent":"North America","summary":["Even before the Church’s 1830 founding, believers brought unbound pages from the Book of Mormon to Canada. Canadian Latter-day Saints played key roles in the early Church and its missions. Pioneer-era Latter-day Saint settlements extended into Alberta; the first temple outside the United States was dedicated in Cardston in 1923. In the 20th century, vibrant Church congregations developed across Canada."],"history":["Even before the Church was organized, many early Latter-day Saints—including Joseph Smith, Lucy Mack Smith, Oliver Cowdery, and six of the original Twelve Apostles—traveled to Canada to preach and attend to Church business. In 1836, Parley P. Pratt preached near Toronto to a small group of Christians that included Leonora and John Taylor and Mary, Joseph, and Mercy Fielding, who were seeking a church with the “primitive simplicity” found in scripture.","Many of the more than 2,000 Canadians who joined the Church migrated to the western United States, along with the main body of the Saints, beginning in 1847. In 1887, Charles Ora Card, a stake president in Cache Valley, Utah, led a small group of Saints to Lee’s Creek (later Cardston), Alberta. Over the next three decades, Latter-day Saints migrated to southern Alberta in large numbers. In 1895, the Cardston Alberta Stake became the first stake outside the United States, and in 1923, the first temple outside the United States was built there.","By the end of the 1970s, stakes and missions had been established in every territory and province of Canada. Several Canadian citizens have served as General Authorities and General Officers of the Church, including First Presidency members Hugh B. Brown (1961–70) and N. Eldon Tanner (1963–82), Young Women General President Ardeth G. Kapp (1984–92), and Relief Society General President Elaine L. Jack (1990–97). By 2018, more than 195,000 members of the Church resided in the country, with additional temples built in or planned for Toronto, Halifax, Regina, Edmonton, Montreal, Vancouver, Calgary, and Winnipeg."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/canada?lang=eng","asOf":"2025-12-31","id":"canada","kind":"country","firstMissionaries":{"year":1836,"said":"In 1836, Parley P. Pratt preached near Toronto to a small group of Christians that included Leonora and John Taylor and Mary, Joseph, and Mercy Fielding, who were seeking a church with the “primitive simplicity” found in scripture."},"began":null,"lat":61.066692,"lng":-107.991707},{"name":"Cayman Islands","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["In 1970, Joan M. Evans, who was born in the Cayman Islands, joined the Church in Miami, Florida. In 1979, her family returned to her homeland where she operated a motel. She and her family were the only known members of the Church. For years she requested missionaries and was visited by mission presidents once or twice a year.","Church members Harold and Marjorie Booth from then Rhodesia moved to the Cayman Islands in November 1982 where the Booths found employment. They started holding sacrament meetings (worship services) with the Evans family.","Harold Booth developed a friendship with a Mr. Wilcox who was the islands’ chief immigration officer, and who had a brother that was a member of the Church in Rhodesia. In September 1985, Wilcox made arrangements so that missionaries complied with immigration law. Shortly thereafter, Richard Brough, president of the Jamaica Kingston Mission, sent the first missionaries.","Due to the Cayman’s economic strengths, Church membership in the country changes rapidly and has included people from the United States, Jamaica, Guyana, Canada and the United Kingdom. A philanthropist Church member donated land and money for a chapel to be built, which members moved into in July 2003. In 2003, there were 113 members.","For Journalist Use Only","Rafael G. Gutiérrez Caribbean Area Office: (809) 487-0120, Ext. 2233 Fax: (809) 533-2340 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/cayman-islands","asOf":"","id":"cayman-islands","kind":"country","continent":"North America","firstMissionaries":{"year":1985,"said":"In September 1985, Wilcox made arrangements so that missionaries complied with immigration law."},"began":null,"lat":19.703182,"lng":-79.917463},{"name":"Costa Rica","members":58373,"congregations":81,"wards":61,"branches":20,"missions":2,"temples":1,"capital":"San José","languages":"Spanish","continent":"North America","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","National Director of Communications of Costa Rica","Director of Communications and Area Publications","A few Latter-day Saints moved to Costa Rica in the 1940s, and missionaries arrived in 1946. By the 1960s, Costa Rican congregations were an important base for the Church’s work across Central America. The country’s Saints have a long tradition of hosting and helping others. In 2000, a temple was dedicated in San José."],"history":["In the 1940s, several Latter-day Saints who lived and worked in Costa Rica began holding meetings. In 1946, H. Clark and Adrienne Fails were living in San José, where Clark was working at the United States Embassy. Clark contacted the Mexican Mission, asking that missionaries be sent. Clark was soon called as a counselor in the Mexican Mission presidency, and Adrienne was set apart as a missionary. The missionaries soon found more interested people than they had time to teach.","By the 1960s, branches were organized throughout Costa Rica. In 1965, the headquarters of the Central American Mission was moved from Guatemala City to San José. In the decades since, Costa Rican Saints have provided strength and support to members throughout Central America. In 1966, more than 200 young Latter-day Saints from Costa Rica, Guatemala, Honduras, Nicaragua, and Panama met in San José for the first of many regional youth conferences. Over the next decade, seminary and institute classes began across the mission, and members from Costa Rica joined other Central American Saints in making regular trips to temples in Arizona, Mexico, and Guatemala.","As regional conflicts displaced Saints in neighboring countries, the Saints of Costa Rica welcomed them, “endeavouring to keep the unity of the Spirit in the bond of peace” (","). The Costa Rican Saints joined in unity toward the work of salvation, looking forward to a day when they would have a temple of their own. On June 4, 2000, that day arrived, with the dedication of the San José Costa Rica Temple."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/costa-rica?lang=eng","asOf":"2025-12-31","id":"costa-rica","kind":"country","firstMissionaries":{"year":1946,"said":"A few Latter-day Saints moved to Costa Rica in the 1940s, and missionaries arrived in 1946."},"began":null,"lat":10.273563,"lng":-84.07391},{"name":"Curacao","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Ingeborg Zielinski went to school in the Netherlands and joined the Church there in October 1970. She returned to Curacao in the Netherlands Antilles in September 1971. Over the next few years, she met with a few Latter-day Saints that temporarily lived in or visited the country.","In 1973, Zielinski was crowned Miss Curacao. She hosted hourly radio programs and taught the family home evening program and other gospel subjects, which were well received across the island, though she used a non-denominational approach to her show. She was the most well-known member of the Church on the island.","Missionary work was opened and closed on Curacao in 1978 by the Venezuela Caracas Mission following many requests for missionaries by Zielinski. The Curacao Branch (a small congregation) was created in October 1979. Though missionaries had visited for a couple weeks at a time since 1972, it was not until mission president Wesley W. Craig, Jr. sent missionaries in 1982 and decided that meetings should be conducted in the local language of Papiamento that the Church began to progress among natives. A chapel was dedicated in August 1988.","Bonaire, which is part of Netherlands Antilles, had 79 members in 2004. The first branch was organized in September 1990.","Membership in Netherlands Antilles in 2002 was 342.","For Journalist Use Only","Sharellis F. Maria Browne National Director of Communication 599-9-527-7964 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/curacao","asOf":"","id":"curacao","kind":"country","continent":"North America","firstMissionaries":{"year":1972,"said":"Though missionaries had visited for a couple weeks at a time since 1972, it was not until mission president Wesley W. Craig, Jr. sent missionaries in 1982 and decided that meetings should be conducted in the local language of Papiamento that the Church began to progress among natives."},"began":null,"lat":12.117649,"lng":-68.930926},{"name":"Dominica","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/dominica","asOf":"","id":"dominica","kind":"country","continent":"North America","firstMissionaries":null,"began":null,"lat":15.411314,"lng":-61.365362},{"name":"Dominican Republic","members":156358,"congregations":203,"wards":145,"branches":58,"missions":4,"temples":1,"capital":"Santo Domingo","languages":"Spanish","continent":"North America","summary":["In 1978, Dominican Latter-day Saints who embraced the restored gospel while living overseas returned to Santo Domingo and helped establish a Latter-day Saint branch. Many Dominicans found a place in the Church. By 1996 nearly half of all missionaries in the Dominican Republic were local members. The first temple in the Caribbean was dedicated in Santo Domingo in 2000."],"history":["On June 8, 1978—the day the revelation extending the priesthood to all male members of the Church regardless of race was announced—Eddie and Mercedes Amparo, Dominicans who had been baptized while living in the United States, returned to the Dominican Republic. In the airport, the Amparos met John and Nancy Rappleye, Latter-day Saints from Utah who were moving to Santo Domingo for work. The two families began holding weekly meetings together, and soon Noemí and Rodolfo Bodden decided to accept baptism. Missionaries arrived soon after, and a branch was organized.","The Church grew rapidly. Over the next three years, branches were organized in several neighborhoods of Santo Domingo and in several other communities. In 1980, a mission was organized in Santo Domingo. Around that same time, José Ramón Baez, Ana Rodriguez, Sara Espinosa, and Mayra Bobea, the first full-time missionaries called from the Dominican Republic, began their service abroad.","Dominican Saints have magnified their offices and labored in their might to bring the gospel to their neighbors (see","). By 1996, nearly half of all missionaries serving in the Dominican Republic were local members, and the missions were the most successful in the Caribbean Area. In 2000, the Santo Domingo Dominican Republic Temple, the first temple in the Caribbean, was dedicated. That same year, a missionary training center opened nearby. In times of need, Dominican Saints have reached out to bear up those around them. In the aftermath of several tropical storms, Dominican Saints have worked to rebuild homes, distribute emergency supplies, and care for the suffering."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/dominican-republic?lang=eng","asOf":"2025-12-31","id":"dominican-republic","kind":"country","firstMissionaries":{"year":1996,"said":"By 1996 nearly half of all missionaries in the Dominican Republic were local members."},"began":null,"lat":19.097403,"lng":-70.302803},{"name":"El Salvador","members":132399,"congregations":154,"wards":126,"branches":28,"missions":3,"temples":1,"capital":"San Salvador","languages":"Spanish","continent":"North America","summary":["Latter-day Saint missionaries arrived in El Salvador in 1949. During the civil war in the 1980s, with no foreign missionaries in the country, many people found spiritual guidance and community among the Latter-day Saints. The Church is now a well-established part of the religious landscape and disaster response efforts."],"history":["In June 1949, missionaries from the Mexican Mission rented a hall in San Salvador, where they offered English lessons and showed Church-produced films, neither of which garnered much interest. In the evenings, they taught the gospel to Ana Villaseñor, their widowed landlord. On March 2, 1951, after housing missionaries for several years, Ana converted and was baptized in El Salvador.","For nearly a decade, the gospel spread slowly in El Salvador. This changed in 1960, when more Salvadoran Saints began being called as leaders and missionaries. Under local direction, gospel preaching accelerated. Primary, seminary, and institute classes were organized to expand gospel learning among children and youth. Beginning in 1965, Salvadoran Saints began making the long journey to the temples in Arizona and later in Mexico City to participate in sacred ordinances. On June 3, 1973, the first stake in El Salvador was organized in San Salvador; by 1980, three more stakes had been organized.","In 1980, civil war swept across El Salvador. All North American missionaries were evacuated, and the mission closed. In 1984, the mission reopened with entirely local leadership and missionaries. The mission was so successful that, despite the war, six new stakes were organized throughout El Salvador before the conflict ended in 1992. Salvadoran Saints have sought the Lord with faith and diligence, and He has heard them (see","). “We pray for Thy blessings to rest upon … El Salvador,” President Henry B. Eyring of the First Presidency said on August 21, 2011, during the dedication of the San Salvador El Salvador Temple. “May peace reign in the land.”"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/el-salvador?lang=eng","asOf":"2025-12-31","id":"el-salvador","kind":"country","firstMissionaries":{"year":1949,"said":"Latter-day Saint missionaries arrived in El Salvador in 1949."},"began":null,"lat":13.800038,"lng":-88.914068},{"name":"Grenada","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["Although some Church members lived in Grenada while attending medical school, little permanent missionary work started until after the 1983 coup and subsequent invasion of Grenada by United States and United Nations forces.","Under the direction of President Kenneth L. Zabriskie of the West Indies Mission, Elders Robert W. Hoffmaster and Leonard C. Gill arrived in Grenada in May 1985. They met with a medical student and their children. A branch (a small congregation) was established in St. George on 3 September 1985.","Grenada is part of the Barbados Bridgetown Mission.","For Journalist Use Only","Rafael G. Gutiérrez Caribbean Area Office: (809) 487-0120, Ext. 2233 Fax: (809) 533-2340 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/grenada","asOf":"","id":"grenada","kind":"country","continent":"North America","firstMissionaries":{"year":1983,"said":"Although some Church members lived in Grenada while attending medical school, little permanent missionary work started until after the 1983 coup and subsequent invasion of Grenada by United States and United Nations forces."},"began":null,"lat":12.136037,"lng":-61.690404},{"name":"Guadeloupe","members":null,"congregations":3,"wards":0,"branches":3,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Among the first converts in Guadeloupe was the Claire Dinane family. Dinane came into contact with the Church because of his duties as a customs officer where he met Latter-day Saints. His family soon moved, but a nucleus of members had joined the Church through contact with Dinane. The Guadeloupe Branch (a small congregation) was organized in June 1982, but was discontinued several months later due to the apostasy of a member of the Church.","In June 1984, West Indies Mission President Kenneth Zabriskie sent French-speaking missionaries to Guadeloupe who had been transferred from French-speaking missions in Europe. Through their efforts the Grande-Terre Branch was organized by Elder Ronald E. Poelman of the Seventy (one of the governing bodies of the Church) in August 1984. The branch was strengthened by Dusan Kolvic, a Yugoslavian refugee who learned of the Church in France, but was not baptized. Kolvic’s work as a policeman for the French government required a transfer to Guadeloupe, and one evening he was dispatched to arrest a drunkard who was attacking two missionaries. Kolvic later joined the Church and served as branch president from 1986 – 1988. Because of Guadeloupe’s connection to France, there have been several members from France who have lived on the island for a few years and brought valuable experience to the Church there.","In April 1998, West Indies Mission President Kenneth J. Mason dedicated the first chapel in Guadeloupe at Basse-Terre.","For Journalist Use Only","Maddly Marcelle Nirellep National Director of Communication Phone: 590-690-82-7003 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/guadeloupe","asOf":"","id":"guadeloupe","kind":"country","continent":"North America","firstMissionaries":{"year":1984,"said":"In June 1984, West Indies Mission President Kenneth Zabriskie sent French-speaking missionaries to Guadeloupe who had been transferred from French-speaking missions in Europe."},"began":null,"lat":16.252883,"lng":-61.568686},{"name":"Guatemala","members":297143,"congregations":441,"wards":296,"branches":145,"missions":7,"temples":3,"capital":"Guatemala City","languages":"Spanish","continent":"North America","summary":["The first Guatemalan Latter-day Saints joined the Church in the 1940s. A few years later, missionaries began teaching in Mayan languages, and a strong multilingual tradition developed among Guatemalan Saints. Those Saints also developed the first","curriculum, which was later used worldwide. Central America’s first temple was dedicated in Guatemala City in 1984."],"history":["John F. O’Donnal, a Church member from the United States, moved to Guatemala in 1942 and foresaw a day when the gospel would be preached to the country’s native peoples. After World War II, he petitioned President George Albert Smith to send missionaries to the country. John’s wife, Carmen Galvez O’Donnal, soon became the first Guatemalan to be baptized. In 1956 missionaries began to study Mayan languages, fulfilling O’Donnal’s dream.","By 1962 there were over 10,000 Guatemalan Latter-day Saints in the cities and the highlands. Many of these faithful Latter-day Saints made great sacrifices to attend the Mesa Arizona Temple. They returned “endowed with power from on high” (Doctrine and Covenants 38:32) and prepared to build up the Church among Guatemala’s many ethnic and language groups. As the Church expanded throughout the country, Guatemalans developed programs such as Gospel Essentials classes, which would come to benefit the Church throughout the world. In 1984 Saints filled to capacity 11 dedicatory sessions for the Guatemala City Guatemala Temple.","Over the course of the Church’s history in Guatemala, Saints have served and supported one another through natural disasters, civil strife, and economic struggles. Countless Guatemalan Saints have sought to develop new skills to bless their families and communities and to administer to the poor and needy."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/guatemala?lang=eng","asOf":"2025-12-31","id":"guatemala","kind":"country","firstMissionaries":{"year":1942,"said":"John F. O’Donnal, a Church member from the United States, moved to Guatemala in 1942 and foresaw a day when the gospel would be preached to the country’s native peoples."},"began":null,"lat":15.585555,"lng":-90.345759},{"name":"Haiti","members":27550,"congregations":56,"wards":31,"branches":25,"missions":1,"temples":1,"capital":"Port-au-Prince","languages":"French","continent":"North America","summary":["After a group of 22 people joined the Church in Haiti in 1978, the Church grew quickly among Haitians, both in the country and in the diaspora. While foreign missionaries were sometimes withdrawn because of political instability, Haitian Saints led missionary efforts, and a stake was organized in 1997. A temple was dedicated in Port-au-Prince in 2019."],"history":["In 1977, after reading a pamphlet containing the testimony of Joseph Smith, Alexandre Mourra arranged to be taught by missionaries and was baptized in Fort Lauderdale, Florida. On his return to Port-au-Prince, Haiti, he preached the gospel and organized regular meetings in Hatte-Marré. In July 1978, 22 Haitian converts were baptized, and a branch was organized with Mourra as president.","The gospel spread quickly in Haiti. By 1983, when Elder Thomas S. Monson of the Quorum of the Twelve Apostles dedicated Haiti for the preaching of the gospel, a district with branches throughout the country had been organized. In the face of political discord, economic instability, and natural disasters, the Haitian Saints have proven resilient and faithful.","In 1991, when a coup forced foreign missionaries out of the country, Fritzner and Gina Joseph, the first Haitians to preside over the mission in Port-au-Prince, led an all-Haitian missionary force as they continued to preach the restored gospel. When a tropical storm destroyed Gonaïves in 2008, and later when an earthquake leveled cities throughout the country, Haitian Saints helped their neighbors by distributing Church-provided aid and helping rebuild.","In 2015 Haitian Saints across the globe rejoiced at the announcement of the construction of a temple in Port-au-Prince. The Port-au-Prince Haiti Temple was dedicated in 2019."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/haiti?lang=eng","asOf":"2025-12-31","id":"haiti","kind":"country","firstMissionaries":{"year":1977,"said":"In 1977, after reading a pamphlet containing the testimony of Joseph Smith, Alexandre Mourra arranged to be taught by missionaries and was baptized in Fort Lauderdale, Florida."},"began":null,"lat":19.139995,"lng":-72.357097},{"name":"Honduras","members":197073,"congregations":242,"wards":180,"branches":62,"missions":4,"temples":2,"capital":"Tegucigalpa","languages":"Spanish","continent":"North America","summary":["The first Honduran Latter-day Saints were baptized in 1953 in the Humuya River. Church members built the first meetinghouse 10 years later. By the 1990s the Church was well-established in Honduras and involved in disaster relief and other humanitarian efforts. The Tegucigalpa Honduras Temple was dedicated in 2013."],"history":["Shortly after the Central American Mission, which included Honduras, was created in November 1952, Mission President Gordon M. Romney and Elder Spencer W. Kimball of the Quorum of the Twelve Apostles traveled to Tegucigalpa, Honduras. While dining in a local hotel, the two were impressed by their waiter. “President Romney,” Kimball said, “there is your first elder in Honduras.” José Santos Ortega Flores, the waiter, was baptized in the Humuya River on March 21, 1953. Others were baptized that day, and José, in fulfillment of prophecy, was ordained the first elder in Honduras three years later. From that beginning, the gospel spread quickly beyond the capital and flourished in Honduras’s second-largest city, San Pedro Sula, where the first Honduran stake was created on April 10, 1977.","Through the years, Honduran members met adversity with faith and resilience, letting their “love abound unto all men” (","). Frequently hit by hurricanes and tropical storms, Honduran Saints have often joined with their communities in rebuilding and providing relief to those in need. In 1998, in the aftermath of Hurricane Mitch, members directed a large-scale effort to provide relief for members and nonmembers alike.","In the 1970s, Honduran Saints began making long journeys to the nearest temple—first in Arizona, then Mexico and Guatemala—to participate in sacred ordinances for themselves and their ancestors. After years of sacrifice, Honduran Saints rejoiced when, in March 2013, the Tegucigalpa Honduras Temple was dedicated. On September 5, 2020, construction work on the San Pedro Sula Honduras Temple commenced."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/honduras?lang=eng","asOf":"2025-12-31","id":"honduras","kind":"country","firstMissionaries":null,"began":{"year":1952,"said":"Shortly after the Central American Mission, which included Honduras, was created in November 1952, Mission President Gordon M. Romney and Elder Spencer W. Kimball of the Quorum of the Twelve Apostles traveled to Tegucigalpa, Honduras."},"lat":15.257243,"lng":-86.075514},{"name":"Jamaica","members":7856,"congregations":18,"wards":6,"branches":12,"missions":1,"temples":0,"capital":"Kingston","languages":"English","continent":"North America","summary":["Missionaries briefly taught in Jamaica in 1853, but the Church’s steady presence in the country began only in 1974. Despite political upheaval, many Jamaicans joined the Church over the next few years, allowing for the establishment of a district and several branches of the Church in the 1980s. The first stake in Jamaica was organized in 2014."],"history":["Missionaries from The Church of Jesus Christ of Latter-day Saints first preached in Jamaica in January 1853. The missionaries departed after one month of preaching exclusively to the white inhabitants of the island. More than a century passed before members of the Church, who came to Jamaica for work in the 1960s, began sharing the gospel with their neighbors.","In 1973, Paul Schmeil invited Victor Nugent, his coworker, and Victor’s wife, Verna, to come to his home to learn about the Church. Victor and Verna were impressed by Joseph Smith’s story and the Book of Mormon and quickly developed a conviction of their truthfulness but were disturbed by the restriction on priesthood ordination and temple attendance for black members of the Church. Despite their misgivings, the Nugents followed the spiritual impressions they received and were baptized on January 20, 1974.","Over the next several years, despite political upheaval around them, other Jamaicans joined the Church. On June 18, 1978, shortly after the priesthood and temple restriction was rescinded by revelation, Victor Nugent, Amos Chin, and Errol Tucker were ordained and soon assumed leadership of the Church in Jamaica. Within six years, a district with several branches and a mission had been organized. The Saints of Jamaica have “offer[ed] the sacrifices of righteousness, and put [their] trust in the Lord” (","). In the decades since, the Church in Jamaica has steadily grown. In 2014, the Kingston Jamaica Stake was organized."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/jamaica?lang=eng","asOf":"2025-12-31","id":"jamaica","kind":"country","firstMissionaries":{"year":1853,"said":"Missionaries briefly taught in Jamaica in 1853, but the Church’s steady presence in the country began only in 1974."},"began":null,"lat":18.185051,"lng":-77.394769},{"name":"Martinique","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Andre Condoris, a young man baptized in France while serving in the military, returned to his homeland in August 1980 and was the first known convert from the country. In July 1983, West Indies Mission President Kenneth Zabriskie visited Andre Condoris and Joell Joseph-Agathe, who had also been baptized in France. The two members welcomed missionaries Mark Richards, Stan Jones, and David Simons in May 1984, and held the first meeting on May 6. One month later Elder Ronald E. Poelman of the Seventy (one of the governing bodies of the Church) visited and a few months later Elder Vaughn J. Featherstone of the Seventy visited. The Martinique Branch (a small congregation) was organized in October 1985. The work has been slow in the country partly due to opportunities for members to immigrate to France.","For Journalist Use Only","Rafael G. Gutiérrez Règion du Caraïbe Bureau: (809) 487-0120, Ext. 2233 Fax: (809) 533-2340 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/martinique","asOf":"","id":"martinique","kind":"country","continent":"North America","firstMissionaries":{"year":1984,"said":"The two members welcomed missionaries Mark Richards, Stan Jones, and David Simons in May 1984, and held the first meeting on May 6. One month later Elder Ronald E. Poelman of the Seventy (one of the governing bodies of the Church) visited and a few months later Elder Vaughn J. Featherstone of the Seventy visited."},"began":null,"lat":14.611373,"lng":-60.962078},{"name":"Mexico","members":1572287,"congregations":1875,"wards":1401,"branches":474,"missions":34,"temples":14,"capital":"Mexico City","languages":"Spanish","continent":"North America","summary":["In the 1870s some people in Mexico encountered translated Book of Mormon selections and missionary pamphlets and corresponded with Church leaders. As early Mexican Latter-day Saints weathered the revolution and a schism among local members in the early 20th century, the Church developed deep local roots. In 2004 Mexico became the second country (after the United States) with one million Latter-day Saints."],"history":["By the 1870s, the Mexican government’s success in securing religious liberty led Brigham Young to conclude that the time had come to take the restored gospel to Mexico, spreading the Lord’s work among His dispersed people (see","). After portions of the Book of Mormon were translated into Spanish, missionaries baptized the first converts in 1877 in Hermosillo and organized a branch in Mexico City in 1879. In the 1880s, several colonies were also established in northern Mexico by Latter-day Saints emigrating from the United States.","Early Church meetings outside of Utah were often led by missionaries, but events such as the Mexican Revolution and the Cristero Rebellion required local leaders to play a greater role in Mexico. From 1936 to 1946, tensions with returning mission leadership led to a painful schism in the Church in Mexico before members were reconciled. The reunited Saints established the Church more fully in their communities, and, in 1961, a stake was organized in Mexico City.","In 1944, temple ordinances were translated into Spanish, and in 1945 many Mexican Saints traveled to Mesa, Arizona, to become the first in Church history to receive temple ordinances in a language other than English. In 1983 a temple was dedicated in Mexico City, and by the end of 2015 there were 13 temples in Mexico."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/mexico?lang=eng","asOf":"2025-12-31","id":"mexico","kind":"country","firstMissionaries":{"year":1877,"said":"). After portions of the Book of Mormon were translated into Spanish, missionaries baptized the first converts in 1877 in Hermosillo and organized a branch in Mexico City in 1879."},"began":null,"lat":23.658512,"lng":-102.00771},{"name":"Nicaragua","members":106953,"congregations":109,"wards":71,"branches":38,"missions":2,"temples":0,"capital":"Managua","languages":"Spanish","continent":"North America","summary":["The first Latter-day Saint branch in Nicaragua was organized in 1954. Latter-day Saints in the country supported each other through natural disasters like the 1972 Managua earthquake, years of civil war, and major social changes. Plans to build a temple in the country were announced in 2018."],"history":["In the 1950s, several Latter-day Saints moved to Managua, Nicaragua, and began holding meetings in their homes and inviting local people to attend. In 1954, José Guzmán and his daughter Nora Esperanza were baptized, and a branch was organized in Managua shortly after. Other converts soon followed. As the work progressed in Nicaragua, additional branches were organized, and a district was created in 1958.","On December 23, 1972, a massive earthquake struck Managua, leaving many Saints without homes and many more without employment. Members helped distribute more than 20 tons of relief supplies sent by the Church and held meetings in their homes. In the following months, members worked together to rebuild their homes, provide food, and secure new employment.","In 1977, political conflicts in Nicaragua led to violence. North American missionaries, falsely accused of orchestrating anti-government plots, were evacuated. Church-owned meetinghouses were confiscated. While some Nicaraguan Saints fled the country, those who remained held meetings in their homes, finding “in a great trial of affliction the abundance of their joy” (","). Local members accepted calls as missionaries, and the Church continued to grow. In March 1981, a stake was organized in Managua.","In the late 1980s, relations between the Church and the government improved, and meetinghouses were returned to the Church. In the decades since then, the Church and the government of Nicaragua have developed a strong working relationship and have worked on several joint humanitarian aid projects. In April 2018, the construction of a temple in Managua was announced during general conference."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/nicaragua?lang=eng","asOf":"2025-12-31","id":"nicaragua","kind":"country","firstMissionaries":null,"began":{"year":1954,"said":"The first Latter-day Saint branch in Nicaragua was organized in 1954."},"lat":12.350644,"lng":-85.784101},{"name":"Panama","members":63936,"congregations":80,"wards":48,"branches":32,"missions":1,"temples":1,"capital":"Panama City","languages":"Spanish","continent":"North America","summary":["In 1954 the first Panamanian Latter-day Saints were baptized. Early missionaries taught in Spanish and, in the San Blas islands, in Guna. By the 1980s there were enough Panamanian missionaries to keep the mission open when political turmoil led to a period without foreign missionaries. The Church grew, and a temple was dedicated in 2008."],"history":["Although several Latter-day Saints were stationed in the Canal Zone (a United States–occupied region of Panama) in the 1940s, a lasting Latter-day Saint presence was not established in the country until 1953. Beginning in the Canal Zone and working their way into the rest of the country, missionaries made slow progress in their preaching. In 1954, Juan Coleman and his wife, Irene Andreve, were the first local converts baptized in Panama.","In 1964, the Church began formal efforts to gain legal recognition and to preach more broadly in Panama. Early missionary efforts focused on the Guna people of the San Blas Islands (now known as Guna Yala). On February 4, 1966, 12 young men were baptized on Carti Tupile. The first meetinghouse in Panama was dedicated in 1974 in Ustupo. A stake was organized in Panama City in 1979, and selections of the Book of Mormon were published in Guna in 1981.","Amid political turmoil in the 1980s, only Panamanian Saints could be called to serve missions in the country. The local members took up this call with zeal, hearkening diligently unto the Lord (see","). Within a year, the work was thriving, and a mission was organized, with headquarters in Panama City. After he dedicated the land in 1991, Elder Howard W. Hunter, who was then a member of the Quorum of the Twelve Apostles, said, “This is the beginning of a new era.” In 2002, Panamanian Latter-day Saints celebrated the announcement of the Panama City Temple. The temple was dedicated in August 2008."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/panama?lang=eng","asOf":"2025-12-31","id":"panama","kind":"country","firstMissionaries":{"year":1964,"said":"In 1964, the Church began formal efforts to gain legal recognition and to preach more broadly in Panama."},"began":null,"lat":8.559559,"lng":-81.130843},{"name":"Puerto Rico","members":26947,"congregations":38,"wards":27,"branches":11,"missions":1,"temples":1,"capital":"","languages":"Continent","continent":"North America","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","The first Latter-day Saint branches in Puerto Rico were organized in 1955. In the 1960s and 1970s local members became pioneers of Latter-day Saint culture in the Caribbean. Church members have helped each other and their neighbors after natural disasters. A temple in San Juan was dedicated in 2023."],"history":["In the 1940s, small groups of Latter-day Saint American servicemen stationed in Puerto Rico began holding Church meetings. As other member families moved to the island, they connected with these groups. By 1955 there were enough members to form two branches: one in San Juan and one at Ramey Air Force Base in Aguadilla.","When full-time missionaries were assigned to the island in 1964, the branches were meeting in chapels on US military bases. As local membership grew, the San Juan Branch decided to construct a building of their own so that Sunday services could be held in Spanish. A month after the meetinghouse was dedicated in 1970, the first Spanish-speaking branch was formed.","By 1985 there were four stakes in Puerto Rico. However, in 1993 all the stakes were reorganized into districts. Puerto Rican Saints initially were disappointed by this setback but committed themselves to strengthening the Church on the island. These inspired Saints worked to share the gospel and encourage one another in living its principles.","There are now five stakes in Puerto Rico, and their dedication to the work continues. Whether they are attending the temple, providing aid after a natural disaster, or sharing the gospel with their neighbors, the Saints in Puerto Rico know “what a pleasure it is to work in the vineyard of the Lord, and what an honor it is to share His word and His light” with those around them (“Placentero nos es Trabajar,”"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/puerto-rico?lang=eng","asOf":"2025-12-31","id":"puerto-rico","kind":"country","firstMissionaries":{"year":1964,"said":"When full-time missionaries were assigned to the island in 1964, the branches were meeting in chapels on US military bases."},"began":null,"lat":18.224771,"lng":-66.485829},{"name":"Saint Kitts and Nevis","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["In July 1984, Elders Douglas Myers and Robert J. Mollina arrived on St. Kitts and were soon followed by Reuel and Alice Lambourn, on 20 October 1984. They converted a home into a meetinghouse, and the St. Kitts-Nevis Branch was organized 10 September 1985.","A local member, Carol Pamela Heather Thomas, became the first missionary from the islands when she was assigned in 1991 to a mission in the United States. In 1994, the branch had about 70 members taking part in all the Church programs.","St. Kitts and Nevis is part of the Puerto Rico San Juan Mission.","For Journalist Use Only","Rafael G. Gutiérrez Caribbean Area Office: (809) 487-0120, Ext. 2233 Fax: (809) 533-2340 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/saint-kitts-and-nevis","asOf":"","id":"saint-kitts-and-nevis","kind":"country","continent":"North America","firstMissionaries":{"year":1991,"said":"A local member, Carol Pamela Heather Thomas, became the first missionary from the islands when she was assigned in 1991 to a mission in the United States."},"began":null,"lat":17.250512,"lng":-62.672597},{"name":"Saint Lucia","members":null,"congregations":2,"wards":0,"branches":2,"missions":null,"stakes":null,"districts":null,"familySearchCenters":2,"temples":null,"history":["A. Clarieta Philgence joined the Church in England in July 1982 and soon returned to her homeland, St. Lucia. In August 1983, after learning about Philgence, West Indies Mission President Kenneth Zabriskie visited St. Lucia and met with Philgence and Al and Julie Nuttal, who had transferred from medical school in Grenada to St. Lucia. Zabriskie was accompanied by Elder Ronald E. Poelman of the Seventy (one of the governing bodies of the Church). In November 1983 President Zabriskie sent Elders Todd Hardy, Paul Jackson, Jay Schroeder and Marty Harris to begin missionary work. The first baptism in St. Lucia was Caren Cotter in September 1984.","The Castries Branch (a small congregation of the Church) was organized in January 1984. By June 1984, about 40 investigators and members were attending meetings. During the next few years missionaries began having trouble renewing their visas after anti-Mormon information was spread in the press. In 1986, missionaries Lewis and Jean Call were asked to leave the country by immigration officials in preparation for a visit of Pope John Paul II. Missionaries were not allowed to return following the papal visit.","The Castries Branch was discontinued in 1994, but was reorganized in April 2003.","For Journalist Use Only","Rafael G. Gutiérrez Caribbean Area Office: (809) 487-0120, Ext. 2233 Fax: (809) 533-2340 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/saint-lucia","asOf":"","id":"saint-lucia","kind":"country","continent":"North America","firstMissionaries":{"year":1983,"said":"In November 1983 President Zabriskie sent Elders Todd Hardy, Paul Jackson, Jay Schroeder and Marty Harris to begin missionary work."},"began":null,"lat":13.825049,"lng":-60.975036},{"name":"Saint Vincent","members":null,"congregations":3,"wards":0,"branches":3,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Elder Joseph B. Wirthlin, then of the Seventy (one of the governing bodies of the Church), visited St. Vincent in January 1980 along with President Richard L. Millett of the Puerto Rico San Juan Mission. Steven B. Wooley and Terry Williams were sent to be missionaries in the country in March 1980. Among those attending the meetings was Ebenezer Joshua, the first chief minister of the country who helped St. Vincent obtain independence from England. Joshua was one of the earliest converts and served in the branch (a small congregation) presidency.","Missionaries cleared the land for a chapel and a site dedication was held in June 1985; a building was subsequently constructed. When Joshua died in 1991, a crowd of 30,000 – 40,000 people, including top government officials, viewed or attended his televised funeral in the Kingstown chapel.","For Journalist Use Only","Rafael G. Gutiérrez Caribbean Area Office: (809) 487-0120, Ext. 2233 Fax: (809) 533-2340 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/saint-vincent","asOf":"","id":"saint-vincent","kind":"country","continent":"North America","firstMissionaries":{"year":1980,"said":"Steven B. Wooley and Terry Williams were sent to be missionaries in the country in March 1980."},"began":null,"lat":43.161439,"lng":-0.149274},{"name":"Sint Maarten","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/sint-maarten","asOf":"","id":"sint-maarten","kind":"country","continent":"North America","firstMissionaries":null,"began":null,"lat":18.042374,"lng":-63.054995},{"name":"Trinidad and Tobago","members":3458,"congregations":10,"wards":5,"branches":5,"missions":0,"temples":0,"capital":"Port of Spain","languages":"English","continent":"North America","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Though official missionary efforts in Trinidad and Tobago had to wait until 1988, the earliest members of the Church joined in the late 1970s, and the first branch was organized in 1980. In 1988 the government recognized the more than 1,000 Latter-day Saints and authorized expanded missionary work."],"history":["In 1976, Latter-day Saint Liz Rogers wrote to President Spencer W. Kimball and asked him to send missionaries to her home country of Trinidad. Regular efforts to send missionaries unfolded over the course of several years, and in 1977, the first local Trinidadian, Lucy Josephine Payne, was baptized. In 1980, members formed the Trinidad Branch (later the Port of Spain Branch).","Within this small branch, a core of dedicated members worked hard to establish Zion. As members of a tiny religious minority, they had to work hard to dispel misunderstandings about Latter-day Saints in the public sphere. Finally, in 1988, with more than 1,000 members in the country, the Church gained recognition from the government, allowing full-scale missionary efforts. In subsequent years, Trinidad and Tobago became a center of strength for members in the Caribbean.","Members from diverse backgrounds have come together in Trinidad and Tobago to establish Zion and serve in their communities. They have worked to root the restored gospel of Jesus Christ deeply into their own experiences and understanding, enriching the global Church. As the Lord said in",", “I will put my law in their inward parts, and write it in their hearts; and will be their God, and they shall be my people.”"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/trinidad-and-tobago?lang=eng","asOf":"2025-12-31","id":"trinidad-and-tobago","kind":"country","firstMissionaries":{"year":1976,"said":"In 1976, Latter-day Saint Liz Rogers wrote to President Spencer W. Kimball and asked him to send missionaries to her home country of Trinidad."},"began":null,"lat":10.74669,"lng":-61.084007},{"name":"Virgin Islands","members":null,"congregations":2,"wards":0,"branches":2,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["The first missionaries called to St. Croix were Elders Thomas Williams, Eric Leach, Gregory Collier and Kurtis Gibbons, who arrived 28 January 1981. They held meetings in the home of a member, Jack Cluet, with about 15 attending. A branch (a small congregation) was organized 8 February 1981. A meetinghouse was later built on the island. Branches have been established also on St. John and St. Thomas.","On St. Thomas, various expatriate families lived on the island. In 1969, one of these was the Earl Keele family. He arrived May 1969 and his wife, Celia, and two children followed in August. The family held a home Sunday School as part of the San Juan Branch in Puerto Rico.","In 1970, another family, James and Carolyn Boykin, joined the group. The first convert was baptized in January 1975. Other families arrived and the St. Thomas Branch was created 13 December 1977. The first missionaries came to the island in June 1978. The first branch meetinghouse was opened 16 July 1978.","A devastating hurricane, Hugo, struck St. Croix in September 1996, destroying the homes of many members. A shipment of food from the mainland and use of the branch meetinghouse helped alleviate the disaster conditions.","For Journalist Use Only","Rafael G. Gutiérrez Caribbean Area Office: (809) 487-0120, Ext. 2233 Fax: (809) 533-2340 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/virgin-islands","asOf":"","id":"virgin-islands","kind":"country","continent":"North America","firstMissionaries":{"year":1978,"said":"The first missionaries came to the island in June 1978."},"began":null,"lat":17.789187,"lng":-64.708057},{"name":"Argentina","members":505819,"congregations":742,"wards":506,"branches":236,"missions":14,"temples":5,"capital":"Buenos Aires","languages":"Spanish","continent":"South America","summary":["The first Latter-day Saint missionary effort in Argentina began in 1925, but significant growth began only after World War II. The first of many stakes was formed in 1966, and the first temple was dedicated in 1986. In the 21st century, Argentina has more than 400,000 members, multiple temples, and several dozen stakes."],"history":["In 1923, two German immigrants named Wilhelm Friedrichs and Emil Hoppe began preaching the gospel in Buenos Aires. In December 1925, the Church built on their success by sending Apostle Melvin J. Ballard to dedicate South America for the preaching of the gospel and to establish the South American Mission. “The work of the Lord will grow slowly for a time here just as an oak grows slowly from an acorn,” Ballard prophesied shortly before leaving Argentina. When the work matured, he said, “The South American Mission will be a power in the Church.”","As predicted, the Church grew slowly in Argentina at first. Argentine members gained valuable experience in the 1940s when foreign missionaries were withdrawn from the country and local members assumed leadership of the branches and the mission organization. Growth accelerated after foreign missionaries returned in 1946.","A building program initiated in the 1950s provided local meetinghouses for the rapidly expanding membership of the Church and gave on-the-job training opportunities to young men called on building missions throughout the country. In 1966, a stake was created in Buenos Aires, and several others were created soon after. In 1986, the Buenos Aires Argentina Temple was dedicated. By the beginning of the twenty-first century, about one percent of Argentines were Latter-day Saints. In 2015, a second temple was completed in Córdoba, and in 2018 President Russell M. Nelson announced a third temple to be built in Salta."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/argentina?lang=eng","asOf":"2025-12-31","id":"argentina","kind":"country","firstMissionaries":{"year":1923,"said":"In 1923, two German immigrants named Wilhelm Friedrichs and Emil Hoppe began preaching the gospel in Buenos Aires."},"began":null,"lat":-34.996496,"lng":-64.967282},{"name":"Bolivia","members":235773,"congregations":290,"wards":220,"branches":70,"missions":6,"temples":1,"capital":"La Paz","languages":"Spanish","continent":"South America","summary":["Latter-day Saint missionaries first arrived in Bolivia in 1964. Now, with dozens of stakes in the country, hundreds of thousands of Bolivian Latter-day Saints serve and strengthen each other and their communities as they face natural disasters and civil unrest. In 2000, the first temple in Bolivia was dedicated in Cochabamba."],"history":["In April 1927, J. Vernon Sharp, one of the first missionaries in South America, distributed tracts and preached for a short time in La Paz but baptized no converts. No efforts were made to preach in Bolivia for nearly 40 years. In 1963, Latter-day Saints working in La Paz and Cochabamba began hosting weekly meetings in their homes and successfully petitioned for legal status. When missionaries arrived in October 1964, many converts were awaiting baptism.","Branches were soon established in La Paz, Cochabamba, Santa Cruz, and Oruro. In 1968, a mission was established in La Paz, and missionaries were soon preaching in cities and towns across the country in Spanish, as well as in Aymara and Quechua, the local Indigenous languages.","The gospel spread quickly in Bolivia. Within a decade, more than 9,700 Latter-day Saints were living in the country. In 1979, stakes were organized in Santa Cruz, La Paz, and Cochabamba.","With “their hearts knit together in unity and in love” (","), Bolivian Saints have exemplified the power of covenant belonging. In the face of tragedy, they have rallied together to support one another and their neighbors. When natural disasters and civil unrest have created fear and insecurity, Bolivian Saints have offered support—spiritual and temporal—to lift one another. “[We] sacrifice so the Lord can see our hearts,” a stake president in La Paz explained.","The Cochabamba Bolivia Temple was dedicated by Church President Gordon B. Hinckley on April 20, 2000."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/bolivia?lang=eng","asOf":"2025-12-31","id":"bolivia","kind":"country","firstMissionaries":{"year":1927,"said":"In April 1927, J. Vernon Sharp, one of the first missionaries in South America, distributed tracts and preached for a short time in La Paz but baptized no converts."},"began":null,"lat":-17.05687,"lng":-64.991229},{"name":"Brazil","members":1573360,"congregations":2008,"wards":1650,"branches":358,"missions":37,"temples":11,"capital":"Brasília","languages":"Portuguese (Brazil)","continent":"South America","summary":["The earliest Latter-day Saints in Brazil were German immigrants in the 1920s, but Church growth accelerated after the Book of Mormon was published in Portuguese in 1940. The first stake (1966) and temple (1978) were established in São Paulo, with many more to come in the following decades."],"history":["Responding to requests from German members of the Church living in Brazil, missionaries began preaching in southern part of the country in 1928. For many years, the Church had some success in the German colonies in Brazil and made little effort to preach among the Portuguese-speaking population. Beginning in the 1930s, a rise in anti-German sentiment led to a government ban on the use of German in public. Church services were soon held in Portuguese, and some German-language materials were destroyed.","The Portuguese translation of the Book of Mormon, first published in 1940, signaled a new era for the Church in Brazil. As missionaries began preaching in Portuguese, the Church in Brazil grew faster than in any other country in South America. Branches, districts, and missions were established throughout the country. In 1966, the first stake in South America was created in São Paulo; 12 years later, the first temple in South America was dedicated in São Paulo.","Since 1978, hundreds of thousands of people have been baptized in Brazil. Wards and stakes are now established throughout the country, and temples are operating or are under construction in many of the major cities of Brazil. The 10th temple, the Brasília Brazil Temple, was announced April 2, 2017. “Brazil,” said President Russell M. Nelson, “is part of the heart of the Church.”"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/brazil?lang=eng","asOf":"2025-12-31","id":"brazil","kind":"country","firstMissionaries":{"year":1928,"said":"Responding to requests from German members of the Church living in Brazil, missionaries began preaching in southern part of the country in 1928."},"began":null,"lat":-10.333333,"lng":-53.2},{"name":"Chile","members":624203,"congregations":578,"wards":456,"branches":122,"missions":11,"temples":3,"capital":"Santiago","languages":"Spanish","continent":"South America","summary":["The first branch of the Church in Chile was established in 1956. Church membership grew quickly, and in 1983 the first Spanish-speaking temple was dedicated in Santiago. With dozens of stakes across the country, Latter-day Saints have become one of the largest religious groups in Chile."],"history":["Elder Parley P. Pratt of the Quorum of the Twelve Apostles served a mission in Chile in 1851 to 1852, but it was another century before the Church was permanently established in the country. In 1952, Billie F. Fotheringham and his family moved to Chile, secured government permission for missionaries to enter the country, and petitioned the Church to establish a mission. Missionaries arrived, and the Santiago Branch was organized in 1956.","The Church grew quickly in Chile. In 1983, the first temple in Spanish-speaking South America was dedicated in Santiago. By 1984 there were stakes spread across the country, from Arica in the north to Punta Arenas in the south, and by 1999 there were more than half a million members of record in the country.","With rapid growth came significant challenges. Chilean Saints responded by pioneering efforts to build a more solid foundation for the kingdom of God in rapidly developing areas throughout the world. In 2001, Chilean Saints were among the first to participate in the Perpetual Education Fund. From 2002 to 2004, Elder Jeffrey R. Holland of the Quorum of the Twelve Apostles served as Chile’s Area President, training leaders and gathering insights that would benefit the Church elsewhere.","Church members in Chile have offered assistance to those in need. Since the 1960 earthquakes in Concepción and Valdivia, Chilean Saints have played a role in disaster relief efforts. In 2004 the Church was also recognized by the Chilean government for its efforts in fighting poverty."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/chile?lang=eng","asOf":"2025-12-31","id":"chile","kind":"country","firstMissionaries":{"year":1952,"said":"In 1952, Billie F. Fotheringham and his family moved to Chile, secured government permission for missionaries to enter the country, and petitioned the Church to establish a mission."},"began":null,"lat":-31.761336,"lng":-71.31877},{"name":"Colombia","members":223090,"congregations":260,"wards":182,"branches":78,"missions":5,"temples":2,"capital":"Bogotá","languages":"Spanish","continent":"South America","summary":["Latter-day Saint missionaries first began preaching in Colombia in 1966. Church membership grew rapidly, and the first stake was organized in 1977. Due to difficulties in land acquisition, the first temple was delayed but was finally dedicated in Bogotá in 1999."],"history":["In May 1966, Elder Spencer W. Kimball of the Quorum of the Twelve Apostles and a small group of missionaries traveled to Bogotá, where Elder Kimball dedicated Colombia for the preaching of the gospel and organized the first branch in the country. The gospel spread quickly from there; within months missionaries had begun preaching in Cali, Medellín, Pereira, and Bucaramanga. Colombians accepted the gospel so readily that a mission was organized in Colombia in 1971.","Church growth after the creation of the mission accelerated even more quickly. By 1977, when the first stake in Colombia was created in Bogotá, nearly 12,000 members were living in the country. In April 1984, Colombian Saints celebrated the announcement of a temple in the country. However, ongoing difficulty with land acquisition and construction delayed the project. In the meantime, many Colombian Saints made significant sacrifices to attend the temple in other countries. In April 1999, 15 years after the temple was announced, it was finally dedicated. On the first day the temple was open, Saints participated in ordinances around the clock. A second temple, in Barranquilla, was dedicated in 2018.","Colombian Saints have frequently reached out in love and kindness to their neighbors and exemplified true servants of Christ by doing “the will of God from the heart” (","). In 2016, to celebrate the Church’s 50th anniversary in Colombia, Saints from all over the country participated in service projects, blood drives, family history exhibitions, and interfaith dialogues across the country."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/colombia?lang=eng","asOf":"2025-12-31","id":"colombia","kind":"country","firstMissionaries":{"year":1966,"said":"Latter-day Saint missionaries first began preaching in Colombia in 1966."},"began":null,"lat":4.099917,"lng":-72.908813},{"name":"Ecuador","members":279046,"congregations":338,"wards":276,"branches":62,"missions":7,"temples":2,"capital":"Quito","languages":"Spanish","continent":"South America","summary":["Latter-day Saint missionaries first began proselytizing in Ecuador in 1965. Soon, their efforts included teaching indigenous Otavalans, and in 1980 the Church published selections of the Book of Mormon in Kichwa. Today, hundreds of thousands of Ecuadorian Latter-day Saints serve in dozens of stakes and multiple temples across the country."],"history":["In 1965, as the first missionaries arrived in Ecuador, Elder Spencer W. Kimball of the Quorum of the Twelve Apostles expressed his belief that teaching the descendants of ancient Andean Indians would help fulfill God’s promise to bring the Book of Mormon to the Lamanites (see","). Over the next few years, Kimball traveled to Ecuador many times to encourage members and preach the gospel. In addition to Church centers in Quito and Guayaquil, the Church soon established a strong presence among indigenous Otavalans. Missionaries began preaching in the Kichwa language in the 1970s, and the Church published a Kichwa translation of selections from the Book of Mormon in 1980.","The first stake in Ecuador was organized in 1978. Just four years later, plans to construct a temple in Guayaquil were announced. As various logistical difficulties delayed the groundbreaking and construction of the temple, Ecuadorian Saints continued to build up the Church and prepare for a temple. In 1999, when the temple was finally dedicated, there were roughly 150,000 Latter-day Saints in Ecuador.","Church members have ministered to each other and to their communities both physically and spiritually, offering service, shelter, and aid in the wake of natural disasters as an expression of discipleship. By 2018 there were over 300 congregations in Ecuador, with a Church presence in every major city and many rural areas."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/ecuador?lang=eng","asOf":"2025-12-31","id":"ecuador","kind":"country","firstMissionaries":{"year":1965,"said":"Latter-day Saint missionaries first began proselytizing in Ecuador in 1965."},"began":null,"lat":-1.339767,"lng":-79.366697},{"name":"French Guiana","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Charles Fortin, a native of French Guiana, was baptized in France and returned to his homeland in 1980. Rosiette Fauvette, also baptized in France, returned to French Guiana in July 1981. She attended Sunday meetings at Fortin’s home in Cayenne. Charles Fortin introduced the Church to many people before his death in April 1986. By then, several other members were attending services, including Gerald Charpentier, who later became president of the first branch (a small congregation). Meetings were then held in the home of the Masinski family until January 1987 when they were moved to Rosiette Fauvette’s home in Kourou. In August 1987, the Francois Pratique family moved from France to Cayenne and began attending meetings.","Elder Charles Didier of the Seventy (one of the governing bodies of the Church) visited in March 1988 and organized a group. In November 1988, Serge and Christie Bonnoit of France became the first converts in French Guiana. In May 1989, the Kourou Branch was formed and in August, the Cayenne Branch was created with Francois Pratique as president.","In July 1989, the first missionary couple Wilbur and Jacqueline Wortham arrived in the country. They were followed in November 1989 by A. Edward and Louise P. Schmidt. The newly organized branch in Cayenne had about 23 members. On February 27, 1990, Elder M. Russell Ballard of the Quorum of the Twelve (the second highest governing body of the Church) blessed the land and with Elder Charles Didier visited branch members in both Cayenne and Kourou.","The Church has grown slowly in French Guiana due to members immigrating to France. A chapel was constructed in Cayenne and was dedicated in March 1999 by West Indies Mission president Kenneth J. Mason."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/french-guiana","asOf":"","id":"french-guiana","kind":"country","continent":"South America","firstMissionaries":{"year":1989,"said":"In July 1989, the first missionary couple Wilbur and Jacqueline Wortham arrived in the country."},"began":null,"lat":4.003988,"lng":-52.999998},{"name":"Guyana","members":7400,"congregations":12,"wards":0,"branches":12,"missions":1,"stakes":null,"districts":2,"familySearchCenters":4,"temples":null,"history":["Missionaries held the first sacrament meeting in Guyana in September 1988. Among those who attended was the Majid Abdulla family, which had been baptized previously in Canada.","The Church gained recognition in February 1989, and a small branch (a small congregation) in Georgetown was organized in March with about 23 in attendance.","In March of 1991, additional missionaries were sent to Guyana and the branch membership soon numbered more than 100 members. Later that year, Guyana became part of the newly created Trinidad Tobago Mission. By the end of 1993, there were about 270 members. By 1996, membership grew to about 500, and another branch was organized.","Guyana is part of the West Indies Mission.","For Journalist Use Only","Latchman Bharat National Director of Communication Oficina: (592) 652-3707 E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/guyana","asOf":"","id":"guyana","kind":"country","continent":"South America","firstMissionaries":{"year":1988,"said":"Missionaries held the first sacrament meeting in Guyana in September 1988."},"began":null,"lat":4.84171,"lng":-58.641689},{"name":"Paraguay","members":106345,"congregations":135,"wards":63,"branches":72,"missions":2,"temples":1,"capital":"Asunción","languages":"Spanish","continent":"South America","summary":["Missionaries first arrived in Paraguay in 1949, and Church membership quickly grew. Branches were organized in several cities, and an elementary school was established in the Moroni meetinghouse in Asunción in 1972. In the 1980s missionaries began teaching the Guaraní and Nevaclé peoples. A temple was dedicated in Asunción in 2002."],"history":["In 1948, before assuming his post as air attaché in the United States embassy in Paraguay, Samuel J. Skousen (a Latter-day Saint) was set apart as a missionary in the South American Mission. The Skousen family began holding meetings in their home in Asunción and invited their neighbors. On August 21, 1948, Alberto Rodríguez—the first Paraguayan convert—was baptized. Missionaries arrived the following year. The Church obtained government recognition in February 1950.","Missionaries found success among the cosmopolitan population of Paraguay. Early converts from Spanish, Italian, and German backgrounds quickly came to the Church and accepted calls to preach the gospel in Paraguay and neighboring Uruguay. Branches were soon organized in several cities. Meetinghouses—built by local members serving in the construction missionary program—soon sprung up around the country. In 1972, an elementary school was opened in the Moroni meetinghouse in central Asunción.","The gospel continued to be accepted by the diverse peoples of Paraguay. In the 1980s, missionaries began preaching to the Guarani and Nivaclé people. In 1980, nearly all the Nivaclé people in the village of Mistolar were baptized. Many Guarani also accepted the gospel. In 2009, the Book of Mormon was published in Guarani.","For many years, Latter-day Saints in Paraguay sacrificed time and money to travel the long distance to the temples in Salt Lake City, Utah; São Paulo, Brazil; and elsewhere. In May 2002, the need to travel great distances ended when the Asunción Paraguay Temple was dedicated."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/paraguay?lang=eng","asOf":"2025-12-31","id":"paraguay","kind":"country","firstMissionaries":{"year":1948,"said":"In 1948, before assuming his post as air attaché in the United States embassy in Paraguay, Samuel J. Skousen (a Latter-day Saint) was set apart as a missionary in the South American Mission."},"began":null,"lat":-23.316593,"lng":-58.169345},{"name":"Peru","members":667836,"congregations":809,"wards":684,"branches":125,"missions":15,"temples":4,"capital":"Lima","languages":"Quechua (Peru)","continent":"South America","summary":["In 1956 Latter-day Saints from the United States living in Peru began a branch and requested an official mission in the country. When the Andes Mission opened in 1959, 700 Peruvians had already joined the Church. Rapid growth continued, and by the 1980s the gospel was taught in both Spanish and Quechua."],"history":["While living in Chile in 1851, Elder Parley P. Pratt of the Quorum of the Twelve Apostles looked to Peru as a potentially fertile field for gospel preaching. “I had much desire to go to Peru,” he wrote later, “but an empty purse and imperfect tongue, which has only barely begun to stammer in that language … combined to cause me to wait a little.”","Although some efforts were made, more than a century passed before Pratt’s dream of establishing the Church in Peru was realized. In July 1956, a branch was organized in Lima, and members, primarily Americans working in the country, began inviting their neighbors to meetings in their homes. Missionaries arrived a month later. By 1959, when the Andes Mission was organized in Lima, more than 700 converts had been baptized, and three branches had been organized.","With such rapid growth, young men across Peru accepted calls as construction missionaries, gaining practical training in construction trades while building much-needed meetinghouses throughout the country. Growth continued as members continued to “proclaim [the] everlasting gospel” from city to city (see",") in Spanish and Quechua, a local Indigenous language. In 1986, the Lima Peru Temple, the first of four in Peru, was dedicated. Two years later, seven stakes were created in Lima in just two days, bringing the total number of stakes in the country to 34, in Lima, Sicuani, Trujillo, Arequipa, Chimbote, Chiclayo, Iquitos, Tacna, Piura, Huancayo, and Cusco.","Peruvian Saints have shown incomparable faith and devotion to the gospel and their communities. Amid violence, natural disasters, and civil unrest, they have remained bound together in love and have served the living and the dead."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/peru?lang=eng","asOf":"2025-12-31","id":"peru","kind":"country","firstMissionaries":{"year":1851,"said":"While living in Chile in 1851, Elder Parley P. Pratt of the Quorum of the Twelve Apostles looked to Peru as a potentially fertile field for gospel preaching."},"began":null,"lat":-6.86997,"lng":-75.045851},{"name":"Suriname","members":1991,"congregations":6,"wards":0,"branches":6,"missions":null,"stakes":null,"districts":null,"familySearchCenters":3,"temples":null,"history":["The Jay and Shirley Bills family lived in Suriname from 1969 to 1972 and held their own Church services. Their daughter Lisa Bills was baptized at age 8 in August 1967 in a river outside Paramaribo, the first known baptism in the country.","Former Netherlands Amsterdam Mission President John Limburg and his wife, Beverly, were called to begin missionary work in Suriname. The Limburgs arrived in Paramaribo in October 1988. By the beginning of 1989, approximately 16 people were attending services. On Easter Sunday, March 26, 1989, August Marengo and two sisters, Eleni and Maudi Treonosimitoe, became the first converts baptized.","A month later Iwan Nathaniel and Philly Denswel were baptized. Denswel’s extended family lived in Lelydorp, which led the Limburgs to begin holding worship services there in December 1989. Membership had increased in Paramaribo so that in November 1989 a branch (a small congregation) was formally organized. By 1990, attendance at the branch averaged about 100 people.","Elder M. Russell Ballard of the Quorum of the Twelve (the second highest governing body of the Church) visited in February 1990. Four men saw in the newspaper an announcement of Elder Ballard’s coming to Suriname and attended the meeting. All four joined the Church, including Stanley Cooman, who became the first native branch president. In 1990, don and Lorna Rapier received copies of pre-recorded radio broadcasts about gospel principles from missionaries in Holland and arranged for broadcasts on a local Dutch-speaking radio program. Irena Manakavera heard one of the broadcasts and was later baptized. She was influential in bringing 28 people into the Church, including several members from a local Carib Indian tribe.","In 2001, there were 495 members in Suriname. The Paramaribo chapel was dedicated in July 2001 and, due to membership growth, the Paramaribo Branch was divided in September 2002 to form the Wanica Branch.","For Journalist Use Only","Roy Haverkamp","National Director of Communication","(597) 884-7296","E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/suriname","asOf":"","id":"suriname","kind":"country","continent":"South America","firstMissionaries":{"year":1990,"said":"In 1990, don and Lorna Rapier received copies of pre-recorded radio broadcasts about gospel principles from missionaries in Holland and arranged for broadcasts on a local Dutch-speaking radio program."},"began":null,"lat":4.141303,"lng":-56.077119},{"name":"Uruguay","members":112449,"congregations":132,"wards":100,"branches":32,"missions":2,"temples":1,"capital":"Montevideo","languages":"Spanish","continent":"South America","summary":["The first branches of The Church of Jesus Christ of Latter-day Saints in Uruguay were organized in the late 1940s. After decades of growth, the Church has established several stakes and dedicated the Montevideo Uruguay Temple in 2001."],"history":["In 1927, missionaries from the South American Mission, headquartered in Argentina, traveled to Montevideo to assess the possibilities of preaching there. However, it wasn’t until 1944, when Frederick S. Williams was working with the US State Department and living in Montevideo, that Latter-day Saints worshipped in the country. Williams and his wife, Corraine, began holding meetings in their home with a few other members living in the country. They petitioned the First Presidency to create a mission, which was organized in 1947 with Williams as president.","Missionaries soon came to Montevideo from Argentina, and in four years, 23 branches were organized across the country. During the 1960s the Church in Uruguay matured as local members were called to replace missionaries in leadership positions. Even recent converts were enlisted to lead branches, and in 1967 the Montevideo Uruguay Stake was organized, with Vincente Rubio as stake president.","In 2001, the Montevideo temple was dedicated, a testament to the growth of the Church and the faith of the Saints in the country. Uruguayan Saints have served frequently in their community and have become important leaders in the Church. In 1990, Luis Alberto Ferrizo, a regional representative, was elected as a national deputy, and in 1996, Francisco J. Viñas was called to serve as a General Authority Seventy. When flooding along the Paraná and Uruguay Rivers forced the evacuation of 80,000 people, members collected food and clothing for flood victims."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/uruguay?lang=eng","asOf":"2025-12-31","stakes":null,"districts":2,"familySearchCenters":43,"id":"uruguay","kind":"country","firstMissionaries":{"year":1927,"said":"In 1927, missionaries from the South American Mission, headquartered in Argentina, traveled to Montevideo to assess the possibilities of preaching there."},"began":null,"lat":-32.875555,"lng":-56.020153},{"name":"Venezuela","members":179389,"congregations":235,"wards":176,"branches":59,"missions":4,"temples":1,"capital":"Caracas","languages":"Spanish","continent":"South America","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","The first branch of the Church was organized in Venezuela when they received official recognition from the government in 1966. In Caracas, a stake was organized in 1977 and a temple was dedicated in 2000. After 2004 political tensions prevented preaching from outside missionaries, but local Venezuelan missionaries continued spreading the gospel."],"history":["Beginning in 1955, American Latter-day Saints living in Caracas began holding meetings in their homes and inviting neighbors whenever possible. In 1966, Church members received official recognition from the government of Venezuela, and a branch was organized. Missionaries from the Central American Mission arrived soon after and began teaching. In 1967, the first Venezuelan converts—Natividad and Hernán Sepulveda—were baptized.","Over the next decade, branches and districts were organized in Maracaibo, Puerto Ordaz, and Mérida. In 1977, Venezuelan Saints traveled to Salt Lake City, where they participated in temple ordinances. Later that year, a stake was organized in Caracas. Members continued to work to share the gospel with their neighbors and prepare the way for one another to attend the temple and make sacred covenants. After the São Paulo Brazil Temple was dedicated in 1978, members in Venezuela made regular group trips to the house of the Lord. When the Caracas Venezuela Temple was dedicated in 2000, membership in Venezuela was nearing 100,000.","In 2004, Venezuela underwent a major political revolution. New laws prevented most non-Venezuelans from preaching in the country. Church leaders discussed closing the four missions in the country, but Venezuelan Saints, committed to the Church’s continued presence in the country, assumed leadership of the missions, and young men and women across the country accepted callings as missionaries. Through their faith and diligence, Venezuelan Saints have shown that “the Lord will surely prepare a way for his people” (","). The four missions have remained open since 2004, with no outside leadership or staffing support."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/venezuela?lang=eng","asOf":"2025-12-31","id":"venezuela","kind":"country","firstMissionaries":{"year":2004,"said":"After 2004 political tensions prevented preaching from outside missionaries, but local Venezuelan missionaries continued spreading the gospel."},"began":null,"lat":8.001871,"lng":-66.110932},{"name":"Albania","members":3285,"congregations":13,"wards":5,"branches":8,"missions":1,"temples":0,"capital":"Tirana","languages":"Albanian","continent":"Europe","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","The Church has been active in Albania since the early 1990s. Since its first branch was organized in 1993, the Church has steadily grown in Albania, and in 2014 its first stake was organized."],"history":["Albania’s Christian history dates back to the early centuries of the Common Era. Islam became another prominent influence on religious life through subsequent long periods of rule under Muslim regimes such as the Ottoman Empire. However, between 1967 and 1985, the Communist-led government of Albania persecuted religious believers. After 1991, the country entered a period of transition away from authoritarian rule and toward a democratic system of government that allowed freedom of religion.","In February 1992, Church humanitarian missionary couples arrived at the University of Tirana. A nucleus of investigators and members formed, and on February 2, 1993, the Tirana Branch was organized. By November 1999 local translators had completed work on the Albanian edition of the Book of Mormon. The first meetinghouse was built in Durrës in 2006, and the first stake was established in 2014.","Latter-day Saints have worked to bless their communities, supporting the education of Roma ethnic-minority children, aiding flood victims, and donating blood. They have also organized visual arts exhibitions to capture and share images of beauty and inspiration with the public, helping Zion “increase in beauty, and in holiness,” enlarging her borders, and strengthening her stakes ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/albania?lang=eng","asOf":"2025-12-31","id":"albania","kind":"country","firstMissionaries":{"year":1992,"said":"In February 1992, Church humanitarian missionary couples arrived at the University of Tirana."},"began":null,"lat":41.179348,"lng":19.882419},{"name":"Andorra","members":818,"congregations":2,"wards":0,"branches":2,"missions":0,"temples":0,"capital":"Andorra la Vella","languages":"Catalan","continent":"Europe","summary":["The Church began in Andorra in 1991 with five members, and an Andorran branch was created in 1993."],"history":["In 1991, there were five members living in Andorra. The first to be baptized in Andorra was Marlize Gomez Lima in April 1992. The Andorra Branch (a small congregation) was created in August 1993, and the first branch presidents were Javier Ortega and Jose Luis Bota, who did not live in the branch boundaries. Previously members traveled 84 miles to Lerida, Spain, to attend meetings.","In that same year, religious freedom was granted and the Church applied for official recognition. In 1994 the branch received its own chapel. Previously meetings were held in private homes. Javier Agulced Jerez was baptized with his wife and two daughters in March 1998 and became the first branch president to live in the branch.","For Journalist use only,","National Director of Public Affairs and Communications","Sérgio Flores","Telephone: +34 663 415 479","Email"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/andorra?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":null,"id":"andorra","kind":"country","firstMissionaries":null,"began":{"year":1991,"said":"The Church began in Andorra in 1991 with five members, and an Andorran branch was created in 1993."},"lat":42.540717,"lng":1.573203},{"name":"Armenia","members":3579,"congregations":8,"wards":0,"branches":8,"missions":1,"temples":0,"capital":"Yerevan","languages":"Armenian","continent":"Europe","summary":["Communities of Armenian Latter-day Saints have been in the Near East since the late 19th century. A translation of the Book of Mormon in Western Armenian was published in 1937, followed nearly 10 decades later by a translation in Eastern Armenian. Despite early challenges related to persecution and regional conflict, Armenian Latter-day Saint communities have become more established in recent years."],"history":["In the late 19th century, communities of Armenian Latter-day Saints in parts of the Ottoman Empire, such as Aintab, Aleppo, and Zara, worked to build Zion in the face of significant persecution. Increased turbulence in the early 20th century caused Latter-day Saint Armenian congregations to dwindle due to emigration, reassimilation into other religious communities, and violence. Emigrants in the United States translated the Book of Mormon into Western Armenian, published in 1937.","In 1989, following a devastating earthquake in Armenia, Church officials sent representatives to consult with the government about building a concrete plant. In 1991, humanitarian couples with construction expertise arrived in Yerevan to work on the plant. Some local Armenians who worked with the couples eventually formed the nucleus of the Yerevan Branch. In 2000, the Eastern Armenian translation of the Book of Mormon was published. In 2010, Armenian members headed every congregation in the country.","In the 21st century, building and rebuilding on these legacies of sacrifice and faith, Armenian Latter-day Saints set examples of Christlike love in their communities, heeding the Savior’s call to “lift up an ensign of peace” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/armenia?lang=eng","asOf":"2025-12-31","id":"armenia","kind":"country","firstMissionaries":null,"began":{"year":1937,"said":"A translation of the Book of Mormon in Western Armenian was published in 1937, followed nearly 10 decades later by a translation in Eastern Armenian."},"lat":40.769627,"lng":44.673665},{"name":"Austria","members":4753,"congregations":17,"wards":14,"branches":3,"missions":0,"temples":0,"capital":"Vienna","languages":"German","continent":"Europe","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","National Director of Public Affairs and Communications","The first missionaries arrived in Austria in 1865 but were banished later that year. Despite early difficulties, the Church gradually grew, and the first branch was formed in 1902. After World War II, the Church grew quickly in Austria, and in 2021 the construction of the Vienna Austria Temple was announced."],"history":["Elder Orson Pratt of the Quorum of the Twelve Apostles dedicated Austria for the preaching of the gospel in 1865, but only a handful of Austrians joined the Church in the nineteenth century. The first lasting group in Austria began with the baptism of Johann Huber from Haag am Hausruck in 1900. Like the early Christians, early Saints in Austria endured religious prejudice and political tumult after embracing the gospel message.","Early Austrian Saints kept the faith and nurtured some of the first converts from other regions of the Austro-Hungarian Empire before its disintegration at the end of World War I. In 1920, members remaining in Austria were organized into the Vienna District; these Saints kept the faith through an international economic depression, annexation by Nazi Germany, and the violence of World War II. The Church grew rapidly in the postwar years, from roughly 200 members during the war to more than 2,500 by the end of the 1960s. Austria’s first stake was organized in Vienna in 1980. A second stake was organized in Salzburg in 1997. By 2015, there were over 4,500 Latter-day Saints in Austria contributing to the communities and reaching out to others in acts of service."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/austria?lang=eng","asOf":"2025-12-31","id":"austria","kind":"country","firstMissionaries":{"year":1865,"said":"The first missionaries arrived in Austria in 1865 but were banished later that year."},"began":null,"lat":47.59397,"lng":14.12456},{"name":"Belgium","members":7164,"congregations":14,"wards":9,"branches":5,"missions":0,"temples":0,"capital":"Brussels","languages":"Dutch","continent":"Europe","summary":["The first Belgian Latter-day Saints were baptized in 1888. The earliest growth in Belgium was in French-speaking cities, but the Church’s presence in the Flanders region (Dutch-speaking) grew significantly after World War II. Today, Brussels is home to the European Union & International Affairs Office of The Church of Jesus Christ of Latter-day Saints. In 2021 the Brussels Belgium Temple was announced."],"history":["The first attempts to preach the restored gospel in regions of Belgium began as early as the 1860s. However, it was not until the late 1880s—after Mischa Markow, a Serbian missionary, baptized Henrietta Esselmann and her children in Antwerp—that missionaries began to travel to Belgium more regularly. By the mid-1890s, missionaries from the Netherlands Mission established branches in Antwerp, Liège, and Brussels. While many early members soon immigrated to Utah, a small group of Belgian Saints remained and continued to share the gospel.","Situated between France, Germany, and the Netherlands, Belgium is a nation with two distinct linguistic regions—a puzzle that has marked the history of the Church in the nation. For much of the history of the Church in Belgium, responsibility for overseeing missionary efforts has been split between the French and Netherlands Missions. Beginning in 1924, branches were organized in many French-speaking Walloon cities, and meetinghouses were built to accommodate the growing number of converts. These successes led to the organization of the French-speaking Brussels Belgium Stake in 1977.","However, few missionaries traveled to Flanders, the Dutch-speaking region in the north, before 1947. A district was organized in Antwerp in 1948, and Dutch-speaking congregations were soon formed. Following the organization of the Antwerp Belgium Mission in 1975, the Church in Flanders experienced substantial growth. The Dutch-speaking Antwerp Belgium Stake was organized in 1994.","Living in a diverse, multicultural nation, Belgian Saints have worked to build “the unity of the Spirit in the bond of peace” (",") across language, culture, and experience in their local communities. They have sought unique opportunities to have thoughtful discussions about faith through media, cultural events, and academic conferences. On April 4, 2021, President Russell M. Nelson announced plans to build a temple in Brussels."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/belgium?lang=eng","asOf":"2025-12-31","id":"belgium","kind":"country","firstMissionaries":{"year":1947,"said":"However, few missionaries traveled to Flanders, the Dutch-speaking region in the north, before 1947."},"began":null,"lat":50.640281,"lng":4.666715},{"name":"Bosnia and Herzegovina","members":91,"congregations":1,"wards":0,"branches":1,"missions":0,"temples":0,"capital":"Sarajevo","languages":"Croatian","continent":"Europe","summary":["The Church has been present in Bosnia and Herzegovina since the early 1990s. Despite the challenges of local conflict, the Church has grown steadily, and faithful pioneers help build safe communities of fellowship and worship."],"history":["In 1996, Elder Jeffrey R. Holland of the Quorum of the Twelve Apostles visited Sarajevo to offer an apostolic blessing of peace for the area. By that time, Church members had been involved in the country for several years. During the early 1990s, members across Europe helped gather and deliver aid to those affected by conflict. In the late 1990s, many members from other countries worshiped in temporary groups while living in Bosnia, and many Bosnians living abroad joined the Church.","It was not until 2010, however, that Elder Russell M. Nelson, then a member of the Quorum of the Twelve Apostles, organized a permanent branch in Sarajevo and dedicated the country for the preaching of the gospel. The Church received official government recognition in 2012, and a year later, a second branch was organized in Banja Luka.","Pioneering members of the Church in Bosnia and Herzegovina have built bonds of fellowship with Saints in neighboring countries and worked to prepare themselves for the future. Together, they are striving to make the Church in Bosnia and Herzegovina a safe and welcoming place for those who come to join them in worship."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/bosnia-and-herzegovina?lang=eng","asOf":"2025-12-31","id":"bosnia-and-herzegovina","kind":"country","firstMissionaries":{"year":2010,"said":"It was not until 2010, however, that Elder Russell M. Nelson, then a member of the Quorum of the Twelve Apostles, organized a permanent branch in Sarajevo and dedicated the country for the preaching of the gospel."},"began":null,"lat":44.305348,"lng":17.596147},{"name":"Bulgaria","members":2424,"congregations":7,"wards":0,"branches":7,"missions":1,"temples":0,"capital":"Sofia","languages":"Bulgarian","continent":"Europe","summary":["After initial preaching efforts in 1900, the first Bulgarian converts to the Church joined overseas throughout the 20th century. After the first official mission began in 1991, the Bulgarian translation of the Book of Mormon was produced in 1999, and meetinghouses were dedicated in Sofia (2000) and Plovdiv (2001)."],"history":["Latter-day Saints have labored to establish the Church in Bulgaria since 1900, when Mischa Markow and Argir Dimitrov first preached, with no success, in Sofia. Over the next several decades, numerous Bulgarians accepted baptism overseas. In 1988, Church leaders met with government officials to discuss establishing the Church in Bulgaria, but the Church was not officially registered in Bulgaria until the1990s.","In 1991, following a change in Bulgaria’s government, Nevenka and Kiril Kiriakov returned to their homeland to preside over the first mission in Bulgaria. Early members exerted tremendous energy to officially register the Church with the government, translate teaching materials and sacred texts, fulfill callings in fledgling branches and districts, and share the gospel with others. They “labored without ceasing” to “bring souls unto repentance; … that they might also be born of God, and be filled with the Holy Ghost” (","The Book of Mormon was published in Bulgarian in 1999, and meetinghouses were dedicated in Sofia and Plovdiv in 2000 and 2001. Bulgarian Saints have sought opportunities to build meaningful relationships in their communities. In 2003, a locally produced documentary about the lives of Saints in Bulgaria was shown on national television, and in 2014 Bulgarian Saints assisted in cleanup efforts following devastating flooding."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/bulgaria?lang=eng","asOf":"2025-12-31","id":"bulgaria","kind":"country","firstMissionaries":{"year":1900,"said":"After initial preaching efforts in 1900, the first Bulgarian converts to the Church joined overseas throughout the 20th century."},"began":null,"lat":42.607397,"lng":25.485662},{"name":"Croatia","members":739,"congregations":5,"wards":0,"branches":5,"missions":1,"temples":0,"capital":"Zagreb","languages":"Croatian","continent":"Europe","summary":["Throughout the 1900s, Croatian Latter-day Saints who embraced the restored gospel overseas returned to then-Yugoslavia to share their faith, establishing the gospel in their home country. Today Croatian Latter-day Saints continue to share their faith and serve in their communities."],"history":["In the early 1900s, a few Croatian converts who had joined the Church abroad returned to share the gospel in their homeland. John Stosich (also known as Janko Stošić), who was baptized in the United States, preached as a missionary in Zagreb in 1911. Eviza Arbić Vujičić, who was baptized in Hungary, returned to Yugoslavia in 1918, and she kept the faith in relative isolation until her death in 1937.","In 1971 another Croatian joined the Church abroad: basketball player Krešimir Ćosić embraced the restored gospel while a student at Brigham Young University. Later, over the course of his professional basketball career in Croatia, he was a shining example of how members of the Church strive to live. Ćosić helped translate the Book of Mormon into Serbo-Croatian, and he also helped secure permission for missionaries to enter Croatia.","The first branch in Croatia was organized in 1974 in Ćosić’s hometown of Zadar. The Church continued to spread to other cities, and a district was formed in 1980, with headquarters in Zagreb. In 2012 nearly 400 people from Croatia and its neighboring areas gathered near Zadar to commemorate the local history of the Church and to train leaders for its future."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/croatia?lang=eng","asOf":"2025-12-31","id":"croatia","kind":"country","firstMissionaries":{"year":1911,"said":"John Stosich (also known as Janko Stošić), who was baptized in the United States, preached as a missionary in Zagreb in 1911."},"began":null,"lat":45.365844,"lng":15.657521},{"name":"Cyprus","members":null,"congregations":5,"wards":0,"branches":5,"missions":null,"stakes":null,"districts":null,"familySearchCenters":4,"temples":null,"history":["By 1961, a small congregation of 20 servicemen and their families stationed at the British Akrotiri Sovereign Base began to meet to worship, forming the Nicosia Cyprus Group. The group was discontinued in 1969 after transfer of LDS servicemen from the base.","In May 1971, Switzerland Mission President M. Elmer Christensen visited southern Cyprus and reestablished the Nicosia Cyprus Group. This group held regular meetings for eight Latter-day Saints and participated in interdenominational protestant meetings, some of which were under the direction of LDS leaders.","During the next decade, several members of the Church emigrated to Cyprus, adding strength to the small congregation. In 1987, Elders James O. and Evelyn H. Henrie became the first missionaries to work in Cyprus. On September 10, 1989, 28 members gathered to witness the creation of the Nicosia Cyprus Branch (a small congregation) under the direction of Austria Vienna East Mission President Dennis B. Neuenshwander.","In February 1992, Georgia Philippou, a 67-year-old Greek Cypriot was baptized, becoming the first Cypriot member.","In 1997, there were 90 members of the Church in Cyprus meeting in branches in Nicosia and Limassol and another group of seven saints in Larnaca.","Contact","Adriatic South Mission Bulevardi Gjergj Fishta Tirana 1001 – Albania Phone +355 69 700 3484"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/cyprus","asOf":"","id":"cyprus","kind":"country","continent":"Europe","firstMissionaries":{"year":1987,"said":"In 1987, Elders James O. and Evelyn H. Henrie became the first missionaries to work in Cyprus."},"began":null,"lat":34.982302,"lng":33.145128},{"name":"Czech Republic","members":2628,"congregations":12,"wards":7,"branches":5,"missions":1,"temples":0,"capital":"Prague","languages":"Czech","continent":"Europe","summary":["The Church’s history in the Czech Republic began in 1884 with the arrival of the first missionary in Prague. Despite challenges, the Church grew significantly after World War I, and the resilience of Latter-day Saints through political upheaval underscores their enduring faith."],"history":["Thomas Biesinger, the first missionary in what is now the Czech Republic, arrived in Prague in February 1884—and was arrested for unauthorized preaching. After nearly 70 days in prison, Biesinger baptized his only convert, Anthon Just, before leaving the city.","Other Czechs in the Austro-Hungarian Empire joined the Church and returned to Czechoslovakia. After World War I, Františka Brodilová and her two daughters, who had joined the Church in Vienna, petitioned the Church to send missionaries to Prague. In 1928, Thomas Biesinger, now 84, traveled to Prague and obtained legal recognition for the Church. Czechoslovakia was soon dedicated, and the Czechoslovak Mission was organized.","Members kept the faith through the difficult days of World War II and after the rise of the Communist Party in 1948. In 1950, the Church was banned by the government. For nearly 50 years, Church members were not allowed to openly practice their faith. Nevertheless, Church members met as frequently as possible, becoming a unified and cohesive group, and found creative ways to share the gospel. Several members taught “Christian yoga” classes—a combination of gospel principles and yoga exercises—leading to the conversion of 130 people.","Since the reopening of the mission in 1991, membership in the Czech Republic has steadily grown. In 2016, the Prague Czech Republic Stake, the first in the Czech Republic, was created."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/czech-republic?lang=eng","asOf":"2021-12-31","id":"czech-republic","kind":"country","firstMissionaries":{"year":1884,"said":"The Church’s history in the Czech Republic began in 1884 with the arrival of the first missionary in Prague."},"began":null,"lat":49.743905,"lng":15.338106},{"name":"Denmark","members":4426,"congregations":21,"wards":13,"branches":8,"missions":1,"temples":1,"capital":"Copenhagen","languages":"Danish","continent":"Europe","summary":["The first Danish Latter-day Saints were baptized in the United States in 1842, and missionaries arrived in Denmark in 1850. The Book of Mormon was translated into Danish in 1851, producing the first non-English translation of the sacred text. In 2004 the Copenhagen Denmark Temple was dedicated."],"history":["A few Danes joined the Church in the United States during Joseph Smith’s lifetime. One of these converts, Peter Hansen, even began work translating the Book of Mormon into Danish. In 1849 Hansen and Elder Erastus Snow of the Quorum of the Twelve Apostles were called to open a mission in Scandinavia. The Copenhagen branch was organized shortly after their arrival in 1850. In 1851 the Danish translation of the Book of Mormon became the first edition of the book printed in a language other than English.","Most Danish converts in the 19th century emigrated to help build up Zion in the American West: in the 1850s and 1860s Latter-day Saints made up almost half of the total emigrants from Denmark, while many remained at home to build the Church. In 1906, for example, Frederick Samuelsen of Aarhus became the first Latter-day Saint elected to a European Parliament.","A wave of rapid growth in the 1960s helped the Church become more firmly established in Denmark, and the first stake was organized there in 1974. Since then, a faithful core of Saints have kept the faith. In 2004 a temple was dedicated in Copenhagen."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/denmark?lang=eng","asOf":"2025-12-31","id":"denmark","kind":"country","firstMissionaries":{"year":1842,"said":"The first Danish Latter-day Saints were baptized in the United States in 1842, and missionaries arrived in Denmark in 1850."},"began":null,"lat":55.670249,"lng":10.333328},{"name":"Estonia","members":1149,"congregations":4,"wards":0,"branches":4,"missions":0,"temples":0,"capital":"Tallinn","languages":"Estonian","continent":"Europe","summary":["Estonia was dedicated for the preaching of the gospel in 1990. As the Church grew there, members helped to translate Church materials such as temple ceremonies and the Book of Mormon into their own language. In 1999 leaders dedicated the Tallinn meetinghouse, making it the first meetinghouse in the Baltic States."],"history":["In 1989, as the Soviet Union relaxed travel restrictions, Valtteri Rötsä traveled from Estonia to Finland, met missionaries, and was baptized. He shared the gospel with relatives and friends, and a branch of the Church was soon organized in Tallinn. On April 25, 1990, Elder Russell M. Nelson of the Quorum of the Twelve Apostles dedicated Estonia for the preaching of the gospel in a wooded area above the Lauluväljak amphitheater.","On December 17, 1990, Jaanus Silla was called as a missionary—the first mission call issued to a Soviet citizen. During his mission, Estonia secured its independence from the Soviet Union, and Estonian Saints enjoyed more religious freedom. Over the course of the next 10 years, Estonian members helped translate Church materials and ordinances into their own language, including temple ceremonies, general conference addresses, and the Book of Mormon.","In 1999 the Church held a two-day open house for the Tallinn meetinghouse, the first Church-built meetinghouse in the Baltic States. In addition to the Tallinn Branch, branches have been established in Tartu, Narva, and Pärnu. Saints in Estonia serve as examples of how to lead committed religious lives in an increasingly secular culture."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/estonia?lang=eng","asOf":"2025-12-31","id":"estonia","kind":"country","firstMissionaries":{"year":1989,"said":"In 1989, as the Soviet Union relaxed travel restrictions, Valtteri Rötsä traveled from Estonia to Finland, met missionaries, and was baptized."},"began":null,"lat":58.752378,"lng":25.331908},{"name":"Finland","members":5024,"congregations":29,"wards":18,"branches":11,"missions":1,"temples":1,"capital":"Helsinki","languages":"Finnish","continent":"Europe","summary":["Latter-day Saints have been in Finland since 1875, when the first missionaries arrived from Sweden. A branch was established in Finland soon after, and the Helsinki Finland Temple was dedicated in 2006."],"history":["During the 1850s and ’60s, a small number of Finns living abroad joined The Church of Jesus Christ of Latter-day Saints. But it was not until 1875 that Church leaders granted a request from Finnish members to have missionaries sent to their relatives back home. The first of these missionaries were Swedish brothers Carl and Johan Sundström, who were sent from Sweden to preach in Vaasa, Finland, where the country’s first branch was soon established. Because Finland was part of the Russian Empire until 1917, legal and social conditions made preaching difficult, and only a few branches were organized before the end of World War II.","After the war, missionaries were trained in Finnish and assigned to cities around the country. Strong congregations with active youth programs quickly developed. In the 1950s, the Book of Mormon was published in Finnish, and Finnish Saints organized their first temple trip for the dedication of the Bern Switzerland Temple. About 20 years later, in 1977, the first stake in Finland was organized in Helsinki.","Finnish Saints had a unique opportunity to act as a light to others when the Soviet Union eased travel restrictions in the late 1980s, bringing Finnish members into contact with Estonians and Russians who found hope in their example of faith. Some were later called to support emerging congregations in the former Soviet Union. In 2006 Finnish Saints joined with fellow Saints from Estonia and Russia to celebrate the dedication of a temple in Helsinki."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/finland?lang=eng","asOf":"2025-12-31","id":"finland","kind":"country","firstMissionaries":{"year":1875,"said":"Latter-day Saints have been in Finland since 1875, when the first missionaries arrived from Sweden."},"began":null,"lat":63.246778,"lng":25.920916},{"name":"France","members":40546,"congregations":109,"wards":70,"branches":39,"missions":2,"temples":1,"capital":"Paris","languages":"French","continent":"Europe","summary":["After the first French Latter-day Saints were baptized in 1849, Church members supported one another and shared the gospel with friends and family, holding to their faith despite the challenges of mission closures, world wars, and economic hardships over the next century. During the 1960s, Church membership in France increased fivefold, and the Paris France Temple was dedicated in 2017."],"history":["When missionaries first arrived in France in 1849, they found interested listeners among religious dissenters and cultural outsiders. One early convert, Louis Bertrand, would lead the French Mission until it closed in 1864.","Missionaries returned to France in 1908, but world wars and economic hardship limited the Church’s presence for the next four decades. Faithful French Saints such as Léon Fargier and Eveline Kleinert helped carry the Church through the difficulties of World War II.","After the war, the Church established a stronger foundation in France. Church President David O. McKay announced that a temple in which ceremonies would be performed in French would be built in Switzerland, the Church gained legal recognition in France, and Church literature was translated and published in French. During the 1960s, Church membership increased fivefold as missionaries and members worked to spread the gospel. In 1975, the first stake in France was organized in Paris.","Since the 1970s, French Saints have prayed for a temple in their own country. In 2011, Thomas S. Monson, President of the Church, announced that a temple would be built near Paris. Members in the area held open houses to help their neighbors understand the temple project. The Paris France Temple was dedicated in May 2017."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/france?lang=eng","asOf":"2025-12-31","id":"france","kind":"country","firstMissionaries":{"year":1849,"said":"When missionaries first arrived in France in 1849, they found interested listeners among religious dissenters and cultural outsiders."},"began":null,"lat":46.603354,"lng":1.888334},{"name":"Georgia","members":null,"congregations":3,"wards":0,"branches":3,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Natives of Georgia, Roman and Nana Amirkhanashvili were baptized in Hanover, Germany in 1996. Shortly after their baptisms, they returned to Georgia. An American couple, John and Rebecca Dockery, who were working at the U.S. Embassy in T’blisi, met with the Amirkhanashvilis for Sunday worship services until returning to the United States in 1998. The Amirkhanashvilis eventually immigrated to the United States. However, Latter-day Saint involvement in Georgia goes back to the late 1980s.","Doris S. Platt, a Latter-day Saint living in Utah, befriended a Georgian woman, Maya Kavtatadze, who was visiting Utah in 1987. While visiting her Georgian friend in 1992, Platt became aware of Georgia’s meager and outdated firefighting equipment. She returned to Utah and was able to arrange for the donation of two retired fire trucks that were still in good working condition. National television broadcasts showed the fire trucks, with the Salt Lake City emblem still on the doors, responding to a bombing near Georgian President Eduard Shevardnadze’s car in 1995.","In June 1999, Philip and Betty Reber were assigned as the first missionary to serve in Georgia. They could not proselyte but served as humanitarian missionaries, answering questions about the Church when asked.","While the Rebers were in Georgia, they met Vazha Natroshvili, a Georgian who had been baptized in Holland some years before. They began holding worship meetings in their home. People asked the Rebers why they were in Georgia, which gave the couple an opportunity to talk about the Church. Since the Church was not registered in Georgia, the first converts, the Mamasakhlisi family and an Armenian, Hike Bagdasaryan, were baptized in Yerevan Armenia, the closest mission location in September 1999.","In September 2002, the T’blisi Branch (a small congregation) was organized. At the end of 2003, there were more than 60 Latter-day Saints in Georgia. Converts were now allowed to be baptized in Georgia, the first baptisms in Georgia were performed in September 2003."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/georgia","asOf":"","id":"georgia","kind":"country","continent":"Europe","firstMissionaries":{"year":1999,"said":"In June 1999, Philip and Betty Reber were assigned as the first missionary to serve in Georgia."},"began":null,"lat":32.329381,"lng":-83.113737},{"name":"Germany","members":42229,"congregations":146,"wards":97,"branches":49,"missions":5,"temples":2,"capital":"Berlin","languages":"German","continent":"Europe","summary":["In 1843 newly baptized German Latter-day Saints began preaching in Germany, and the Book of Mormon was published in German in 1852. Local members began overseeing German branches in 1868, and the Church continued to grow over the next century amid devastating wars and a global depression. The first temple in Germany was dedicated in Freiberg in 1985."],"history":["“There is a great work to be done in Germany,” wrote Elder Orson Hyde of the Quorum of the Twelve Apostles in 1840. Over the next decade, however, Hyde and other missionaries found little success preaching on German soil. In 1851 Elder John Taylor, George P. Dykes, and George Viett organized a small branch in Hamburg, and the Book of Mormon, translated by Dykes and Viett, was published in 1852. For nearly two decades many converts, fleeing harassment, moved to the United States; few Saints remained in Germany by the 1860s. In 1868 Karl G. Maeser, a convert from Dresden, became president of the Swiss and German Mission. Maeser called local members as branch leaders, began publishing","(a newspaper for German-speaking Saints), and established a permanent Church presence in Germany.","In the 20th century, amid the ravages of two world wars and a devastating global depression, the Church flourished in Germany. Some German Saints, seeking economic opportunity elsewhere, established branches in Europe and South America while many others stayed, supported one another, and accepted calls to preach the gospel. Through World War II and the dividing of the nation into East and West, Saints continued to congregate. Stakes were established and buildings constructed in both West and East Germany. Temples were dedicated in both Freiberg in the east and Frankfurt in the west before German reunification in 1990. German Saints continue to reach out in love and service to their neighbors and contribute to the leadership and development of the Church throughout the world."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/germany?lang=eng","asOf":"2025-12-31","id":"germany","kind":"country","firstMissionaries":{"year":1843,"said":"In 1843 newly baptized German Latter-day Saints began preaching in Germany, and the Book of Mormon was published in German in 1852."},"began":null,"lat":51.163818,"lng":10.447831},{"name":"Greece","members":818,"congregations":2,"wards":0,"branches":2,"missions":0,"temples":0,"capital":"Athens","languages":"Greek","continent":"Europe","summary":["The Church’s presence in Greece began in the 1890s. Though missionary work was suspended in 1909, many local members retained their faith, and Greek Latter-day Saints helped to reestablish the Church there in 1970."],"history":["Click here for the Church's Greece Newsroom site","In the early 1900s, Rigas Pofantis, a printer from Athens, sent a request to leaders of The Church of Jesus Christ of Latter-day Saints for information. The president of the Church's mission in Turkey taught Pofantis, who was baptized in October 1905.","The Church experienced little growth in Greece until the 1950s, when Greek-American Church members in Salt Lake City, Utah, organized the Hellenic Latter-day Saint Society to retain their heritage and maintain ties with their homelands. Latter-day Saints participated in a number of diplomatic exchanges over the following decades, including a visit to Greece by Church President Ezra Taft Benson. Church leaders organized a small congregation in Athens in 1965 and reorganized it in 1967. They established the Greece Athens Mission in July 1990 and completed construction of the first meetinghouse in Greece in May 1999.","In 2016, Elder D. Todd Christofferson of the Quorum of the Twelve and his wife, Katherine, visited Greece as part of a European tour. He stood on Mars Hill and read the account of Paul’s teachings as recorded in the New Testament.","Contact","Adriatic South Mission Bulevardi Gjergj Fishta Tirana 1001 – Albania Phone +355 69 700 3484"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/greece?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":2,"id":"greece","kind":"country","firstMissionaries":{"year":1909,"said":"Though missionary work was suspended in 1909, many local members retained their faith, and Greek Latter-day Saints helped to reestablish the Church there in 1970."},"began":null,"lat":38.995368,"lng":21.987713},{"name":"Guernsey","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["Click here for the Church's United Kingdom Newsroom site","For Journalist Use Only:","Malcolm Adcock Solihull, United Kingdom Phone: 44-121-712-1161"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/guernsey","asOf":"","id":"guernsey","kind":"country","continent":"Europe","firstMissionaries":null,"began":null,"lat":49.462291,"lng":-2.581202},{"name":"Hungary","members":5274,"congregations":19,"wards":5,"branches":14,"missions":1,"temples":0,"capital":"Budapest","languages":"Hungarian","continent":"Europe","summary":["Missionary work began in what was then Austria-Hungary in the early 1900s. The Book of Mormon was translated into Hungarian in 1991."],"history":["The first missionaries of The Church of Jesus Christ of Latter-day Saints to come to Hungary were elders Thomas Biessinger and Paul Hammer from the Swiss and German Mission, who arrived in 1885, but left after a month. The first known Hungarian citizen to be baptized was Mischa Markow from Hungary’s Banat region (now divided between Serbia and Romania), who joined the Church in 1887 while residing in Constantinople (now Istanbul). The first Hungarian member to serve a mission in Hungary was Elder Mihály Marjalaky (aka Michael Marialaky), a native of Debrecen, who had lived in the US since 1873 and joined the Church in Wyoming. He served in his home town in 1897-98. The following year Elder Markow returned to Hungary for a mission lasting three years. From the fall of 1900 he served in the Banat town of Temesvár (now Timișoara, Romania), baptizing many members, mostly ethnic Germans as well as some Hungarians. In 1901 the Church’s first congregation in Hungary was organized in the town, followed by one in the town of Brassó (now Brasov, Romania) in 1905. Proselytizing faced strong resistance from the authorities, and petitions to allow meetings and to recognize the Church were repeatedly rejected. Foreign missionaries preached mostly in German, but in 1909 Elder John Ensign Hill from Utah, serving in the Swiss-German Mission, was assigned to learn the language and serve a Hungarian-speaking mission. On 28 November 1909, he conducted the first LDS meeting held entirely in the Hungarian language, and on 10 January 1910, he performed the first baptism in Hungarian. In January 1911 authorities allowed the missionaries in Brassó to hold public meetings. In November of the same year the nation’s Supreme Court overturned lower court decisions against official recognition of the Church, thereby granting it a recognized status. This was apparently withdrawn in the following year. In March 1913 the Church decided to suspend Hungarian speaking missionary work in the country. By the time of World War I more than 100 members had been baptized in Hungary, but most of them subsequently emigrated to the United States. In 1914, at the start of the war the Church recalled its missionaries from Europe, including Hungary. Although several faithful members remained, organized activity ceased for more than seven decades. On April 19th 1987 President Russell M. Nelson, then a member of the Quorum of the Twelve Apostles, dedicated Hungary for missionary work in a prayer and a ceremony on Budapest's Gellert Hill. On June 1st 1988 The Church of Jesus Christ of Latter-day Saints received official recognition and the first missionaries arrived. Church activity has been uninterrupted ever since.","Hungary's first meetinghouse was dedicated in October 1989, by President Thomas S. Monson, a Counselor to the Church President, with President Nelson also attending. The Hungary Budapest Mission was created in June 1990. The nation’s first stake, the Budapest Hungary Stake was organized on June 4th 2006.","At the April 2019 General Conference of the Church, President Russell M. Nelson announced the construction of a temple in Hungary.","For Journalist Use Only:","National Director of Communication","Gábor Klinger","Telephone: +36 70 882 9262","Email"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/hungary?lang=eng","asOf":"2025-12-31","stakes":null,"districts":2,"familySearchCenters":12,"id":"hungary","kind":"country","firstMissionaries":{"year":1885,"said":"The first missionaries of The Church of Jesus Christ of Latter-day Saints to come to Hungary were elders Thomas Biessinger and Paul Hammer from the Swiss and German Mission, who arrived in 1885, but left after a month."},"began":null,"lat":47.181759,"lng":19.506094},{"name":"Iceland","members":445,"congregations":4,"wards":0,"branches":4,"missions":0,"temples":0,"capital":"Reykjavík","languages":"Icelandic","continent":"Europe","summary":["After the first branch of the Church in Iceland was established in 1853, the Church grew slowly despite the challenges of emigration and local opposition. The Book of Mormon was translated into Icelandic in 1981, and the first meetinghouse was dedicated in 2000."],"history":["Guðmundur Guðmundsson and Þórarinn Hafliðason, the first Latter-day Saint missionaries to preach in Iceland, were Icelanders who had recently converted in Denmark and returned to their homeland in 1851. After Þórarinn’s untimely death, Guðmundur preached alone for almost two years. In 1853, despite ongoing opposition, he organized a branch on the Westman Islands.","Although Icelanders continued to join the Church, immigration to North America sometimes left Iceland with no established branches. Recent converts often led the Church with the assistance of Icelandic members who returned as missionaries. Missionary work in Iceland was discontinued at the outset of World War I.","By the end of World War II, the Church had slowly rebuilt its presence in Iceland. US servicemen stationed near Keflavík formed a small congregation in 1945 and began preaching the gospel. Several missionaries from the Denmark Copenhagen Mission were reassigned to Iceland in 1975, and a branch was organized in Reykjavík the following year. The Book of Mormon was published in Icelandic in 1981, and the first meetinghouse constructed in Iceland was dedicated in 2000. A branch was organized in Selfoss in 2007.","Although the number of Church members in Iceland remains small, Icelandic Saints form a close-knit community."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/iceland?lang=eng","asOf":"2025-12-31","id":"iceland","kind":"country","firstMissionaries":{"year":1851,"said":"Guðmundur Guðmundsson and Þórarinn Hafliðason, the first Latter-day Saint missionaries to preach in Iceland, were Icelanders who had recently converted in Denmark and returned to their homeland in 1851."},"began":null,"lat":64.984182,"lng":-18.105901},{"name":"Ireland","members":4923,"congregations":12,"wards":6,"branches":6,"missions":0,"temples":0,"capital":"Dublin","languages":"English","continent":"Europe","summary":["The first Dublin branch was organized in 1850, though many of the earliest converts immigrated to Utah. The Irish Mission was established more than a century later, in 1962, leading to rapid growth, and the Dublin Ireland Temple was announced in 2024."],"history":["In 1840 Thomas Tate became the first Latter-day Saint convert in Ireland when he was baptized near Belfast by John Taylor of the Quorum of the Twelve Apostles. For much of the early history of the Church in Ireland, preaching was centered around Belfast. It was not until 1850 that Edward Sutherland, a native of Dublin who had been baptized in London, made the first sustained effort to preach in Dublin. Despite public ridicule during his preaching, Sutherland found some success and organized the first branch in Dublin in 1850. By 1856 there were over 200 Church members in Ireland, mostly in the north; however, many Church members from both the south and the north later emigrated. The Dublin Branch was closed in 1863.","Though many Irish emigrants joined the Church overseas, the Dublin Branch was reorganized in 1901 with mostly German immigrant members. At the time of Irish independence in 1922, these families and other converts made up a faithful core of Saints as a tiny minority in the country. The organization of the Irish Mission in 1962 led to a period of rapid growth during which the first Church-built meetinghouse was completed in 1971. The Dublin Ireland Stake was organized in 1995, and Church membership in Ireland surpassed 3,000 in 2012."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/ireland?lang=eng","asOf":"2025-12-31","id":"ireland","kind":"country","firstMissionaries":{"year":1850,"said":"It was not until 1850 that Edward Sutherland, a native of Dublin who had been baptized in London, made the first sustained effort to preach in Dublin."},"began":null,"lat":52.865196,"lng":-7.97946},{"name":"Isle of Man","members":null,"congregations":1,"wards":1,"branches":0,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["For Journalist Use Only","Malcolm Adcock Solihull, United Kingdom Phone: 44-121-712-1161"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/isle-of-man","asOf":"","id":"isle-of-man","kind":"country","continent":"Europe","firstMissionaries":null,"began":null,"lat":54.19368,"lng":-4.559115},{"name":"Italy","members":30105,"congregations":91,"wards":62,"branches":29,"missions":2,"temples":1,"capital":"Rome","languages":"Italian","continent":"Europe","summary":["Missionaries first preached the gospel in Italy in 1849. Though the Italy Mission was closed in 1867, it was reopened in 1966, with a nearly eightfold increase in membership between 1970 and 1980. The Rome Italy Temple was dedicated in 2019."],"history":["In 1843, Joseph Toronto (born Giuseppe Taranto) became the first known Italian convert to the Church when he was baptized in Boston, Massachusetts. In 1849, Toronto was among the first missionaries to his homeland when he accompanied Apostle Lorenzo Snow and others in opening the mission. This first mission was short-lived; it was closed in 1867.","In 1910, Vincenzo di Francesca gained a testimony of the Book of Mormon while living in New York City; he continued to live by its precepts after he returned to Italy in 1914, although he did not learn for years where the book came from. The Church was not reestablished in Italy until the 1950s, when a number of Italians learned of the gospel in other countries and returned home to share the message with friends and family. The first Italian-speaking branches were formed in Brescia and Palermo.","In 1966, the Italian Mission was reestablished with headquarters in Rome. Over the last 50 years, the Church has made steady progress. In 2008, when the Church announced a temple would be built in Rome, there were more than 20,000 members in Italy."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/italy?lang=eng","asOf":"2025-12-31","id":"italy","kind":"country","firstMissionaries":{"year":1849,"said":"Missionaries first preached the gospel in Italy in 1849."},"began":null,"lat":42.638426,"lng":12.674297},{"name":"Jersey","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Click here for the Church's United Kingdom Newsroom site","For Journalist Use Only","Malcolm Adcock Solihull, United Kingdom Phone: 44-121-712-1161"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/jersey","asOf":"","id":"jersey","kind":"country","continent":"Europe","firstMissionaries":null,"began":null,"lat":39.084846,"lng":-90.330334},{"name":"Latvia","members":1281,"congregations":4,"wards":0,"branches":4,"missions":1,"temples":0,"capital":"Riga","languages":"Latvian","continent":"Europe","summary":["Mischa Markow preached in Rīga in 1903, but a lasting Church presence in Latvia began only in 1992 with the first missionaries to the country. The first branch was organized the same year, and the Book of Mormon was translated into Latvian in 2001."],"history":["Although Mischa Markow preached the gospel in Rīga in 1903, a lasting Church presence in Latvia was not established until 1992, when Gvido and Velga Senkāns moved to Rīga, followed shortly by the first missionaries. On March 17, 1992, James E. Faust of the Quorum of the Twelve Apostles dedicated Latvia for the preaching of the gospel. Two months later, the first branch was organized.","Additional Latvian- and Russian-speaking branches were organized over the next decade. In 2001 the Book of Mormon was published in Latvian, and a ceremony was held for the groundbreaking of the first Church-constructed meetinghouse in the country. Latvian Saints have worshipped together, supported each other, and contributed to their communities through regular service projects, keeping their baptismal covenant to “comfort those that stand in need of comfort” (","). By 2019 there were roughly 1,000 Latter-day Saints in Latvia, with branches in Rīga, Liepāja, and Daugavpils."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/latvia?lang=eng","asOf":"2025-12-31","id":"latvia","kind":"country","firstMissionaries":{"year":1903,"said":"Mischa Markow preached in Rīga in 1903, but a lasting Church presence in Latvia began only in 1992 with the first missionaries to the country."},"began":null,"lat":56.840649,"lng":24.753764},{"name":"Lithuania","members":1024,"congregations":5,"wards":0,"branches":5,"missions":0,"temples":0,"capital":"Vilnius","languages":"Lithuanian","continent":"Europe","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Missionaries first preached in Lithuania in 1907, with renewed efforts in 1992. The country was first dedicated for missionary work in 1993, and in 2001 the Book of Mormon was translated into Lithuanian."],"history":["Members of The Church of Jesus Christ of Latter-day Saints in Lithuania are few but faithful. Their history has been one of isolation from Church leadership while gathering frequently as a small group to strengthen one another (see","In 1907 Latter-day Saint missionaries first preached in the modern territory of Lithuania in Memel, Germany (now Klaipėda, Lithuania). During the tumult of World War II, contact with the branch, which was established in 1909, was lost.","No Latter-day Saint missionaries preached in Lithuania while it was part of the Soviet Union. In the late 1980s, however, several Lithuanians were baptized in other countries and eventually returned to their home nation. Missionaries were reassigned to Lithuania in late 1992 after the country regained independence. While these first missionaries preached only in Russian, within six months, a program to train missionaries in both Russian and Lithuanian was started.","On May 20, 1993, Elder M. Russell Ballard of the Quorum of the Twelve Apostles traveled to Vilnius and dedicated the land for the preaching of the restored gospel. Since the dedication, the Church in Lithuania has experienced small but sustained growth. Latter-day Saints from Lithuania have served full-time missions, attended the temple, and witnessed the translation of the Book of Mormon into their own language."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/lithuania?lang=eng","asOf":"2025-12-31","id":"lithuania","kind":"country","firstMissionaries":{"year":1907,"said":"Missionaries first preached in Lithuania in 1907, with renewed efforts in 1992."},"began":null,"lat":55.35,"lng":23.75},{"name":"Luxembourg","members":null,"congregations":2,"wards":2,"branches":0,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["On November 19, 1963, Elders Hyrum M. Smith and Gerald E. Malmrose of the Franco-Belgian Mission went into the city of Luxembourg to help new missionaries there. They were there four days and left several missionaries in Luxembourg to get started in their labors.","A branch (a small congregation) was formed in the mid 1960s, and in 1965 Sunday meetings were conducted in the Hotel Kons. Attendance varied from one to three members and six missionaries. The branch remained small and struggled until it was discontinued in 1971.","In late 1989 more than 1,000 people from 23 countries attended a nine-day exhibition titled \"The Origin of Man\" at the Luxembourg municipal hall. The event was hosted by area Church members and full-time missionaries. Of the 1,000 guests, nearly 200 signed the visitors book, leading to the placement of 190 copies of the Book of Mormon: Another Testament of Jesus Christ. In about June 1994, Luxembourg became part of the newly created Metz France District, which was divided from the Nancy France Stake (diocese).","In January 2007, the Luxembourg Ward (larger congregation than a branch) was organized.","Contact","Communication Director","Matthieu Bennasar Phone: +33 (0) 6 85 68 92 29 Email"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/luxembourg","asOf":"","id":"luxembourg","kind":"country","continent":"Europe","firstMissionaries":{"year":1963,"said":"On November 19, 1963, Elders Hyrum M. Smith and Gerald E. Malmrose of the Franco-Belgian Mission went into the city of Luxembourg to help new missionaries there."},"began":null,"lat":49.815868,"lng":6.129675},{"name":"Malta","members":320,"congregations":1,"wards":0,"branches":1,"missions":0,"temples":0,"capital":"Valletta","languages":"Maltese","continent":"Europe","summary":["The Church began in Malta in 1852, with early branches serving members from the British military. Though missionary efforts were discontinued for more than a century, in 1988 missionaries returned and the Malta Branch was organized."],"history":["In February 1852, Apostle Lorenzo Snow and Jabez Woodard arrived on Malta and began to preach the gospel. That May, Ferndinanda Seiapati and Jean Alais Frouche were the first people baptized on the island. The following June, a branch (a small congregation) was organized. Most of the converts were British military personnel. Opposition surfaced, however, and many converts were threatened by military officials with loss of rank or punishment for their involvement in the Church. Many remained faithful, but others fell away.","In 1854, many branch members left Malta to serve in the Crimean War. Four mobile branches were organized to serve the members at war from the original branch in Malta. By 1856, however, the main branch was dissolved.","Thereafter, there is no known Church presence on Malta until the 1960s when Latter-day Saints, primarily with the British military, came to Malta. Most lived there temporarily, but by December 1968 an informal group was meeting, with meetings continuing until at least 1972.","Mission president Lino P. Gambarotto with Church legal counsel David Farnsworth went to Malta in September 1979. They met with government officials and learned that missionaries were welcome but that getting them permission to stay over extended periods of time would be difficult. The government of Malta granted permission for the Church to have missionaries there in January 1980.","Missionary work progressed and in December 1988 a branch (a small congregation) was organized. In early 1991, missionary work was interrupted due to anti-American demonstrations and the branch was discontinued, reopening in October 1991 with Emanuele D’Emanuele as the first native president. Missionaries returned in June 1993.","Contact","Communication Director","Remo Sicardi Phone: +39 351 710 3192 Email"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/malta?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":1,"id":"malta","kind":"country","firstMissionaries":{"year":1852,"said":"In February 1852, Apostle Lorenzo Snow and Jabez Woodard arrived on Malta and began to preach the gospel."},"began":null,"lat":35.931144,"lng":14.395163},{"name":"Moldova","members":null,"congregations":2,"wards":0,"branches":2,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Following the Soviet Union’s demise, Moldovans were able to travel abroad. During the mid-1990s a few joined the Church: Vitalii Volosin in Moscow, Russia; Sylvia Vacarciuc in Odessa, Ukraine; and Lilia Carasciuc in southern California.","In September 1995, Paul and Betty Morris arrived in Chisinau, where Paul worked in the U.S. Embassy. In June of that, John Nielson, a private contractor doing development work, arrived in Moldova. And in May 1996, Janet Jasen, a nurse with the Peace Corps, began her tour in Chisinau. These four Latter-day Saints met each week.","Elder Charles A. Didier, a member of the Seventy (one of the highest governing bodies of the Church) and Romania Bucharest Mission president, Robert F. Orton, traveled to Chisinau in September 1997 to meet with Moldovan and American Latter-day Saints and friends. It was announced that the first branch (a small congregation) was shortly to be organized and missionaries were to be assigned to labor in Moldova.","Five weeks after that visit, missionaries arrived in Chisinau. At that time, missionaries could not wear name tags or openly proselyte; rather, they provided service and taught people who had been referred to them by Church members or waited for people to ask them about the Church. On November 11 of that year, five people were baptized in the bathtub of the Morris home, the first baptisms in Moldova. On that same day, a branch was organized with Paul Morris as president.","On December 23, 1998, the first complete translation of the Book of Mormon in Romanian arrived. This “special Christmas gift” was a blessing to the majority of members who could now read the Book of Mormon in their native language."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/moldova","asOf":"","id":"moldova","kind":"country","continent":"Europe","firstMissionaries":null,"began":{"year":1995,"said":"In September 1995, Paul and Betty Morris arrived in Chisinau, where Paul worked in the U.S. Embassy."},"lat":47.287961,"lng":28.567094},{"name":"Montenegro","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["In September 2010, Russell M. Nelson, a member of the Quorum of the Twelve Apostles, and a small group of members assembled in the Roman ruins of Doclea and dedicated the land of Montenegro. Following the dedication, the first group of members was organized.","Contact","Adriatic North Mission Trg Petra Svacica 3/1 10000 Zagreb, Croatia Phone: +385 145 77 783"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/montenegro","asOf":"","id":"montenegro","kind":"country","continent":"Europe","firstMissionaries":null,"began":{"year":2010,"said":"In September 2010, Russell M. Nelson, a member of the Quorum of the Twelve Apostles, and a small group of members assembled in the Roman ruins of Doclea and dedicated the land of Montenegro."},"lat":42.775562,"lng":19.202242},{"name":"Netherlands","members":9027,"congregations":24,"wards":19,"branches":5,"missions":1,"temples":1,"capital":"Amsterdam","languages":"Dutch","continent":"Europe","summary":["Though Apostle Orson Hyde visited Jewish communities in the Netherlands in 1841, the first members of the Church were baptized in 1861. Many early converts immigrated to the United States, with some returning to the Netherlands to preach, and the Book of Mormon was published in Dutch in 1890. The Hague Netherlands Temple was dedicated in 2002."],"history":["Elder Orson Hyde visited Jewish communities in Rotterdam, Amsterdam, and The Hague in 1841. But it was not until 1861 that Elders Anne W. van der Woude and Paul A. Schettler baptized the first converts in the Netherlands. A few branches were established, but many early converts immigrated to the western United States to build up Latter-day Saint communities there and escape persecution. Some Dutch Saints returned to the Netherlands to preach the restored gospel. In 1890, the Book of Mormon was published in Dutch, leading to unprecedented growth for the Church in the country.","In a 1907 Christmas greeting to the Saints in the Netherlands, the First Presidency encouraged members and converts to stay and build up the Church in the Netherlands. During the two world wars, members continued to preach the gospel to their friends and neighbors despite limited contact with the Church headquarters. Dutch Saints worked to turn wartime tribulation into “the furtherance of the gospel” (","), and several future Church leaders were converted in a German prisoner-of-war camp.","After the war, Saints in the Netherlands modeled Christlike love and forgiveness when they sent their welfare crops to starving members in Germany. In 1961 the Holland Stake, the first in continental Europe, was organized in Rotterdam. Over the years, Dutch Saints have served their communities and neighboring countries. In 2002 The Hague Netherlands Temple was dedicated."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/netherlands?lang=eng","asOf":"2025-12-31","id":"netherlands","kind":"country","firstMissionaries":{"year":1890,"said":"Many early converts immigrated to the United States, with some returning to the Netherlands to preach, and the Book of Mormon was published in Dutch in 1890."},"began":null,"lat":52.243498,"lng":5.634323},{"name":"Norway","members":4547,"congregations":19,"wards":10,"branches":9,"missions":1,"temples":0,"capital":"Oslo","languages":"Norwegian","continent":"Europe","summary":["The Scandinavian Mission began in 1850, extending to Norway in 1851. Despite early opposition, thousands of people were baptized, though nearly half of them immigrated to the United States and helped build the Church in Utah. A temple in Oslo was announced in 2021."],"history":["Norway’s people have played a significant role in Church history since the 1840s. Norwegians who joined the Church in the United States joined the first pioneer companies to reach the Salt Lake Valley. Three years later, in 1850, the Scandinavian Mission became one of the first missions in which missionaries taught the gospel in a language other than English. Hans F. Petersen, a Dane, extended the mission’s work into Norway in 1851. Though the government refused to recognize the Church, and the early Saints in Norway faced significant opposition, thousands joined the Church in Norway throughout the late nineteenth century.","Nearly half of those early members immigrated and helped build up the Church in Utah and the surrounding areas. One immigrant, John A. Widtsoe, later became a member of the Quorum of the Twelve Apostles and served for three decades. Other members remained in Norway and helped keep a continual Church presence there, though the development of Church organizations was limited.","In August 1946, the Norwegian government granted the Church permission to preach in Norway. The government granted the Church official registration as a religious denomination in 1988. Now, with two stakes and 22 congregations, the Church is firmly established in Norway.","From average members living their religion daily to leaders in the highest councils, Norwegian Latter-day Saints have deeply influenced the Church. Theirs is a story of perseverance, conviction, and continuing in the faith (see"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/norway?lang=eng","asOf":"2025-12-31","id":"norway","kind":"country","firstMissionaries":{"year":1850,"said":"Three years later, in 1850, the Scandinavian Mission became one of the first missions in which missionaries taught the gospel in a language other than English."},"began":null,"lat":61.152939,"lng":8.787665},{"name":"Poland","members":2315,"congregations":11,"wards":0,"branches":11,"missions":1,"temples":0,"capital":"","languages":"Continent","continent":"Europe","summary":["In the late 19th century missionaries from the Swiss-German Mission preached in modern Poland, leading to 2,500 new members of the Church. Despite challenges during the Second World War, the Church persisted, gaining official recognition in the 1960s. The Poland Warsaw Mission was established in 1990, with steady growth since."],"history":["Beginning in the late 19th century, missionaries from the Swiss-German Mission began preaching the gospel in the territory of modern Poland. These early efforts led to nearly 2,500 converts and the establishment of a district with several branches in an area that was part of the German Empire. In the early 1920s, another branch in the small town of Selbongen (later Zełwągi) was established.","Toward the end of World War II when Soviet troops advanced into Poland, many branches were closed as members fled to Germany. The members of the Zełwągi Branch, however, continued to work together to live the gospel and maintain a presence in the country. The branch functioned as a Church center in the country, even when restrictions on communication and travel limited contact with the broader Church. In the 1960s and 1970s, the Church was officially recognized by the Polish government and began to establish branches in other places.","Despite being at the center of many of the most difficult geopolitical events of the 20th century, the faithful Polish Saints persevered through faith and prayer, championing the gospel cause (see","). Since the 1980s, the Church in Poland has grown slowly but steadily. In 1990, the Poland Warsaw Mission was established, and in 2016, Mateusz Turek, a native of Poland, and his wife, Adrienne, were called to preside over the mission."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/poland?lang=eng","asOf":"2025-12-31","id":"poland","kind":"country","firstMissionaries":null,"began":{"year":1990,"said":"The Poland Warsaw Mission was established in 1990, with steady growth since."},"lat":52.215933,"lng":19.134422},{"name":"Portugal","members":50341,"congregations":64,"wards":47,"branches":17,"missions":2,"temples":1,"capital":"","languages":"Continent","continent":"Europe","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","After religious freedom was established in Portugal in 1974, missionaries began preaching, and a branch was organized in Lisbon in 1975. By 1980 there were over 1,000 members of the Church in Portugal. The first stake was established in 1981, and the Lisbon Portugal Temple was dedicated in 2019."],"history":["In April 1974, the people of Portugal took to the streets to demand a new form of government. The success of the nonviolent Carnation Revolution soon led to the beginning of religious freedom in the country, allowing Latter-day Saints to begin missionary efforts there for the first time. Church leaders acted quickly, transferring missionaries to Portugal from Brazil. In 1975, a branch was organized in Lisbon, and Elder Thomas S. Monson, then of the Quorum of the Twelve Apostles, dedicated the country for the preaching of the gospel.","Portugal proved to be like the “good ground” in Jesus’s parable of the sower (see","), with many taking the gospel fully into their lives and sharing it freely. By 1980, there were over 1,000 members in the country, with Church branches in Lisbon, Porto, Coimbra, Viseu, and the Azores. The Lisbon stake, the first in Portugal, was organized in 1981. By 2000, Portugal had five stakes and over 35,000 Church members, giving it a higher concentration of Latter-day Saints than almost any other European country. In 2010, Church President Thomas S. Monson announced that a temple would be built in Lisbon."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/portugal?lang=eng","asOf":"2025-12-31","id":"portugal","kind":"country","firstMissionaries":{"year":1974,"said":"After religious freedom was established in Portugal in 1974, missionaries began preaching, and a branch was organized in Lisbon in 1975."},"began":null,"lat":39.662165,"lng":-8.135352},{"name":"Romania","members":3127,"congregations":15,"wards":0,"branches":15,"missions":1,"temples":0,"capital":"","languages":"Continent","continent":"Europe","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","The first Romanian branches were established in 1899, though no Church members remained after the 1930s. In 1989, after years of political upheaval, Church leaders offered humanitarian aid to the country, and a branch was established in Bucharest in 1991. By 2000 branches existed in multiple cities, and members were actively serving their communities."],"history":["Beginning in 1899, Mischa Markow, a Latter-day Saint missionary with a Romanian mother, preached in what is now Romania and established branches in Bucharest, Timişoara, and Braşov. However, no members are known to have remained in the country after the 1930s. After the regime of Nicolae Ceaușescu was overthrown in 1989, Church leaders visited Romania to offer humanitarian assistance. Latter-day Saints around Europe and in other parts of the world participated in extended efforts to help. At the same time, a few Romanians felt drawn to the restored gospel, and in 1991, a branch in Bucharest was established.","The Church soon spread beyond Bucharest: by 2000, there were also branches in Constanța, Piteşti, Ploieşti, Arad, Timişoara, Cluj-Napoca, Oradea, Sibiu, Bacău, Braşov, Galați, and Iaşi. In early 2001, young Romanian Latter-day Saints gathered for a countrywide youth conference for the first time. In the Church, members found a place of encouragement and support in times of trial, such as after the 2006 flooding on the Danube. Following Jesus’s counsel to give as freely as they had received (see","), Romanian members reached out to others in service, especially as the number of refugees in Europe increased after 2015."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/romania?lang=eng","asOf":"2025-12-31","id":"romania","kind":"country","firstMissionaries":{"year":1899,"said":"Beginning in 1899, Mischa Markow, a Latter-day Saint missionary with a Romanian mother, preached in what is now Romania and established branches in Bucharest, Timişoara, and Braşov."},"began":null,"lat":45.985213,"lng":24.685923},{"name":"Russia","members":18306,"congregations":51,"wards":11,"branches":40,"missions":3,"temples":0,"capital":"Moscow","languages":"Russian","continent":"Europe","summary":["Missionaries were called to Russia in 1843. After more than a century, congregations were formed in 1990, and Moscow’s first stake was established in 2011."],"history":["As many Russians sought renewed spirituality in their lives in the late 1980s, some found answers in the teachings of The Church of Jesus Christ of Latter-day Saints. In 1990 these Russians formed the first Russian Latter-day Saint congregations in St. Petersburg and Vyborg. Over the course of the 1990s, other congregations were established across the country, from Kaliningrad to Vladivostok. In 2011 the Church’s first stake in Russia was organized in Moscow.","Yet the Church’s ties with Russia go back further. Joseph Smith called missionaries to Russia in 1843, and Church leaders visited the country in 1866. In 1895 the Lindlöf family joined the Church in St. Petersburg. Starting in the 1920s, Russian emigrants translated Church literature to share with Russian-speaking people. In 1903 and 1990, Elders Francis M. Lyman and Russell M. Nelson of the Quorum of the Twelve, respectively, offered special prayers for Russia and its people.","Russian Latter-day Saints inherited this modern legacy of faith in addition to their country’s own rich religious heritage. Moving forward in faith, they build upon this past as they strengthen each other and their communities. In their lives as Christians and citizens of their country, Russian Latter-day Saints have proven to be “example[s] of the believers” in our day ( 1 Timothy 4:12 ).","For Journalist Use Only","Boris Leostrin","Director of the Church Communication Department","leostrinboris@churchofjesuschrist.org"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/russia?lang=eng","asOf":"2025-12-31","stakes":null,"districts":4,"familySearchCenters":null,"id":"russia","kind":"country","firstMissionaries":{"year":1843,"said":"Missionaries were called to Russia in 1843."},"began":null,"lat":64.686314,"lng":97.745306},{"name":"Serbia","members":422,"congregations":1,"wards":0,"branches":1,"missions":0,"temples":0,"capital":"Belgrade","languages":"Serbian","continent":"Europe","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Adriatic North Mission Communication Director","Though early preaching in Serbia dates back to 1899, the Church was not established there until the 1970s and 1980s. The first branch was organized in 1983, and the Church continued to grow, with the first district created in 1992."],"history":["Mischa Markow, a convert from Vojvodina, briefly preached in Beograd and Zrenjanin in 1899, but the first Church member to settle in Serbia was Eviza Arbić Vujičić, who moved to Beograd in 1918 after being baptized in Budapest, Hungary. In part through Vujičić’s efforts to help teach the gospel, in 1933 Matej Spaček became the first person baptized in Serbia.","The Church did not become fully established in Serbia, however, until the 1970s and 1980s. Krešimir Ćosić, who had joined the Church at Brigham Young University, helped spread the gospel during his basketball career in Yugoslavia. In Beograd, Radmila Ranović became the first person living in Yugoslavia to serve a full-time mission. The first branch in Serbia was organized in Beograd in 1983, shortly after Ranović’s return.","The branch developed into a district by 1992 as the work began to spread beyond Beograd. In their branches and in their own lives, Latter-day Saints in Serbia followed Christ’s call to build “upon the foundation of my gospel and my rock” as a protection against evil (","). Over the following decade, as Saints in Serbia witnessed warfare and endured bombing campaigns, their fellow Saints around Europe worked to deliver aid to their country. By 2002 both proselytizing and humanitarian missionaries had returned to Serbia to serve in the branches in Beograd, Novi Sad, and Sremska Mitrovica."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/serbia?lang=eng","asOf":"2025-12-31","id":"serbia","kind":"country","firstMissionaries":{"year":1899,"said":"Though early preaching in Serbia dates back to 1899, the Church was not established there until the 1970s and 1980s."},"began":null,"lat":44.024323,"lng":21.076574},{"name":"Slovakia","members":334,"congregations":4,"wards":0,"branches":4,"missions":0,"temples":0,"capital":"Bratislava","languages":"Slovak","continent":"Europe","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Director of Public Affairs and Communications","The Czechoslovak Mission opened in 1929, focusing on Czech-speaking cities. Slovaks shared the gospel with friends and family despite challenges, and the Book of Mormon was published in Slovak in 2013."],"history":["The Czechoslovak Mission opened on July 24, 1929. Most missionary work initially took place in Czech-speaking cities. During the Communist era, Slovaks learned about the Church when Latter-day Saint Otakar Vojkůvka, his family, and others began teaching “Christian yoga” classes. They combined principles of the gospel of Jesus Christ with yoga exercises. By 1993, when Slovakia and the Czech Republic separated, there were 20 to 30 members in Slovakia.","When Slovakia and the Czech Republic separated, a procedural error left the Church without official recognition in Slovakia. With fewer than 200 members in the country, the Church needed 20,000 Slovakian citizens to sign a petition supporting its application for registration. The task seemed insurmountable. In 2006, members, missionaries, and Church leaders joined in faith to gather the necessary signatures in just seven days. Elder David A. Bednar of the Quorum of the Twelve Apostles called this miracle the “dawning of a brighter day.”","Since 2006, the Church has become more firmly planted in Slovakia. In 2013, the Book of Mormon was published in Slovak. Two years later, the Bratislava District was created. Latter-day Saints in Slovakia have faced their challenges with faith in the Lord."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/slovakia?lang=eng","asOf":"2025-12-31","id":"slovakia","kind":"country","firstMissionaries":{"year":2006,"said":"In 2006, members, missionaries, and Church leaders joined in faith to gather the necessary signatures in just seven days."},"began":null,"lat":48.741152,"lng":19.452865},{"name":"Slovenia","members":466,"congregations":2,"wards":0,"branches":2,"missions":0,"temples":0,"capital":"Ljubljana","languages":"Slovenian","continent":"Europe","summary":["Early preaching in Slovenia in the early 20th century found little success. Missionary work officially began in 1978, and by 1992 the first branches were established. The Book of Mormon was published in Slovene in 2002."],"history":["In 1911 John Stosich became the first Latter-day Saint missionary to preach the restored gospel of Jesus Christ in Slovenia. But no one joined the Church during Elder Stosich’s stay in Ljubljana. Five decades later, Maria Gruden’s son joined the Church abroad. Maria learned about her son’s religion and joined The Church of Jesus Christ of Latter-day Saints in 1968 (becoming the only member in Ljubljana). Maria spent many faithful years in isolated devotion to the gospel. She made irregular trips to branch meetings in Klagenfurt, Austria, and on occasion received visits from Church members from other areas.","Missionary work officially began in Yugoslavia in 1978, but missionaries were not specifically assigned to Ljubljana until 1990. Saints in Slovenia welcomed the missionaries’ arrival. By then, several converts living in Slovenia were making regular trips to Klagenfurt to attend Church meetings. Saints helped missionaries make contacts, find accommodations, and translate Church materials into Slovene.","Between 1990 and 1992, branches were established in Ljubljana, Celje, and Maribor, and a district was organized. In 2002 the Book of Mormon was published in Slovene, and in 2017 the Slovene translation of the Doctrine and Covenants and Pearl of Great Price was announced."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/slovenia?lang=eng","asOf":"2025-12-31","id":"slovenia","kind":"country","firstMissionaries":{"year":1911,"said":"In 1911 John Stosich became the first Latter-day Saint missionary to preach the restored gospel of Jesus Christ in Slovenia."},"began":null,"lat":46.119944,"lng":14.815333},{"name":"Spain","members":71995,"congregations":150,"wards":95,"branches":55,"missions":3,"temples":1,"capital":"Madrid","languages":"Spanish (Spain)","continent":"Europe","summary":["The earliest Latter-day Saints in Spain joined the Church in the 1950s and 1960s. Despite various challenges, the Church in Spain grew, gaining recognition in 1968. The Madrid Spain Temple was dedicated in 1999, and the Barcelona Spain Temple was announced in 2022."],"history":["In 1874, Melitón González Trejo, an officer in the Spanish army, came to Utah to learn more about the “group of Saints” he had heard about from a fellow officer. He was soon baptized and became influential to the work of translating the Book of Mormon into Spanish, which opened doors to the preaching of the gospel in Latin America.","The first members of the Church in Spain were baptized during the 1950s and 1960s. At that time, non-Catholic religious ceremonies were illegal, so most converts traveled to France to be baptized. The Church in Spain grew as new members shared the gospel with their family and friends. After the law granting religious freedom was passed in 1967, an independent Spanish branch was organized in Madrid. The Church was legally recognized in October 1968.","Today, more than 59,000 Saints across Spain are “remembering without ceasing [their] work of faith, and labour of love” (","). They have been honored by their communities for their examples of service and faith, and they actively advance the work of the Lord by sharing the gospel and serving in the temple."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/spain?lang=eng","asOf":"2025-12-31","id":"spain","kind":"country","firstMissionaries":null,"began":{"year":1874,"said":"In 1874, Melitón González Trejo, an officer in the Spanish army, came to Utah to learn more about the “group of Saints” he had heard about from a fellow officer."},"lat":39.326068,"lng":-4.837979},{"name":"Sweden","members":9569,"congregations":38,"wards":25,"branches":13,"missions":1,"temples":1,"capital":"Stockholm","languages":"Swedish","continent":"Europe","summary":["The first missionary efforts in Sweden were in 1850. Despite early opposition, the Church grew rapidly, with branches established by 1860. The Swedish Mission was organized in 1905, and the first stake was organized in 1975. The Stockholm Sweden Temple was dedicated in 1985."],"history":["John E. Forsgren, a Swede who had joined the Church in Boston in 1843, returned as the first missionary to his homeland in 1850. Despite intense early opposition, the restored gospel spread quickly, and by 1860 there were branches of the Church spread around the country. Many early converts immigrated to Utah to help build up new Latter-day Saint settlements there, but they and their children maintained ties to Sweden and often returned as missionaries.","In the early 1900s, emigration from Sweden declined, and Latter-day Saint congregations gained new strength. In 1905, the Swedish Mission was organized, with Peter Matson, a Swedish convert, as president. As the Church grew, however, so too did opposition. Persistent false accusations of plural marriage prompted the Riksdag (parliament) to consider funding a public awareness campaign opposing the Church and, in 1920, to temporarily discontinue visas for Latter-day Saint missionaries. Despite this, members persisted in sharing the gospel, meeting together often, and strengthening one another (see","). By the mid-20th century, branches had been reestablished throughout Sweden. In 1975, the first stake in Sweden was organized in Stockholm.","Throughout their history, Swedish Saints have provided strength and support for members across Europe. In 1966, Festinord, an annual conference attended by young adult members from Sweden, Denmark, Norway, and Finland, was first held in Stockholm. Since the dedication of the Stockholm Sweden Temple, the first in Scandinavia, in July 1985, Saints from throughout northern and eastern Europe have traveled to Stockholm to participate in temple ordinances."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/sweden?lang=eng","asOf":"2025-12-31","id":"sweden","kind":"country","firstMissionaries":{"year":1843,"said":"John E. Forsgren, a Swede who had joined the Church in Boston in 1843, returned as the first missionary to his homeland in 1850."},"began":null,"lat":59.674971,"lng":14.520858},{"name":"Switzerland","members":9630,"congregations":34,"wards":26,"branches":8,"missions":0,"temples":1,"capital":"Bern","languages":"German","continent":"Europe","summary":["After the first missionary efforts in Switzerland began in 1851, hundreds joined the Church. Many immigrated to Utah, though those who remained built a strong legacy of faith. The first European temple was dedicated in Bern, Switzerland, in 1955, and the first stake was organized in Zürich six years later"],"history":["In November 1850 Lorenzo Snow, then an Apostle preaching in Italy, sent his missionary companion, Thomas B. H. Stenhouse, over the Alps to preach in Switzerland. The next March, the first converts in Switzerland were baptized. Over the next 10 years, hundreds were baptized in Switzerland’s French- and German-speaking cantons. Later many immigrated to the United States to help build Zion in Utah.","Other converts remained in Switzerland. In the early 20th century, Swiss Latter-day Saints were faithful during the disruptions caused by world wars in neighboring countries. In 1955 the first temple in Europe was dedicated in Bern, Switzerland. Latter-day Saints from many nations were taught and blessed in this temple.","The first stake in Switzerland was organized in Zürich six years later. Swiss Latter-day Saints played a key role in spreading the gospel, helping reopen missionary work in Italy in the 1960s, and administering branches in the Middle East. In 1982 the first French-speaking stake in Switzerland was organized in Geneva, and by the year 2000 there were over 7,000 Latter-day Saints in Switzerland."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/switzerland?lang=eng","asOf":"2025-12-31","id":"switzerland","kind":"country","firstMissionaries":{"year":1850,"said":"In November 1850 Lorenzo Snow, then an Apostle preaching in Italy, sent his missionary companion, Thomas B. H. Stenhouse, over the Alps to preach in Switzerland."},"began":null,"lat":46.798562,"lng":8.231974},{"name":"Turkey","members":null,"congregations":7,"wards":0,"branches":7,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["Early leaders of The Church of Jesus Christ of Latter-day Saints preached in Turkey in 1850, recognizing present-day Ephesus as the New Testament home of the Christian congregation to which Paul, Timothy and John belonged. In May 1854, Latter-day Saints organized a congregation in Turkey. It consisted of British Latter-day Saint soldiers who, along with allied forces from Turkey and France, fought against Russia in the Crimean War.","In 1884, the Church established the Turkish Mission and sent Jacob Spori, born in the Swiss Alps, to preach in Turkey. Three months after arriving in Istanbul and teaching himself the Turkish language, Spori began preaching. While there, he also taught English, French and German. Mischa Markow, a Hungarian living in Istanbul, joined the Church in 1887. After his baptism, he returned to Hungary to preach. In September 1889, the first Armenian converts were baptized in Aintab. For many years Church growth in Turkey was slow but efforts during recent decades have led to the organization of several new congregations. The first of these was organized in Ankara in October 1979. In 1991 the Church sent an estimated 13,000 blankets, 80,000 pounds of clothing, and funds for medical supplies to aid Kurdish refugees in Turkey."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/turkey","asOf":"","id":"turkey","kind":"country","continent":"Europe","firstMissionaries":{"year":1850,"said":"Early leaders of The Church of Jesus Christ of Latter-day Saints preached in Turkey in 1850, recognizing present-day Ephesus as the New Testament home of the Christian congregation to which Paul, Timothy and John belonged."},"began":null,"lat":39.294076,"lng":35.231663},{"name":"Ukraine","members":10014,"congregations":41,"wards":11,"branches":30,"missions":2,"temples":1,"capital":"Kyiv","languages":"Ukrainian","continent":"Europe","summary":["The first Latter-day Saint missionaries arrived in Ukraine in 1990. The Church grew from a small branch worshipping in a rented hall in 1991, and in 2010 the Kyiv Ukraine Temple was dedicated. In 2004 Kyiv became the first city in Eastern Europe to have an organized stake"],"history":["When the Kyiv Ukraine Temple was dedicated, nearly 20 years had passed since the arrival of the first missionaries to Kyiv in October 1990. In 1991 a small branch of Ukrainian Saints gathered in a rented hall in Kyiv. From those obscure beginnings, the Church in Ukraine grew in number and in faith across the country as the Saints there lived the gospel in small and simple ways. Like early Church members, Ukrainian Saints witnessed how “out of small things proceedeth that which is great” (","Living the gospel not only changed their lives but also transformed the Church. Branches of the Church were established in nearly every major city. Attending the temple in Germany, the Saints found spiritual strength in making covenants with God. In 2004 the first stake of the Church in eastern Europe was organized in Kyiv.","On August 28, 2010, thousands of Saints crowded into the National Palace of Arts Ukraine in Kyiv to watch performers from seven countries across eastern Europe join in dance and song to celebrate the completion of the Kyiv Temple, the first temple in eastern Europe. The next day, the temple was dedicated in several sessions broadcast to Saints throughout the region. For many present, it was also a time to reflect on the past and ponder the future of the Church. Since the temple dedication in 2010, Ukrainian Saints have continued on the gospel path and made the Church more widely known and respected."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/ukraine?lang=eng","asOf":"2025-12-31","id":"ukraine","kind":"country","firstMissionaries":{"year":1990,"said":"The first Latter-day Saint missionaries arrived in Ukraine in 1990."},"began":null,"lat":49.487197,"lng":31.271832},{"name":"United Kingdom","members":190066,"congregations":298,"wards":257,"branches":41,"missions":6,"stakes":null,"districts":null,"familySearchCenters":121,"temples":2,"history":["The first missionaries to go overseas were sent to Britain in 1837, only seven years after the Church was founded. A total of seven missionaries were sent, including two members of the Quorum of the Twelve Apostles (the highest governing body of the Church). The group arrived in England on July 19, 1837, preached in Preston on July 23, and held baptismal services for nine new converts on July 30 before an audience of more than 8,000 curious onlookers. By the next week, 50 more converts were baptized. The teachings of the Church attracted more than a thousand converts in the first few years in the United Kingdom, despite mounting opposition from ministers and the press.","Between 1837 and the turn of the century, as many as 100,000 converts emigrated to join the main body of the Church in the United States. In fact, by 1870 nearly half of the population of Utah were British immigrants. Missionary work in the United Kingdom has continued to be successful in the 20th century despite setbacks during World War I and World War II. In the 1950s, Church membership in Britain increased as Church leaders encouraged new members to avoid further mass emigration and to build the Church in their native lands.","In the late 1950s, a temple was dedicated in London. In June 1998, another temple was opened in Preston, the site of the first preaching more than 150 years ago. Preston is the home of the oldest continuous branch (a small congregation) of the Church anywhere in the world, dating back to 1837.","In April 2000, the rebuilt Gadfield Elm Chapel, the oldest chapel of the Church of Jesus Christ in England, was rededicated by Jeffrey R. Holland of the Quorum of the Twelve Apostles.","In July 2012, the historic Hyde Park Chapel in London has been rededicated after remodeling for worship services and as a visitor’s center. The building was rededicated by Erich W. Kopischke, General Authority Seventy and President of the Church in Europe.","The first official Church Pageant outside of North America was hosted in the United Kingdom in July 2013. The British Pageant titled “Truth will prevail” was performed in the grounds of the Preston Temple. Jeffrey R. Holland from the Quorum of the Twelve Apostles visited the United Kingdom in June 2015. During his visit, he addressed the All-Party Parliamentary Group on Foreign Affairs in the House of Lords. He also met with missionaries and spoke at a devotional to young single adults of the Church.","In September 2016, Elder Holland was invited by Baroness Emma Nicholson to participate and speak at a conference at Windsor Castle addressing religious persecution and its role in forced migration.","In June 2017, D. Todd Christofferson of the Quorum of the Twelve Apostles spoke to students, faculty and academics at the University of Oxford about ethical conscience and integrity relating to his experiences as a law clerk during the Watergate trials more than 40 years ago. M. Russell Ballard of the Quorum of the Twelve Apostles visited, among other global church leaders, the United Kingdom in August 2017 to celebrate the 180th anniversary of the opening of the Church’s first mission to the British Isles. He attended the second British Pageant which was part of the celebrations.","In October 2019, RootsTech held its first ever family discovery conference outside of Salt Lake City, Utah at the ExCeL Convention Centre in London. A total of 42 countries was represented with nearly 10.000 attendees from around the world. Among the special guests were David A. Bednar and Quentin L. Cook of the Quorum of the Twelve Apostles accompanied by their wives Susan Bednar and Mary Cook. Among the Keynote Speakers were Dan Snow, British historian and television presenter, Paralympic gold medallist Kadeena Cox and Entertainer Donny Osmond.","For Journalist Use Only","Malcolm Adcock Europe Area Public Affairs Office United Kingdom Phone: +44 (0)121 712 1161 Mobile: +44 (0)7801 685 258"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/united-kingdom","asOf":"","id":"united-kingdom","kind":"country","continent":"Europe","firstMissionaries":{"year":1837,"said":"The first missionaries to go overseas were sent to Britain in 1837, only seven years after the Church was founded."},"began":null,"lat":54.702354,"lng":-3.276575},{"name":"Bahrain","members":231,"congregations":1,"wards":1,"branches":0,"missions":0,"temples":0,"capital":"Manama","languages":"Arabic","continent":"Asia","summary":["Since the 1970s Latter-day Saints from other countries have lived and worshiped in Bahrain. The Manama Bahrain Stake consists of mostly emigrant members currently residing in Bahrain and other countries in the Middle East."],"history":["Since the 1970s, Latter-day Saints have lived and worshiped in Bahrain. The Manama Bahrain Stake has been organized to accommodate members from outside the country who currently reside in Bahrain. In May 2024, Elder Anthony D. Perkins, president of the Middle East/Africa North Area of the Church, and his wife, Christine Dee Abbott Perkins, met with His Excellency Dr. Shaikh Abdullah bin Ahmed Al Khalifa, the undersecretary of the Ministry of Foreign Affairs. The meeting focused on possibilities for future interfaith collaboration and initiatives in the Kingdom of Bahrain, a Muslim majority country where religious tolerance and appreciation are prioritized."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/bahrain?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":null,"id":"bahrain","kind":"country","firstMissionaries":null,"began":{"year":2024,"said":"In May 2024, Elder Anthony D. Perkins, president of the Middle East/Africa North Area of the Church, and his wife, Christine Dee Abbott Perkins, met with His Excellency Dr. Shaikh Abdullah bin Ahmed Al Khalifa, the undersecretary of the Ministry of Foreign Affairs."},"lat":26.155125,"lng":50.534461},{"name":"Cambodia","members":18070,"congregations":30,"wards":9,"branches":21,"missions":2,"temples":0,"capital":"Phnom Penh","languages":"Khmer","continent":"Asia","summary":["Many Cambodian refugees joined the Church in the United States before returning to their homeland in the 1990s. Missionary work resumed in 1994, and the first two Cambodian stakes were organized in 2014."],"history":["When the Cambodian Civil War began in 1970, the small group of Latter-day Saints who had been holding meetings in their homes left. The war lasted more than two decades and led to widespread violence and famine. Millions of Cambodian citizens died, and thousands fled to refuge in Thailand, France, and the United States. In the United States, many Cambodian refugees met Latter-day Saints, learned the gospel, and accepted baptism. By the 1990s, more than 20 Khmer-speaking branches had beenestablishedin seven US states.","After the fighting ended and a peace agreement was reached, many Cambodian Saints returned to their homeland. In 1994, the Church began holding meetings and preaching the restored gospel in Cambodia. In September of that year, the first","in Phnom Penh was organized with both Cambodian and Vietnamese members. Local members worked with missionaries to deliver food and clothing to rural villages affected by droughts in January 1995 and in February, senior missionaries began working with the Royal Agricultural University to teach agricultural science classes.","A district was organized in 2000, led by the first local","president, with branches in Phnom Penh, Takmau, and Kampong. In 2002, a district for Vietnamese-speaking members in Cambodia was organized with branches throughout the country. Cambodian Saints have hosted a variety of cultural events, participated in Church-wide art competitions, and volunteered in their local communities. In 2008, members and missionaries assisted the Cambodian government in hosting two interfaith symposia.","in Cambodia were organized on May 9, 2014, in Phnom Penh, and later that year over 3,000 Saints celebrated the 20","anniversary of the Church’s establishment in Cambodia. The construction of the Phnom Pen Cambodia Temple was announced in 2018, and a groundbreaking ceremony was held in September 2021."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/cambodia?lang=eng","asOf":"2025-12-31","stakes":null,"districts":4,"familySearchCenters":12,"id":"cambodia","kind":"country","firstMissionaries":{"year":1994,"said":"Missionary work resumed in 1994, and the first two Cambodian stakes were organized in 2014."},"began":null,"lat":12.543322,"lng":104.814491},{"name":"China","members":null,"congregations":null,"wards":null,"branches":null,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/china","asOf":"","id":"china","kind":"country","continent":"Asia","firstMissionaries":null,"began":null,"lat":34.541225,"lng":108.923707},{"name":"Hong Kong","members":24930,"congregations":26,"wards":20,"branches":6,"missions":1,"temples":1,"capital":"","languages":"Chinese (Cantonese Traditional)","continent":"Asia","summary":["Hong Kong became the headquarters of the Latter-day Saint Southern Far East Mission in 1955. Many converts were refugees and have helped build the Church and promote security. Adapting to the unique needs of local members, worship services are available each day, and the temple in Hong Kong (dedicated in 1996) is open for special Sunday sessions."],"history":["A crossroads for culture and commerce, the vibrant city of Hong Kong became the headquarters for Latter-day Saint missionaries of the Southern Far East Mission in 1955. Most early converts were refugees fleeing conditions of conflict and instability. Converts worked energetically to establish the Church while also pursuing a new life for themselves and their families. Church members and mission leaders worked together on several innovative employment, education, and health-care projects aimed at helping people find security in daily life. Though many members had very few material possessions, they contributed time and talents to Church and mission callings.","The temple in Hong Kong has drawn Latter-day Saints from all over North and Southeast Asia since its completion in 1996. In the temple dedication, President Gordon B. Hinckley prayed, “May [the temple] be a sanctuary of peace amid the rush and roar of this great city. May those who enter to serve here leave the world behind and reflect on the things of eternity.” To fulfill the promise of this prayer, Church leaders in Hong Kong have flexibly accommodated Saints’ diverse life circumstances. To serve the large population of foreign domestic workers who have only one day off per week, Church services are held every day of the week, and in 2014 the temple opened for special Sunday sessions. The Saints have deeply felt God’s love and trust as they renew sacred covenants in their own languages and circumstances."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/hong-kong?lang=eng","asOf":"2025-12-31","id":"hong-kong","kind":"country","firstMissionaries":{"year":1955,"said":"A crossroads for culture and commerce, the vibrant city of Hong Kong became the headquarters for Latter-day Saint missionaries of the Southern Far East Mission in 1955."},"began":null,"lat":22.281833,"lng":114.158283},{"name":"India","members":15664,"congregations":47,"wards":21,"branches":26,"missions":2,"temples":0,"capital":"New Delhi","languages":"Hindi","continent":"Asia","summary":["Latter-day Saint missionaries formed the first branches in India in the 1850s, but a majority of Church members immigrated to Utah. From the 1960s to 1980s new Church groups formed in Tamil Nadu, Karnataka, present-day Telangana, and New Delhi. A mission in India was officially organized in 1993, and the first stake was created in Hyderabad in 2012."],"history":["The restored gospel reached India in 1849 through tracts from Orson Hyde and preaching by Latter-day Saint sailors. The first missionaries arrived in 1851. Over 300 Europeans and Indians joined the Church before the mission closed in 1856. A few members remained in the subcontinent into the 1930s, and three later missions to British India took place.","The first baptism in independent India took place in 1961, when Elder Spencer W. Kimball baptized Mangal Dan Dipty in New Delhi. Though a mission was not established at the time, people continued to find their way into the Church. For example, S. Paul Thiruthuvadoss was converted by a pamphlet he found in a used book store in 1954, and he began preaching the gospel near Coimbatore. In 1978 Edwin and Elsie Dharmaraju, expatriate Indians called as missionaries to their homeland, established a branch in Hyderabad.","In 1993 a mission in India was finally organized. Reactivation efforts, leadership development, and conversions led to a rapid increase in the number of branches. Visa restrictions limited the number of foreign missionaries, but local members helped carry the work forward, and Church membership in the country increased tenfold in the next 20 years, even as many members emigrated. The first stake in India was organized in Hyderabad in 2012."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/india?lang=eng","asOf":"2025-12-31","id":"india","kind":"country","firstMissionaries":{"year":1849,"said":"The restored gospel reached India in 1849 through tracts from Orson Hyde and preaching by Latter-day Saint sailors."},"began":null,"lat":22.351115,"lng":78.667743},{"name":"Indonesia","members":7655,"congregations":24,"wards":16,"branches":8,"missions":1,"temples":0,"capital":"Jakarta","languages":"Indonesian","continent":"Asia","summary":["Latter-day Saint missionaries arrived in Indonesia in 1970, and the first stake in Indonesia was organized in 2011."],"history":["In June 1969, after years of association with foreign Latter-day Saints residing in Indonesia, a man named Sutrisno became the first Indonesian to be baptized in the country. Later that year, Church leaders visited Indonesia to formally establish a foundation in the ethnically diverse country that spans more than 17,000 islands. The first Latter-day Saint missionaries to Indonesia—assigned initially from the Southeast Asia Mission headquartered in Singapore—arrived in Jakarta, on the island of Java, in January 1970. Over the next few years, membership grew and expanded to other Javanese cities, and in 1975 the Indonesia Jakarta Mission was created.","Limitations on foreign missionary visas in Indonesia created challenges for several years, leading to periodic mission closures. However, local Indonesian missionaries continued to serve in their home country as part of the Singapore mission. Indonesians Effian and Mary Kadarusman served as mission leaders from 1985 to 1989, extending their mission a year while the new mission president faced difficulties obtaining a visa. This led to the calling of Piet Tandiman in 1989 and his son Juswan in 1992 to serve as full-time counselors to the Singapore mission president while residing in Indonesia. The Indonesia Jakarta Mission reopened in 1995, and missionaries were assigned to areas outside of Java. Branches were organized on several islands, including Sumatra and Bali.","In 2000, Church President Gordon B. Hinckley visited with the president of Indonesia, Abdurrahman Wahid, and arranged for the Church to donate rice, hygiene kits, and clothing for refugees. More humanitarian aid was provided by the Church in response to the devastating tsunami that hit parts of Indonesia in December 2004.","The Jakarta Indonesia Stake, the first in the country, was organized in May 2011, and the second, the Surakarta Indonesia Stake, in April 2012. The first Latter-day Saint temple in Indonesia was announced to be built in Jakarta in April 2023."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/indonesia?lang=eng","asOf":"2025-12-31","stakes":null,"districts":1,"familySearchCenters":12,"id":"indonesia","kind":"country","firstMissionaries":{"year":1970,"said":"Latter-day Saint missionaries arrived in Indonesia in 1970, and the first stake in Indonesia was organized in 2011."},"began":null,"lat":-2.483383,"lng":117.890285},{"name":"Israel","members":null,"congregations":3,"wards":0,"branches":3,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/israel","asOf":"","id":"israel","kind":"country","continent":"Asia","firstMissionaries":null,"began":null,"lat":30.812425,"lng":34.859476},{"name":"Japan","members":131776,"congregations":230,"wards":142,"branches":88,"missions":7,"temples":4,"capital":"Tokyo","languages":"Japanese","continent":"Asia","summary":["Latter-day Saint missionaries first arrived in Japan in 1901. The mission closed between 1924 and 1948, but a few faithful members of the Church continued to meet together. The Church experienced gradual growth in Japan, and the first temple in Asia was dedicated in Tokyo in 1980. Japanese Latter-day Saints have donated many hours to earthquake and tsunami recovery efforts."],"history":["The Church of Jesus Christ of Latter-day Saints first sent missionaries to Japan in 1901. Although political tension closed the Japan Mission between 1924 and 1948, members of the Church continued to practice their faith, share the gospel, and build the Church in Japan. When the Church returned to Japan at the end of World War II, a small group of faithful Japanese converts, few having been baptized, were found meeting together regularly.","Since World War II, the Church in Japan has experienced gradual yet steady advancement. The Japanese Saints have shown great devotion to the restored gospel. In 1965, many sacrificed time and wages to travel to the temple in Hawaii. In the 1970s, this devotion led to the construction of a temple in Tokyo—the first temple in Asia and the first of three in Japan. Japanese Saints today make important contributions to their communities and nation. For example, in 2011, after the East Japan earthquake and tsunami devastated many areas, Japanese Saints spent many hours distributing relief supplies and helping their neighbors to repair the damage.","The history of the Church in Japan is one of conviction that transcends national boundaries and political disagreements."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/japan?lang=eng","asOf":"2025-12-31","id":"japan","kind":"country","firstMissionaries":{"year":1901,"said":"Latter-day Saint missionaries first arrived in Japan in 1901."},"began":null,"lat":36.574844,"lng":139.239418},{"name":"Kazakhstan","members":null,"congregations":3,"wards":0,"branches":3,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["The first Latter-day Saints to live in Kazakhstan were Russell and Margaret Backus, Americans working in Almaty, who began having worship meetings in their apartment in late 1997. In 1998, other families moved to Almaty and provided the nucleus around which the Church began to grow.","The first baptism in Kazakhstan was in November 1999, a woman named Jazigul Tugelbaeva who learned of the Church from American members living in Almaty. The Church received official recognition in December 2000. Seven months after the government recognition, the first branch of the Church in the country was created in Almaty on July 29, 2001.","Barry A. and Tamara H. Baker were the first missionaries called to Kazakhstan. Representing Latter-day Saint Charities, the Bakers undertook projects in hospitals and orphanages, provided aid to victims of the May 2003 earthquake, and also worked with other humanitarian organizations.","For Journalist Use Only","Boris Leostrin","E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/kazakhstan","asOf":"","id":"kazakhstan","kind":"country","continent":"Asia","firstMissionaries":null,"began":{"year":1997,"said":"The first Latter-day Saints to live in Kazakhstan were Russell and Margaret Backus, Americans working in Almaty, who began having worship meetings in their apartment in late 1997."},"lat":48.101295,"lng":66.778082},{"name":"Kuwait","members":null,"congregations":1,"wards":1,"branches":0,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/kuwait","asOf":"","id":"kuwait","kind":"country","continent":"Asia","firstMissionaries":null,"began":null,"lat":29.273396,"lng":47.497948},{"name":"Macau","members":1595,"congregations":2,"wards":0,"branches":2,"missions":0,"temples":0,"capital":"","languages":"Chinese (Cantonese Traditional)","continent":"Asia","summary":["Latter-day Saint missionaries arrived in Macau in 1964, but government policies soon caused the mission to close. A 1976 constitutional amendment allowed for the return of missionaries, and several new Church members were baptized in 1977. The Church continued to grow as Macau reverted from Portuguese control to Chinese in 1999, and in 2015 the Macau China District was organized."],"history":["The Latter-day Saints are relatively few in number in Macau, the most densely populated region in the world. For over half a century Latter-day Saints have been part of the fabric of Macanese society, working hard within the bustling economy and building relationships with local government and the religious establishment. In the early years of missionary efforts in Macau, missionaries and local members hosted annual choir performances during the Christmas season, which were attended by hundreds of local people.","The constant flow of people in and out of Macau for economic opportunities has contributed to fluctuations in local Church organization. For instance, a Mandarin-speaking branch was organized in 2001 but discontinued in 2004. A few dedicated families have served diligently in key local callings for more than one generation. In 2015 the Church reached a milestone for institutional maturity with the creation of the Macau China District. That same year, Macau’s diverse but small, committed membership was an ideal pilot for the new basic unit program, centered on a two-hour church block. Latter-day Saints’ experiences in Macau prove Jesus’s promise that “where two or three are gathered together in my name, there am I in the midst of them” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/macau?lang=eng","asOf":"2025-12-31","id":"macau","kind":"country","firstMissionaries":{"year":1964,"said":"Latter-day Saint missionaries arrived in Macau in 1964, but government policies soon caused the mission to close."},"began":null,"lat":22.17576,"lng":113.551414},{"name":"Malaysia","members":11769,"congregations":24,"wards":0,"branches":24,"missions":0,"temples":0,"capital":"Kuala Lumpur","languages":"Malay","continent":"Asia","summary":["The first Church presence in Malaysia began with expatriate Latter-day Saints who held meetings with local members in the 1970s. The Malay translation of the Book of Mormon, Doctrine and Covenants, and Pearl of Great Price was completed in 2018. Today, Church membership reflects the geographic and ethnic diversity in West and East Malaysia."],"history":["Latter-day Saint history in Malaysia dates back to 1854, when a local ruler of Malacca briefly hosted American missionary Elam Luddington, but the Church did not take root until the 1970s, when small groups of expatriate and local Latter-day Saints began to gather in Penang and Kuala Lumpur.","The Church received official recognition by the government on October 19, 1977, with local Latter-day Saints such as Anthony T. K. Lim taking formal responsibility as Church representatives. In the late 1970s and early 1980s, Jenny Lum, Derrick Ho, Chan Wai Leong, and Doreen Khoo Bee Yee were among the first to serve full-time missions. Ricky Tjeong and Ivan Bee Ho were among the first local leaders at the branch and district levels.","As the restored gospel spread throughout Malaysia’s ethnic populations and geographic regions, the Church became increasingly diverse. Despite the great distances involved, Latter-day Saints regularly gathered together to teach each other and to connect to the global Church. The Malay translation of the triple combination of scriptures—the Book of Mormon, Doctrine and Covenants, and Pearl of Great Price—was completed in 2018.","The Saints have also labored diligently to serve and build in their local communities in West and East Malaysia, laboring in many corners of the Lord’s vineyard (see"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/malaysia?lang=eng","asOf":"2025-12-31","id":"malaysia","kind":"country","firstMissionaries":{"year":1854,"said":"Latter-day Saint history in Malaysia dates back to 1854, when a local ruler of Malacca briefly hosted American missionary Elam Luddington, but the Church did not take root until the 1970s, when small groups of expatriate and local Latter-day Saints began to gather in Penang and Kuala Lumpur."},"began":null,"lat":4.569375,"lng":102.265682},{"name":"Mongolia","members":13250,"congregations":24,"wards":12,"branches":12,"missions":1,"temples":0,"capital":"Ulaanbaatar","languages":"Mongolian","continent":"Asia","summary":["In 1992 retired Latter-day Saints were called as senior missionaries to teach school in Mongolia. Three students were baptized in 1993, followed by others who helped lay a foundation in the 1990s as translators, missionaries, and leaders. The first stake was organized in Ulaanbaatar in 2009, followed by the Ulaanbaatar East Stake, organized in 2016."],"history":["Senior missionaries for The Church of Jesus Christ of Latter-day Saints arrived in Ulaanbaatar in 1992, shortly after the creation of a democratic government in Mongolia. Unable to openly proselytize, the missionaries began teaching university and high school classes and holding private meetings to teach those interested in the restored gospel. In February 1993, Tsendkhuu Bat-Ulzii and Lamjav Purevsuren, students in the missionaries’ classes, were baptized; others soon followed. As the small group of converts grew, members formed a committee to translate Church materials, including the sacrament and baptismal prayers, into Mongolian.","On January 9, 1994, the Ulaanbaatar Relief Society was organized. One week later, the Ulaanbaatar Branch was organized, and members began holding regular meetings. As the Church grew, members accepted calls to leadership, and, as missionaries, shared the restored gospel with their neighbors and established a firm foundation for the Church in their homeland. In July 1998, the Mongolia Service Center was established in Ulaanbaatar and has directed member efforts to provide humanitarian aid throughout the country. Mongolian Saints have shown their love and discipleship as they have served their neighbors (see","Mongolian Saints have demonstrated incomparable faith and determination to extend love to their neighbors, share the gospel, and live the gospel. Saints from across the country have made long journeys to weekly meetings and to the temple to make and keep their covenants and to provide a place of covenant belonging for all."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/mongolia?lang=eng","asOf":"2025-12-31","id":"mongolia","kind":"country","firstMissionaries":{"year":1992,"said":"In 1992 retired Latter-day Saints were called as senior missionaries to teach school in Mongolia."},"began":null,"lat":46.825039,"lng":103.849974},{"name":"Philippines","members":905082,"congregations":1370,"wards":890,"branches":480,"missions":26,"temples":3,"capital":"","languages":"Continent","continent":"Asia","summary":["Though a few Filipinos joined the Church in the 1940s and 1950s, growth quickly accelerated in 1961, when the government granted legal recognition to the Church and missionaries began teaching in the country. The first stake in the Philippines was organized in 1973, and more than 100 stakes had been established by 2017. The Philippines now has multiple temples in use and many others under construction."],"history":["A few Filipinos joined the Church in the 1940s and 1950s, but missionary work did not begin in earnest in the Philippines until 1961. After that point, it accelerated quickly. By the end of the decade, the Church had a presence on eight major islands. In 1973 the first stake in the Philippines was organized. Latter-day Saints’ faithful service led not only to the construction of the country’s first temple, dedicated in 1984, but also to the opening of a local missionary training center and to efforts to translate Church materials into multiple Philippine languages. In the 1990s Church membership grew to over a quarter of a million members.","Filipino Saints have worked to build their lives and congregations on “the rock of our Redeemer,” a firm foundation against the troubles of the world (","). Working closely with each other and in concert with Church members from around the world, Filipino Latter-day Saints have provided shelter and given aid to their fellow Filipinos during natural disasters, developed additional skills to provide for their families and improve their communities, and tried to live as examples of Christlike righteousness and love. The Philippines has the fourth-largest population of Latter-day Saints of any country in the world: members worship in over 100 stakes and in two temples while they await the completion of five more."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/philippines?lang=eng","asOf":"2025-12-31","id":"philippines","kind":"country","firstMissionaries":{"year":1961,"said":"Though a few Filipinos joined the Church in the 1940s and 1950s, growth quickly accelerated in 1961, when the government granted legal recognition to the Church and missionaries began teaching in the country."},"began":null,"lat":12.750349,"lng":122.73121},{"name":"Singapore","members":3262,"congregations":6,"wards":6,"branches":0,"missions":1,"temples":0,"capital":"Singapore","languages":"English","continent":"Asia","summary":["Latter-day Saint missionaries were sent from Hong Kong to Singapore in 1968, but in 1970 governmental restrictions on missionary visas deterred proselytizing for a decade. Local Latter-day Saints embraced missionary work and leadership and laid a foundation for the organization of the Singapore Stake in 1995. A temple was announced in Singapore in 2023."],"history":["From the beginning, Latter-day Saint communities in Singapore have been a cosmopolitan mix of people from Chinese, Malaysian, Indian, Indonesian, European, and other ethnic and national backgrounds. Singapore has drawn this diverse community of Latter-day Saints, all with unique gifts to share, because it is a hub of southeast Asian commerce, education, and culture.","After decades of war and civil unrest in the South Asia area, efforts to spread the gospel to these countries began in earnest in the late 1960s. Tight government restrictions on foreign missionary visas established in 1970 created a Church culture in which local members, many of them new converts, assumed significant responsibilities of leadership and missionary work. By 1977 most new converts had been introduced to the gospel by other members. Indeed, Singaporean Saints have been “not weary in well-doing, … laying the foundation of a great work” and learning that “out of small things proceedeth that which is great” (","Over the decades the Church’s relationship with the government has improved significantly, and Church members have earned a reputation as hardworking citizens who put family first. Their energetic family history efforts have led them to send many names to the nearby Hong Kong and Taipei temples for sacred ordinances. In November 2019, when President Russell M. Nelson visited Singapore, he praised their efforts and said he prayed for a day when the Singapore Saints would have a temple of their own."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/singapore?lang=eng","asOf":"2025-12-31","id":"singapore","kind":"country","firstMissionaries":{"year":1968,"said":"Latter-day Saint missionaries were sent from Hong Kong to Singapore in 1968, but in 1970 governmental restrictions on missionary visas deterred proselytizing for a decade."},"began":null,"lat":1.357107,"lng":103.819499},{"name":"South Korea","members":89092,"congregations":99,"wards":60,"branches":39,"missions":3,"temples":1,"capital":"","languages":"Korean","continent":"Asia","summary":["During the Korean War, United States servicemen and local converts shared the gospel and many accepted it. During the following decades, thousands of Koreans were baptized, and in 1973 the first stake in mainland Asia was organized in Seoul, South Korea."],"history":[],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/south-korea?lang=eng","asOf":"2025-12-31","id":"south-korea","kind":"country","firstMissionaries":null,"began":{"year":1973,"said":"During the following decades, thousands of Koreans were baptized, and in 1973 the first stake in mainland Asia was organized in Seoul, South Korea."},"lat":36.638392,"lng":127.696119},{"name":"Sri Lanka","members":1732,"congregations":4,"wards":0,"branches":4,"missions":null,"stakes":null,"districts":null,"familySearchCenters":3,"temples":null,"history":["Two Latter-day Saint missionaries, Chauncey W. West and Benjamin F. Dewey, arrived in Ceylon in May 1853. They briefly labored in Galle and Colombo but could find neither a hall in which to preach nor a person to listen to their message, thanks largely to the influence of anti-Mormon tracts and newspaper articles. They remained in the country only a short time before returning to India.","The Church’s next official contact with Sri Lanka was in August 1975, when two missionaries en route home from the Singapore Mission were assigned to stop in Sri Lanka to explore the prospects for initiating missionary work. They reported favorably.","In 1976, Clarence Long, a Latter-day Saint from Texas, visited Colombo on business and became acquainted with Reginald and Easvary Rasiah and presented them with a Book of Mormon. Their son, Rosignald traveled to the U.S. to work for Long and was baptized in Texas in June 1977. Reginald and Easvary Rasiah were baptized in August 1977, a few of their family members and others were baptized in ensuing months.","The Sri Lanka Branch (a small congregation) was organized in March 1978 with Reginald Rasiah as president. The Church was officially registered in March 1979.","In 1979, the Genealogical Society of Utah started microfilming Sri Lanka’s vital records. The Church and the Rotary Club in Columbo worked together to start a program to teach English as a second language in February 1982.","Several senior couples served in Sri Lanka beginning in the late 1970s. They did not actively proselyte, but taught those who requested more information about the Church. Missionaries were removed from the country at different times due to civil war. Sri Lanka had one branch and 135 members in 1990. Limited numbers of young foreign missionaries were allowed to serve there beginning about the late 1990s. This led to accelerated Church growth.","The first chapel in Sri Lanka was dedicated in December 2001. In 2003, membership reached 783.","For Journalist Use Only","Annie Wong Wan Chai, Hong Kong Phone: 852-2910-2940"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/sri-lanka","asOf":"","id":"sri-lanka","kind":"country","continent":"Asia","firstMissionaries":{"year":1853,"said":"Two Latter-day Saint missionaries, Chauncey W. West and Benjamin F. Dewey, arrived in Ceylon in May 1853."},"began":null,"lat":7.555494,"lng":80.713785},{"name":"Taiwan","members":63425,"congregations":97,"wards":87,"branches":10,"missions":2,"temples":1,"capital":"Taipei City","languages":"Chinese (Mandarin)","continent":"Asia","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","National Assistant Director of Communication","Latter-day Saint missionaries arrived in Taipei in 1956. Early Church members translated hymns and scriptures, and Taiwan became a hub for Chinese translation. Saints in Taiwan donated funds and labor to construct the first meetinghouse in Taipei, which was completed in 1966. Taiwanese Saints also donated funds to build the Taipei Taiwan Temple, which was dedicated in 1984."],"history":["Home to indigenous peoples for thousands of years, now with a majority Han Chinese population, the island of Taiwan has a complex cultural, political, religious, and linguistic heritage. Missionaries of the Southern Far East Mission studied Mandarin Chinese for several months before arriving in Taiwan in 1956. By 1959 the missionary force included ethnic Chinese members such as Koot Siu-yuen (Nora) 葛肇媛 from Hong Kong and Chiu Siou-ping (Donna) 邱秀平, a local convert.","Taiwan was the center for translation efforts for the Book of Mormon in Chinese, published in 1965. In 1974 translators in Taiwan worked as part of an international team to publish the Chinese Doctrine and Covenants and, two years later in 1976, the Pearl of Great Price.","Amid trials and challenges in Taiwan’s bustling economy and competitive educational system, individual Latter-day Saints have consecrated their talents and experience to God’s work. Members labored with their own hands to build the first chapel in Taipei, completed in 1966, and contributed funds to construct the Taipei Taiwan Temple, completed in 1984. “May it be sacred to all who enter its portals,” prayed Church President Gordon B. Hinckley at the temple dedication, “and may they rejoice in the eternal ordinances to be performed herein.” Indeed, in decades since, the temple has been a powerful focus of Latter-day Saint life in Taiwan. Members have also coordinated with civic and cultural institutions to host genealogy and family history exhibitions, sharing the spirit of temple ordinances far and wide."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/taiwan?lang=eng","asOf":"2025-12-31","id":"taiwan","kind":"country","firstMissionaries":{"year":1956,"said":"Latter-day Saint missionaries arrived in Taipei in 1956."},"began":null,"lat":23.973937,"lng":120.982018},{"name":"Thailand","members":24825,"congregations":44,"wards":21,"branches":23,"missions":2,"temples":1,"capital":"Bangkok","languages":"Thai","continent":"Asia","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Latter-day Saint missionaries first preached in Thailand in 1968. Local members helped establish the Church through their outreach and example of service and love, particularly in organizing cleanup after natural disasters and sharing the gospel with their friends and neighbors. Thailand’s first stake was organized 1995, and the Bangkok Thailand Temple was dedicated in 2023."],"history":["Following American missionary Elam Luddington’s short mission in 1854, no further attempts were made to establish the Church in Thailand for more than a century. In 1968, Anan Eldredge, a Thai member who had joined the Church after meeting a Latter-day Saint family in Bangkok, tutored missionaries in the Thai language and culture when they first arrived. In 1969, Natthamon D. Limsukon, a member from Chiang Mai, was similarly instrumental in helping missionaries establish local congregations in northern Thailand.","Local members’ outreach and example were critical to the survival of the Church in delicate cultural and political circumstances. Members hosted cultural events at local meetinghouses, excelled in the arts, organized to clean up after natural disasters, and reached out in love to share the gospel with friends and neighbors.","In 1988, Margaret and Anan Eldredge were called to preside over the Thailand Bangkok Mission. In June 1995, when the Bangkok Thailand Stake was organized, local members accepted callings as stake president, stake Relief Society president, and stake patriarch. Shortly after the announcement of the planned Bangkok Thailand Temple, Saints celebrated the first half century of the Church’s establishment. Truly “by [their] faith with great diligence, and with patience,” the gospel fruit had taken root and become “a tree springing up unto everlasting life” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/thailand?lang=eng","asOf":"2025-12-31","id":"thailand","kind":"country","firstMissionaries":{"year":1854,"said":"Following American missionary Elam Luddington’s short mission in 1854, no further attempts were made to establish the Church in Thailand for more than a century."},"began":null,"lat":14.897192,"lng":100.83273},{"name":"United Arab Emirates","members":2002,"congregations":6,"wards":5,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/united-arab-emirates","asOf":"","id":"united-arab-emirates","kind":"country","continent":"Asia","firstMissionaries":null,"began":null,"lat":24.000249,"lng":53.999483},{"name":"American Samoa","members":17646,"congregations":44,"wards":38,"branches":6,"missions":0,"temples":0,"capital":"Pago Pago","languages":"Samoan","continent":"Oceania (Pacific)","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Congregations of Samoan Latter-day Saints have worshipped together since the 1860s. In the early 20th century, the Church organized schools and built up Mapusaga as a gathering place for Saints in American Samoa. The first temple was dedicated in 1983, and in 2019 a second temple was announced in Pago Pago."],"history":["In 1863 Kimo Pelio and Samuela Manoa—two missionaries sent from Hawai‘i—brought the restored gospel to the Samoan Islands. Due to disruptions in the Church in Hawai‘i, the additional missionaries they expected never arrived, but both chose to remain on the islands. In 1888 Joseph and Florence Dean arrived to formally open a mission. By 1900, when Samoa was divided into a western, German-governed territory and an eastern, American-governed territory, there were over 1,000 Latter-day Saints on the islands.","In the early 1900s, in addition to teaching the gospel, the Church organized schools and helped build up Mapusaga as a gathering center. As the Church became more established in the mid-twentieth century, many American Samoans learned career and Church leadership skills while serving as labor missionaries. In 1969 the first stake in American Samoa was organized.","In 1977 President Spencer W. Kimball announced plans to build a temple in Pago Pago, American Samoa, but the location of the temple was later changed to Apia, Samoa. American Samoan Saints gave to help build the Apia temple, which was dedicated in 1983. The Church in American Samoa has continued to grow. By 2012 there were five stakes in American Samoa, and in 2019 President Russell M. Nelson announced new plans for a temple in Pago Pago."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/american-samoa?lang=eng","asOf":"2025-12-31","id":"american-samoa","kind":"country","firstMissionaries":{"year":1863,"said":"In 1863 Kimo Pelio and Samuela Manoa—two missionaries sent from Hawai‘i—brought the restored gospel to the Samoan Islands."},"began":null,"lat":-14.297124,"lng":-170.713148},{"name":"Australia","members":165272,"congregations":300,"wards":232,"branches":68,"missions":5,"temples":5,"capital":"Canberra","languages":"English","continent":"Oceania (Pacific)","summary":["The first Latter-day Saint missionaries came to Australia in the 1840s. Church growth was initially slow in the country, but greater growth and stability came in the 20th century. The first Australian stakes were organized in 1960. In 1984, the Church dedicated a temple in Sydney."],"history":["The restored gospel was introduced to Australia in 1840 by William Barratt, a 17-year-old British convert who had been ordained to preach just before his family immigrated to Australia. Other missionaries and immigrant members arrived in the following years, organizing the first branch in 1844 and a mission in 1851. Many early members emigrated to help build up the kingdom of God in Utah, but a few remained in Australia.","In the early 1900s, the Church began establishing a more stable presence in Australia. The first Church-owned meetinghouse was dedicated in 1904. At the end of World War I, after assuring the government that missionaries were no longer encouraging converts to emigrate, the Church was granted permission to send more missionaries to the country. After World War II, Church members participated in an ambitious building program to construct chapels around the country. In 1960, stakes were organized in Sydney, Brisbane, and Melbourne and were among the first stakes organized outside North America.","In 1984, the first temple in Australia was dedicated in Sydney. Saints faithfully pursued family history work to preserve both immigrant and Aboriginal Australian histories. By 2003, there were also temples in Adelaide, Melbourne, Perth, and Brisbane, and by 2016 there were roughly 150,000 Church members organized into 40 stakes."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/australia?lang=eng","asOf":"2025-12-31","id":"australia","kind":"country","firstMissionaries":{"year":1840,"said":"The restored gospel was introduced to Australia in 1840 by William Barratt, a 17-year-old British convert who had been ordained to preach just before his family immigrated to Australia."},"began":null,"lat":-24.776109,"lng":134.755},{"name":"Cook Islands","members":1890,"congregations":5,"wards":0,"branches":5,"missions":0,"temples":0,"capital":"Avarua","languages":"Cook Islands Maori (Rarotongan)","continent":"Oceania (Pacific)","summary":["The first Latter-day Saint branch in the Cook Islands was organized in 1946. Over the decades that followed, Church members in the Cook Islands labored on the project of translating Latter-day Saint scriptures, including the Book of Mormon, into Cook Islands Māori."],"history":["Beginning in the 1940s, groups of Latter-day Saints began forming in the Cook Islands, with the first branch formed in Rarotonga on October 6, 1946. A flurry of activity ensued as the Saints worked hard to build Zion, from the publication of","), a Latter-day Saint periodical, to the establishment of Primaries in Avarua, Murienua, Black Rock, Nikao, and Tutakimoa. Manu Cummings and Temauiarii James Vahua Ezekiela labored for decades on the project of translating Latter-day Saint scriptures—including the Book of Mormon, Doctrine and Covenants, and Pearl of Great Price—into Cook Islands Māori.","Latter-day Saints worked to be contributing members of their local societies, holding joint activities with community groups such as the Akaroa Youth Club of Arorangi. They also gathered with each other to work on common projects, such as the work of the Aitutaki Branch to maintain the branch boat and raise funds for a branch trip to the temple in Hamilton, New Zealand. Branch members in Rarotonga regularly hosted groups of members from other islands who were en route to the temple in New Zealand.","Latter-day Saints have continued to serve in their communities, helping those living in poverty, assisting with disaster recovery, and protecting the natural environment. They have embodied the prophet Nephi’s exhortation to “press forward with a steadfastness in Christ, having a perfect brightness of hope, and a love of God and of all [humankind]” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/cook-islands?lang=eng","asOf":"2025-12-31","id":"cook-islands","kind":"country","firstMissionaries":null,"began":{"year":1946,"said":"The first Latter-day Saint branch in the Cook Islands was organized in 1946."},"lat":-19.996972,"lng":-157.785871},{"name":"Fiji","members":24847,"congregations":52,"wards":26,"branches":26,"missions":1,"temples":1,"capital":"Suva","languages":"Fijian","continent":"Oceania (Pacific)","summary":["Though a small group of faithful Church members began worshipping together in Fiji in the 1930s, it was not until 1954 that missionaries officially arrived to preach. The Church eventually became an established presence across the island, and in 2000 a temple was dedicated in Suva."],"history":["Although Latter-day Saint missionaries traveling throughout the South Pacific occasionally stopped in Fiji, no attempts were made to establish the Church among the Fijian people until 1924. That year, Mele Vea Inoke Tidboald Ashley, a Tongan convert, moved to Suva. Mele Vea maintained her strong faith in isolation, with only occasional contact with the Church until about 1947, when Cecil and Amely Smith began holding weekly Church meetings in their home.","This small group’s efforts to share the gospel built a nucleus of Church members in Suva long before missionaries arrived. In 1958, just four years after missionaries were assigned to Fiji, Church President David O. McKay dedicated a meetinghouse in Suva, and a district was organized. When government quotas limited non-Fijian missionaries allowed in the country, local member missionaries traveled throughout the islands to preach. By 1971, branches were established on the three largest Fijian islands.","In the 1970s, Fijian Saints began translation of the Book of Mormon and other Church materials into Fijian, established a home study seminary program, and opened several Church-operated schools throughout Fiji. By 1980, the Church was a recognized part of Fijian society, with government officials attending meetings. In 1983, the Suva Fiji Stake was organized.","In 2000, during a coup arising from racial tensions in Fiji, the Fiji Suva Temple was dedicated by Church President Gordon B. Hinckley. In 2016, shortly after a devastating cyclone made landfall, the refurbished temple was rededicated. Despite occasional political upheaval and natural disasters, a diverse group of Saints in Fiji have rejoiced together, being “all one in Christ” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/fiji?lang=eng","asOf":"2025-12-31","id":"fiji","kind":"country","firstMissionaries":{"year":1924,"said":"Although Latter-day Saint missionaries traveling throughout the South Pacific occasionally stopped in Fiji, no attempts were made to establish the Church among the Fijian people until 1924."},"began":null,"lat":-18.12397,"lng":179.012274},{"name":"French Polynesia","members":30350,"congregations":94,"wards":74,"branches":20,"missions":1,"temples":1,"capital":"Papeete","languages":"French","continent":"Oceania (Pacific)","summary":["Latter-day Saint congregations in French Polynesia first worshipped together on Tubuai, Tahiti, and on the Tuamotu Islands in the 1840s. Religious and political strife limited Church growth and full-time missionary work on the islands until the 1890s. Since then, Church members across French Polynesia have established deep spiritual roots. In 1984 the Church dedicated a temple in Papeete, Tahiti."],"history":["In 1843, the Prophet Joseph Smith and the Quorum of the Twelve Apostles called four missionaries to take the gospel “unto the islands of the sea” in the Pacific (Doctrine and Covenants 133:8). On Tubuai, Addison Pratt became the first Latter-day Saint missionary to preach in a language other than English. Benjamin Grouard established the Church in the Tuamotus; early native converts Haametua and Hamoe laid the foundation for Church growth in Tahiti. Telii, one of the earliest members baptized by Pratt, taught Tahitian converts to sing Latter-day Saint hymns, which they adapted to Polynesian singing styles.","In 1852, amidst religious conflicts between the French and the English, Latter-day Saint missionaries were expelled from the islands. For the next 40 years, Saints in French Polynesia maintained the faith in the face of persecution. Saints in Anaa, for example, were attacked, and five were executed after an altercation with a police officer. Despite limited contact with Church headquarters, local leaders endured imprisonment, spread the gospel, and organized a Relief Society.","After missionaries returned in 1892, Church programs were more fully established, and publishing efforts began. Saints built meetinghouses, gathered for conferences, and organized singing groups. In 1963, a group of Saints made the trip to New Zealand for the first Tahitian-language temple sessions. In 1983, President Gordon B. Hinckley dedicated the Papeete Tahiti Temple. Today, French Polynesian Saints honor their deep roots in the Church while reaching out in service to their community."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/french-polynesia?lang=eng","asOf":"2025-12-31","id":"french-polynesia","kind":"country","firstMissionaries":{"year":1843,"said":"In 1843, the Prophet Joseph Smith and the Quorum of the Twelve Apostles called four missionaries to take the gospel “unto the islands of the sea” in the Pacific (Doctrine and Covenants 133:8)."},"began":null,"lat":-17.024375,"lng":-144.64349},{"name":"Guam","members":2768,"congregations":4,"wards":4,"branches":0,"missions":1,"temples":1,"capital":"Hagåtña","languages":"Chamorro","continent":"Oceania (Pacific)","summary":["Latter-day Saints in the United States military were the first to bring the Church to Guam after World War II. The first Chamoru Saints joined the Church in the 1970s, leading to the translation of the Book of Mormon into Chamoru in 1989. In 2022 the first temple in the territory was dedicated in Yigo, Guam."],"history":["At the end of World War II, Latter-day Saints serving in the United States military and stationed in Guam began meeting in informal groups. By the early 1950s, branches were organized for military personnel, their families, and other expatriate Saints living in Guam. With the support of missionaries from the Japanese Mission, members began sharing the gospel with their neighbors. By the end of the decade, the first meetinghouses in Guam were dedicated to accommodate the steadily growing branches.","Saints in Guam have worked closely together with their neighbors. In the midst of celebration, severe tropical weather, and cultural renewal, members have provided service, teaching, and translation. In the 1970s, the indigenous CHamoru people, whose language and culture had been repressed for generations, began to meet with members and missionaries. After the first CHamoru converts, Maria and Donald Calvo, were baptized in May 1977, Maria began working to translate the Book of Mormon into CHamoru. Maria hoped that the translation would help other CHamoru converts learn the gospel in their language and that it would contribute to the preservation of their language. When her selections were published in 1989, the Guamanian legislature adopted a resolution recognizing the Book of Mormon translation as a “major accomplishment” in the preservation of the CHamoru language.","Although war created the impetus for the establishment of branches in Guam, the Saints there have endeavored to “keep the unity of the Spirit in the bond of peace” (",") as they have worked together with their neighbors."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/guam?lang=eng","asOf":"2025-12-31","id":"guam","kind":"country","firstMissionaries":null,"began":{"year":1977,"said":"After the first CHamoru converts, Maria and Donald Calvo, were baptized in May 1977, Maria began working to translate the Book of Mormon into CHamoru."},"lat":13.449994,"lng":144.765168},{"name":"Kiribati","members":23585,"congregations":45,"wards":20,"branches":25,"missions":0,"temples":0,"capital":"Tarawa","languages":"Kiribati","continent":"Oceania (Pacific)","summary":["In the 1970s, I-Kiribati students joined the Church while studying at Liahona High School in Tonga. Later, these students returned to Kiribati as missionaries and helped establish the Church there. The Church has continued to grow on the islands since Kiribati gained its independence in 1979 and is now recognized as a positive influence in the country."],"history":["In 1975 students from Kiribati who had been baptized while attending the Church-owned Liahona High School in Tonga returned to their home country as missionaries. The early converts of these young I-Kiribati missionaries established the first branch of the Church and held meetings on the campus of their old school, the Auriaria Kokoi Ataria School on the island of Tarawa. Just two years later, the Church converted that school into the Moroni Community School (later Moroni High School).","As students of Moroni High School embraced the restored gospel and spread its message across the islands, the school gained a reputation as “a city on a hill” (",") and a place of study and faith. Despite early resistance from government and community leaders, the school and the Church have grown much in the years since Kiribati gained its independence in 1979. Now the Church is recognized as a positive influence in the social, educational, and cultural development of the country and is the third-largest Christian denomination in the republic."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/kiribati?lang=eng","asOf":"2025-12-31","id":"kiribati","kind":"country","firstMissionaries":{"year":1975,"said":"In 1975 students from Kiribati who had been baptized while attending the Church-owned Liahona High School in Tonga returned to their home country as missionaries."},"began":null,"lat":0.344861,"lng":173.664177},{"name":"Marshall Islands","members":6927,"congregations":13,"wards":12,"branches":1,"missions":1,"temples":0,"capital":"Majuro","languages":"Marshallese","continent":"Oceania (Pacific)","summary":["The earliest Church presence on the Marshall Islands was through Church members in the United States military after World War II. In the 1970s the efforts of missionaries and Marshallese people who had joined abroad helped build the Church, and in May 1978 the Church organized a branch in Majuro. In 2009 the Majuro Marshall Islands Stake was organized."],"history":["The Church’s presence in the Marshall Islands began during World War II, and for the next three decades Church meetings were held only by United States military personnel stationed there. In 1975, Helen Sievers, Primary president on Kwajalein, requested that missionaries be sent. At that time, only 9 of the nearly 90 children attending her weekly meetings had been baptized. Two years later, missionaries arrived and began baptizing local converts. In the meantime, Marshallese people living in places such as Hawaiʻi began joining the Church. On April 23, 1977, Misao and Mirasko Lokeijak were baptized, and a Church group was soon organized. In May 1978, a branch was organized in Majuro, with Misao Lokeijak as its president.","The Church spread throughout the islands. Selections of the Book of Mormon in Marshallese were published in 1984, and new meetinghouses, built with the help and support of local Saints, were dedicated in 1986. In 1991, the Kwajalein Marshall Islands District was organized, and in 2009 the Majuro Marshall Islands Stake was organized.","Throughout their history, the Marshallese Saints have worked to serve their neighbors by expanding educational opportunities and providing for the sick, the needy, and the displaced. Indeed, Marshallese Saints have been “good stewards of the manifold grace of God” (",") as they have untiringly served their communities and one another."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/marshall-islands?lang=eng","asOf":"2025-12-31","id":"marshall-islands","kind":"country","firstMissionaries":{"year":1975,"said":"In 1975, Helen Sievers, Primary president on Kwajalein, requested that missionaries be sent."},"began":null,"lat":8.230817,"lng":167.795322},{"name":"Micronesia","members":6241,"congregations":22,"wards":5,"branches":17,"missions":0,"temples":0,"capital":"Palikir","languages":"English","continent":"Oceania (Pacific)","summary":["In 1977 Yap-speaking Latter-day Saints held the first Church meetings in Micronesia. In 1985 the Church organized a small branch in Kosrae, and the Church began to grow. Since then, meetinghouses have been built throughout Micronesia, and the Book of Mormon is available in many of the local languages."],"history":["In the late 1970s, teachers from Pohnpei traveled to Lāʻie, Hawaiʻi, where they participated in educational programs at Brigham Young University–Hawaii. During their time there, they were introduced to missionaries who began teaching them the gospel. Some local people were baptized and established branches in Pohnpei after their return. Members and missionaries were soon establishing branches in other of the Federated States of Micronesia. In 1977, Charles and Odetta Keliikipi held the first Church meetings in Yap in their home. Later that same year, the first converts in Chuuk, T. M. Conrad Mailo and Nisor Cerly David, were baptized. In 1985, a small branch began meeting in Kosrae.","As the Church began to grow throughout the Federated States of Micronesia, attempts were made to stop the Church from establishing branches. Some members experienced open hostility, and some local legislatures considered proposals to ban the Church. In the face of antagonism, members of the Church responded with kindness and service. For their efforts, Micronesian Saints truly learned the wisdom of service (see",") as they participated in cleanup projects, assisted neighbors after disasters, and arranged donations to local schools, hospitals, and athletic programs. Within a few short years, legislatures throughout Micronesia issued letters of commendation for the positive contributions of Latter-day Saints to their communities.","As the Church grew, meetinghouses were built throughout Micronesia, and the Book of Mormon was translated into many of the local languages. It is now available in Pohnpeian, Yapese, Kosraean, and Chuukese. In 2014, the Panasang Pohnpei Stake was organized."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/micronesia?lang=eng","asOf":"2025-12-31","id":"micronesia","kind":"country","firstMissionaries":null,"began":{"year":1977,"said":"In 1977 Yap-speaking Latter-day Saints held the first Church meetings in Micronesia."},"lat":8.606235,"lng":151.832744},{"name":"Nauru","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/nauru","asOf":"","id":"nauru","kind":"country","continent":"Oceania (Pacific)","firstMissionaries":null,"began":null,"lat":-0.525231,"lng":166.932443},{"name":"New Caledonia","members":2585,"congregations":9,"wards":6,"branches":3,"missions":0,"temples":0,"capital":"Nouméa","languages":"French","continent":"Oceania (Pacific)","summary":["The first local member was baptized in 1968, joining a branch of migrant workers that had already been organized in the island nation. The first stake was formed in 2012."],"history":["In 1968, with a branch composed mostly of migrant workers from Fiji, 13-year-old Etienne Sun became the first New Caledonian baptized into the Church of Jesus Christ of Latter-day Saints. Membership on the island French territory had been growing slowly since workers began arriving in the 1950s, and a branch, the Nouméa branch, had been organized in 1961. Growth quickened, however, with the arrival of missionaries in 1968, a few months before Sun’s baptism. In 1972, a small meetinghouse was dedicated.","The congregation outgrew the original meetinghouse a few years later, and it was enlarged in response to the division of the branch in 1976. That year also saw the first seminary graduation in New Caledonia. The following year, a new branch was formed in Tontouta, and the three branches became the District of New Caledonia. Missionary work and membership grew in number and reach as missionaries met with tribal leaders on more islands throughout the territory.","By the early years of the new millennium, there were more than 1,500 members in New Caledonia. In 2012, the first stake was formed. The Nouméa New Caledonia Stake was composed of five wards and three branches for the over 2,000 members, as well as eight meetinghouses. Historically, the over 2,500 New Caledonian members have been assigned to the Suva Fiji and Hamilton New Zealand temple districts. However, in April 2025, a temple was announced for construction in New Caledonia."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/new-caledonia?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":3,"id":"new-caledonia","kind":"country","firstMissionaries":{"year":1968,"said":"Growth quickened, however, with the arrival of missionaries in 1968, a few months before Sun’s baptism."},"began":null,"lat":-20.637843,"lng":161.211763},{"name":"New Zealand","members":120992,"congregations":219,"wards":171,"branches":48,"missions":3,"temples":2,"capital":"Wellington","languages":"Maori","continent":"Oceania (Pacific)","summary":["After the first Latter-day Saint baptism in New Zealand in 1854, significant growth began in the 1880s when many Māori embraced the restored gospel and viewed Latter-day Saint missionaries as fulfilling Māori prophecies. In 1958 many Pacific Island missionaries helped to build a temple in Hamilton, and in 2018 the Church announced the construction of a second temple in Auckland."],"history":["In 1854, Martha Holder of Karori became the first person baptized in New Zealand. Her son, Thomas, who had previously been converted during Australia’s gold rush, was among New Zealand’s first missionaries. Early branches were established in Karori (near Wellington on the North Island) and Kaiapoi (near Christchurch on the South Island), but large congregations did not develop until the 1880s. At that point, many Māori recognized Latter-day Saint missionaries’ efforts as the fulfillment of earlier prophecies by Māori prophets, and they embraced the restored gospel. The Book of Mormon was first published in Māori in 1889. For much of the next century, the Church in New Zealand owed much of its growth to faithful Māori converts.","Near the beginning of the twentieth century, the Church worked to provide greater educational opportunities for members, first building the Māori Agricultural College and, later, the Church College of New Zealand. In the 1950s, many members were called as labor missionaries to help construct educational and religious buildings, including the temple in Hamilton, which was dedicated in 1958. The Auckland Stake—the first in New Zealand—was organized that same year.","With the dedication of the Hamilton Temple in 1958, New Zealand became a place where many Saints from the South Pacific gathered to worship in a house of the Lord (see","). Additionally, the opening of a missionary training center in New Zealand in 1977 attested to the maturity and growth of the Church in New Zealand and the Pacific. As members and missionaries worked to share the gospel, the Church grew. In 2016, the 30th stake in New Zealand was established in Dunedin, and in 2018, a second temple was announced to be built in Auckland."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/new-zealand?lang=eng","asOf":"2025-12-31","id":"new-zealand","kind":"country","firstMissionaries":{"year":1854,"said":"After the first Latter-day Saint baptism in New Zealand in 1854, significant growth began in the 1880s when many Māori embraced the restored gospel and viewed Latter-day Saint missionaries as fulfilling Māori prophecies."},"began":null,"lat":-41.500083,"lng":172.834408},{"name":"Niue","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["The first Church members in Niue were Fritz Bunge-Kruger and his family, who arrived in 1952 to do missionary work. He traveled about the island and showed movies, and then, with the contacts he made, started a home Sunday School. It soon grew to an attendance of 80. They moved to a local dance hall for meetings and on 29 May 1952, a Mutual Improvement Association was organized.","The following August, 26 converts were baptized by Elder Thayne Christensen. Other baptismal services followed, and a total of 65 were baptized the first year. Because of persecution during open air meetings, activities were held quietly at first, but at times entire villages attended. The first Niuean missionary was Sionemologa Tagavaitau.","On 12 February 1955, work commenced on the Alofi Chapel with a handful of members raising money and doing much of the building by hand. They were assisted by labor missionaries. The building was completed in 1958. Additional Church buildings were erected later.","About a third or more of the Niuean members have moved to New Zealand. Devastating hurricanes hit the island in 1959, 1960, and 1990. Many homes were leveled. Members in Niue, particularly the youth, have often distinguished themselves in island competitions.","In January 2004 a super tropical cyclone destroyed the vital birth, death and marriage records of the island. The Church had microfilmed these records starting in 1994, which preserved the information that had been destroyed. In February 2004, copies of the microfilmed records were presented to the Niueans.","For Journalist Use Only","Richard Hunter New Zealand Phone: 64(9)488-5572 Mobile: 64-21-240-7804","E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/niue","asOf":"","id":"niue","kind":"country","continent":"Oceania (Pacific)","firstMissionaries":{"year":1952,"said":"The first Church members in Niue were Fritz Bunge-Kruger and his family, who arrived in 1952 to do missionary work."},"began":null,"lat":-19.053641,"lng":-169.861341},{"name":"Northern Mariana Islands","members":null,"congregations":1,"wards":1,"branches":0,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["Among the first Church members to visit Saipan were American servicemen in 1944, including L. Tom Perry, later a member of the Quorum of the Twelve Apostles. Missionary work in Saipan began in the early 1970s, but was stopped because of local hostility. In February 1975, Elders Jeff Frame and Callis Carlton began full-time missionary work. One of the first group meetings on the island was held 24 July 1975.","Church member Alfred \"Mustang\" Gonzalez became construction manager of the new airport, arriving 16 July 1975. His family followed him in October. They bought a small vacant quonset hut that had been abandoned in the jungle and used it for a meetinghouse. After this building became too small, meetings were held in the elders' kitchen and living room. Sunday School classes were held outside under the coconut trees. A small building was completed in 1983. Brad T. Nago and his wife, Jean, were converts in Saipan, baptized 24 January 1976, and became president of Saipan's Chalan Laulau Branch (a small congregation) after the Gonzalez family returned to Hawaii. In 1980 when the Micronesia Guam Mission was created, the Saipan Branch had 85 members.","President Gordon B. Hinckley, Elder Joseph B. Wirthlin and their wives visited briefly and met with 10 missionaries and about 60 of Saipan's 300 members during a refueling stop en route from Asia on 1 June 1996.","ROTA - TINIAN","Elders Stephen Jones and Kamealoha Kaniho were assigned to open Rota, an island in the Northern Marianas, for proselyting on 5 September 1986. Work was opened on Tinian 14 August 1992, by Elder James Adamson and an Elder McCune.","For Journalist Use Only","Richard Hunter New Zealand Phone: 64-9-488-5572 Mobile: 64-21-240-7804","E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/northern-mariana-islands","asOf":"","id":"northern-mariana-islands","kind":"country","continent":"Oceania (Pacific)","firstMissionaries":{"year":1975,"said":"In February 1975, Elders Jeff Frame and Callis Carlton began full-time missionary work."},"began":null,"lat":15.175365,"lng":145.737934},{"name":"Palau","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":["There are no records of missionary activity or visits by Latter-day Saints in this 100-plus island group prior to World War II. The first known Latter-day Saints on Palau came as members of the armed forces during the war. There were no other Latter-day Saints on Palau until Heber Butler, a counselor in the Hawaii Honolulu Mission presidency, visited Palau in October 1977 to investigate the potential for missionary work.","Full-time missionary work began when Ron Brown and Stanton Akana arrived in July 1978. Their missionary activities were initially restricted by the Palauan government to the islands of Koror, Arakabesan, Malakal, and Airai. The first to be baptized in Palau were Thaem and Marina Oei and eight of their nine children in September 1978. In December 1978, the Sakuma family was baptized, the first native Palauans to join. The Palau Branch (a small congregation), later renamed the Meyungs Branch, became part of the Micronesia Guam Mission in April 1980.","Another early convert was Vincent Roberto, who was baptized in December 1980 and later served as the first native branch president. By the end of 1981, there were 59 members in Palau. The Airai Branch was created in September 1987 with Bing de Leon as president. The Meyungs Branch was divided and the Koror Topside Branch was created in December 1998 with Walter Mauiur as president. The Koror Central Branch was created in March 1989 bringing the total to four branches with 208 members. A chapel was dedicated in Meyungs in May 1990. The chapel was later torn down after the branch was dissolved to give greater strength to the Koror Topside Branch. The branch was renamed the Koror Branch in 2010, and the branch was assigned to the Barrigada Guam Stake in September 2018.","There is a fluctuating population on Palau, in and around Meyungs, comprised mostly of workers from mainland China. Missionary efforts among them began with Kenneth and Margaret Styles, a missionary couple who served in Palau from 1990 to 1991. Donglong Liu and his wife Mei Li were baptized by Kenneth Styles in August 1990. Liu was the first president of the Chinese Branch. It was later discontinued when many of its members returned to China.","For Journalist Use Only Richard Hunter New Zealand Phone: 64(9)488-5572 Mobile: 64-21-240-7804","E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/palau","asOf":"","id":"palau","kind":"country","continent":"Oceania (Pacific)","firstMissionaries":{"year":1977,"said":"There were no other Latter-day Saints on Palau until Heber Butler, a counselor in the Hawaii Honolulu Mission presidency, visited Palau in October 1977 to investigate the potential for missionary work."},"began":null,"lat":5.378354,"lng":132.910257},{"name":"Papua New Guinea","members":46583,"congregations":96,"wards":33,"branches":63,"missions":2,"temples":0,"capital":"Port Moresby","languages":"Tok Pisin","continent":"Oceania (Pacific)","summary":["Following World War II, Latter-day Saints in the United States military sometimes gathered for informal Church meetings in Papua New Guinea. In 1980 missionaries began to preach in the country, and the Church soon received legal status and established four branches. Since then, the Church has grown steadily in Papua New Guinea, especially in the 21st century."],"history":["Papua New Guinea, an archipelago nation in Oceania, had many decades of Christian history when the first Latter-day Saints arrived—US Army personnel during World War II. Some missionary work took place in 1961, but sustained Latter-day Saint missionary work did not occur until 1980. Shortly after Papua New Guinea became an independent nation, a senior missionary couple began preaching in Port Moresby. In a short time, several local converts were baptized.","The Church grew rapidly through members’ enthusiastic outreach to friends and family members. During 1981, the Church received legal status, and the Port Moresby Branch—with more than 200 members—was divided into four branches. Local members, along with young foreign missionaries, continued sharing the gospel. Consequently, the first stake in Port Moresby was organized in 1995, with Vaiba Rome as president.","Because of Papua New Guinea’s rugged topography and wide ocean distances, local Latter-day Saints often expend considerable effort just to attend regional Church meetings. It is not surprising that in a country with over 800 languages, Latter-day Saints speak multiple languages but use English and Tok Pisin at church.","In 2011, Papua New Guinea was the Church’s fastest-growing area in the Pacific. In the October 2019 general conference, President Russell M. Nelson announced a temple to be built in Port Moresby. Now, faithful Saints in this country “may go forth from this house armed with . . . power, and that [God’s] name may be upon them, and [his] glory be round about them” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/papua-new-guinea?lang=eng","asOf":"2025-12-31","id":"papua-new-guinea","kind":"country","firstMissionaries":{"year":1961,"said":"Papua New Guinea, an archipelago nation in Oceania, had many decades of Christian history when the first Latter-day Saints arrived—US Army personnel during World War II. Some missionary work took place in 1961, but sustained Latter-day Saint missionary work did not occur until 1980."},"began":null,"lat":-5.681607,"lng":144.248908},{"name":"Samoa","members":90706,"congregations":170,"wards":162,"branches":8,"missions":1,"temples":1,"capital":"","languages":"Continent","continent":"Oceania (Pacific)","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","The first missionaries to preach the restored gospel on Sāmoa arrived from Hawai‘i in 1863. Later, American missionaries officially opened a mission on the islands in 1888, and the Church grew steadily in the years that followed. In 1983 a temple was dedicated in Apia, Upolu."],"history":["In 1863 Kimo Pelio and Samuela Manoa—two missionaries sent from Hawai‘i—brought the restored gospel to the Samoan Islands. Due to disruptions in the Church in Hawai‘i, the additional missionaries they expected never arrived, but both chose to remain on the islands. In 1888 Joseph and Florence Dean arrived to formally open a mission. By 1900, when Samoa was divided into a western, German-governed territory and an eastern, American-governed territory, there were over 1,000 Latter-day Saints in the islands.","In the early 1900s, in addition to teaching the gospel the Church organized schools—at different times in English, German, and Samoan—and established the community of Sauniatu. Latter-day Saints ministered to each other during the devastating influenza pandemic of 1918 and showed their willingness to “mourn with those that mourn” (",") when one-fifth of the country’s population died.","In the years after World War II, the Church put greater focus on developing local leaders, and many Samoans learned Church leadership and career skills while serving as labor missionaries. In 1962 Samoa became one of the first countries outside the United States to have a stake; in 1974 it became the first country organized entirely into stakes, with no small districts. The Apia Samoa Temple was dedicated in 1983. After a 2003 fire the temple was rebuilt and rededicated."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/samoa?lang=eng","asOf":"2025-12-31","id":"samoa","kind":"country","firstMissionaries":{"year":1863,"said":"The first missionaries to preach the restored gospel on Sāmoa arrived from Hawai‘i in 1863."},"began":null,"lat":-13.76939,"lng":-172.12005},{"name":"Solomon Islands","members":3232,"congregations":10,"wards":0,"branches":10,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["The Solomon Islands were dedicated for the preaching of the gospel and missionary work on 10 March 1987, by Elder James E. Faust of the Quorum of the Twelve Apostles. He was accompanied by his wife and Elder and Sister John Sonnenberg of the Pacific Area Presidency. They went to Henderson Field at 5:15 in the morning and in the area of the four monuments, dedicated the Solomon Islands for the work of the Church.","Imo Ta'asi had been baptized the previous year at the Church-owned Brigham Young University, in the United States, and Peter Joseph Salaka, a member of Parliament, had been baptized the previous year in England by Ed Pinegar. The first missionaries in the islands were Elder E. Crawford Jones and his wife, Sister Judith Jones, of Moses Lake, Washington, United States. They arrived in the islands in February, 1995.","President John Gibson of the Papua New Guinea Mission later sent two pidgin-speaking Polynesian missionaries from Papua New Guinea, Elder Glenn R. Cockburn from New Zealand and Elder Sa Francis Togia from Australia. These two missionaries began the first missionary work to the people of the Solomon Islands in their own language.","The first sacrament meeting was held in Honiara on 5 February 1995. President John Gibson, Elder and Sister Jones, and Robert Bera were the four in attendance on this day. On 26 April 1995, President Gibson met with the Prime Minister of the Solomon Islands, Solomon Mamaloni, and presented him with a framed painting of Jesus Christ with the inscription \"To the Government and People of the Solomon Islands from The Church of Jesus Christ of Latter-day Saints.\" He also presented to him a specially-inscribed copy of the Book of Mormon: Another Testament of Jesus Christ.","The Honiara Branch (a small congregation) of the Solomon Islands District of the Papua New Guinea Mission of The Church of Jesus Christ of Latter-day Saints was formally organized on 4 February 1996. Sixty-two people were present that day including 17 baptized members of the Church. In 1987, there were only three Latter-day Saints in the Solomon Islands. By 1998, there were almost 100 members. The Church continues to grow and bless the lives of the people of the Solomon Islands.","For Journalist Use Only","Richard Hunter New Zealand Phone: 64(9)488-5572 Mobile: 64-21-240-7804","E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/solomon-islands","asOf":"","id":"solomon-islands","kind":"country","continent":"Oceania (Pacific)","firstMissionaries":{"year":1987,"said":"The Solomon Islands were dedicated for the preaching of the gospel and missionary work on 10 March 1987, by Elder James E. Faust of the Quorum of the Twelve Apostles."},"began":null,"lat":-8.705394,"lng":159.107069},{"name":"Tonga","members":69594,"congregations":175,"wards":141,"branches":34,"missions":1,"temples":1,"capital":"Nukuʻalofa","languages":"Tongan (Tonga Islands)","continent":"Oceania (Pacific)","summary":["Latter-day Saint missionaries first came to Tonga in the early 1890s. Significant Church growth began in 1907 after missionaries opened a school in Neiafu. Since then, generations of Latter-day Saints have shared their commitment to education and the restored gospel in their communities, and many thousands of Tongans have joined the Church."],"history":["On July 15, 1891, Brigham Smoot and Alva Butler, the first Latter-day Saint missionaries in Tonga, arrived in Nuku‘alofa. News of their arrival spread quickly, and the following day they found audience with King George Tupou I. The king graciously listened as the missionaries’ translator read the Articles of Faith in Tongan. Despite having recently created the Free Church of Tonga, the king granted the missionaries permission to preach in the country. With little success, however, the mission closed in 1897, having baptized fewer than 15 people.","Ten years later, missionaries organized a school in Neiafu, where one member lived, and began preaching throughout the islands. In the century since then, the Church has organized dozens of schools throughout Tonga. Today, seven of those schools (five middle schools and two high schools) continue to operate. Generations of Latter-day Saints have shared both skills from their education and the message of the restored gospel in their communities, and many thousands of Tongans have joined the Church. Today, more than half the population of Tonga are members of the Church.","Saints in Tonga have shown exceptional faith and diligence in living the gospel, exemplifying the scriptural call to “cheerfully do all things that lie in our power; … to see the salvation of God” (","). The history of the Church in Tonga is filled with faithful members who have trusted in God, accepted His commands, and worked faithfully to build the Church in their homeland."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/tonga?lang=eng","asOf":"2025-12-31","id":"tonga","kind":"country","firstMissionaries":{"year":1891,"said":"On July 15, 1891, Brigham Smoot and Alva Butler, the first Latter-day Saint missionaries in Tonga, arrived in Nuku‘alofa."},"began":null,"lat":-19.916082,"lng":-175.202642},{"name":"Tuvalu","members":null,"congregations":1,"wards":0,"branches":1,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["When Joseph B. Keeler became president of the Micronesia-Guam Mission in July 1983 he found that Tuvalu was part of the mission but there was no record of any members there. While visiting Tarawa in 1983 he became acquainted with two of his missionaries, Teuai Lekasa and Tekafa Tinai, and learned that they were originally from Tuvalu. They had become acquainted with the Church and were baptized while students at Liahona High School in Tonga. They told President Keeler that there were about 25 members of the Church in Funafuti, Tuvalu’s main village, all converts from either Liahona or Moroni High School in Fiji.","Keeler was not able to visit Tuvalu until September 1984. He and his wife arrived unannounced, but Tavita Tapu, another Church member who had joined the Church while attending a Church school, worked at the airport and immediately recognized the man dressed in a white shirt and tie and wearing a missionary tag as probably someone from the Church. He helped the Keelers get a room at the only hotel in Funafuti, then he got on his bike and notified all the members he could find. They met with the Keelers at the hotel that same day and held a testimony meeting. President Keeler assigned Glen and Shirley Cornwall from Murray, Utah, to begin the work of organizing a branch (a small congregation) in Tuvalu and registering the Church with the local government. They arrived in March 1985 and held the very first sacrament meeting in their hotel room with seven present. Two sister missionaries, Nolaise Maumau (a native of Tuvalu) and Kalou Tetapo, arrived in April and were joined by Elders Tevasa and Popeieta Raponi in May 1985.","The Cornwalls began the process of registering the Church (which required completion of a petition with 50 signatures). Ward and Madge Little replaced the Cornwalls in August 1985 and continued with the registration process. The first baptism in Tuvalu was Tepenga Luka, who was baptized in the lagoon on 14 December 1985. Official Church recognition was received on 16 December 1985. Sixty-two members and friends of the Church had signed the petition.","Richard Hunter New Zealand Phone: 64(9)488-5572 Mobile: 64-21-240-7804","E-mail"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/tuvalu","asOf":"","id":"tuvalu","kind":"country","continent":"Oceania (Pacific)","firstMissionaries":{"year":1983,"said":"While visiting Tarawa in 1983 he became acquainted with two of his missionaries, Teuai Lekasa and Tekafa Tinai, and learned that they were originally from Tuvalu."},"began":null,"lat":-8.640521,"lng":179.158292},{"name":"Vanuatu","members":14042,"congregations":43,"wards":11,"branches":32,"missions":1,"temples":0,"capital":"Port Vila","languages":"Bislama","continent":"Oceania (Pacific)","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","In the 1950s a few Tongan Latter-day Saints settled in Port Vila, New Hebrides. Ten years later, Tongan missionaries began sharing the gospel. After Vanuatu gained its independence in 1980, the government imposed a restriction on foreign missionaries, which lasted until 1991. In 2020 a temple was announced in Port Vila."],"history":["Latter-day Saints laid the foundations of the restored gospel in Vanuatu through years of dedicated labor. From 1981 to 1991, foreign missionaries and mission leaders were not allowed to reside in the country, and local Latter-day Saints, such as Saikem Jackson and Jack Hokau Taso in Port Vila, shouldered the responsibility for strengthening each other and sharing the gospel. Eventually, through a shift in political winds and the efforts of Saints like Edwin R. Basil, they were able to reestablish connections with the full program of the international Church.","The isolated nature of Vanuatu’s many islands has created strong local congregations that go to great lengths to gather together at the regional level. In 2003, Church President Gordon B. Hinckley visited Vanuatu. More than 2,000 Latter-day Saints from far-flung islands made great sacrifices and pooled resources to travel to hear him speak.","In 2005, the Book of Mormon was translated in Bislama under the direction of Mariella Kaun. Also under her supervision, Bislama interpretation of general conference broadcasts became available.","Vanuatu Latter-day Saints have weathered many storms, including Super Cyclone Pam in 2015, which destroyed many homes. As always, they have relied on each other to rebuild and press on."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/vanuatu?lang=eng","asOf":"2025-12-31","id":"vanuatu","kind":"country","firstMissionaries":{"year":1980,"said":"After Vanuatu gained its independence in 1980, the government imposed a restriction on foreign missionaries, which lasted until 1991."},"began":null,"lat":-16.525507,"lng":168.106915},{"name":"Angola","members":8779,"congregations":33,"wards":13,"branches":20,"missions":1,"temples":0,"capital":"Luanda","languages":"Portuguese (Brazil)","continent":"Africa","summary":["Angolan Latter-day Saints baptized while living abroad were organized into a group in 1992—16 years before the first proselytizing missionaries arrived in 2008. In addition to sharing the gospel of Jesus Christ with their neighbors, Angolan Saints serve their communities through disease awareness and prevention programs and distributing medical supplies, such as wheelchairs."],"history":["Latter-day Saints who joined the Church in overseas countries were the first to establish Zion in Angola. In March 1992, Carlos Ferreira from Mozambique led the first organized meeting for Latter-day Saint worship. Later that year, Maria da Silva, who had joined the Church in Portugal, succeeded in registering the Church with the Angolan government despite ongoing civil conflict. On June 9, 1996, the Luanda Branch was organized, with Vuamina Tshaka Mbenza as president.","Over the next decade, as the political situation stabilized, members of the Church in Angola continued to serve in the Church and share the gospel. They served their communities by hosting training sessions for the Church-sponsored HIV/AIDS prevention program. They also helped facilitate the distribution of wheelchairs to those who had been maimed in the civil conflict.","When the first full-time proselytizing missionaries arrived in 2008, they found a strong local leadership and a number of investigators who were eager to learn more after being introduced to the restored gospel by Latter-day Saint friends.","On April 17, 2011, the Luanda Angola District was organized, with Artur J. Miranda as president. Local Latter-day Saints worked to serve and engage with neighbors in their communities. Through times of fear and times of peace, nothing has been able to separate the Angolan Saints from the love of God (see"],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/angola?lang=eng","asOf":"2025-12-31","id":"angola","kind":"country","firstMissionaries":{"year":1992,"said":"Angolan Latter-day Saints baptized while living abroad were organized into a group in 1992—16 years before the first proselytizing missionaries arrived in 2008."},"began":null,"lat":-11.877577,"lng":17.569124},{"name":"Benin","members":8286,"congregations":34,"wards":22,"branches":12,"missions":1,"temples":0,"capital":"Porto-Novo","languages":"French","continent":"Africa","summary":["Though Latter-day Saints from other countries began meeting in Benin in the 1990s, the first baptisms of native Beninese occurred in 2003, after the country officially recognized the Church. With no missionaries in the country, the new Latter-day Saints were taught the gospel by telephone by missionaries in the Côte d’Ivoire Abidjan Mission."],"history":["In the late 1990s, a small group of Beninese began meeting in the home of Lincoln Dahl, a Latter-day Saint working in the American embassy in Cotonou, to partake of the sacrament and study the scriptures. When Dahl left Benin in 1997, Mathias Egoku, a Nigerian member of the Church living in Benin, led the group, which was beginning to grow. Two years later, missionaries from the Côte d’Ivoire Abidjan Mission began teaching the gospel over the phone to interested people in Cotonou. No baptisms, however, could be performed until after the Church was officially recognized in the country.","In 2003 the Church received formal recognition in Benin, and two years later, the first branch was organized in Cotonou with Egoku as president. Other branches soon followed. The Church in Benin grew quickly. Just three years after the first branch was established, three branches had been organized. In 2012 a district was created in Cotonou and, just four years later, the district became the first stake in Benin. Latter-day Saints in Benin continue to share the gospel and to reach out in love to their community."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/benin?lang=eng","asOf":"2025-12-31","id":"benin","kind":"country","firstMissionaries":null,"began":{"year":1997,"said":"When Dahl left Benin in 1997, Mathias Egoku, a Nigerian member of the Church living in Benin, led the group, which was beginning to grow."},"lat":9.529347,"lng":2.258441},{"name":"Botswana","members":5465,"congregations":23,"wards":7,"branches":16,"missions":1,"temples":0,"capital":"Gaborone","languages":"English","continent":"Africa","summary":["Latter-day Saints living in Botswana were organized into an official congregation in 1990, and missionaries arrived the same year. Since then, membership has grown to encompass several branches throughout the country."],"history":["Maurice Mzwinila and Anthony Mokgare joined The Church of Jesus Christ of Latter-day Saints while studying in the United States. With no knowledge of each other, they believed they were the only Latter-day Saints in Botswana until missionaries from the South Africa Johannesburg Mission arrived in June 1990 and placed notices in local newspapers announcing they would begin holding church services in the capital city, Gaborone. A group of the newly united Latter-day Saints was organized in Gaborone on June 24, 1990. In 1991, the group became a branch, with Kwasi Agyare-Dwomoh, a Ghanaian man who had been baptized the previous year, as president.","A year later, the congregation had grown sufficiently to become two congregations, and Agyare-Dwomoh was called as president of the new Gaborone Botswana District to supervise the two branches. The district was dissolved in 1995 to allow district officers to serve in the branches; Botswana’s congregations were then placed under the supervision of the Roodepoort South Africa Stake rather than the mission headquartered in Johannesburg, South Africa. As the Church spread outside of Gaborone, congregations were established in other areas, such as Lobatse in October 1992 and Francistown in April 1993.","Botswana’s Latter-day Saints did more than worship together on Sundays. They also served together, visiting orphanages and schools for the disabled and volunteering on projects to provide clean water and immunizations. Other projects from the Church included donating wheelchairs, training on maternal and newborn care, providing vision care, and offering a variety of local community projects. The first edition of the Book of Mormon in Tswana, Botswana’s most widely spoken language, was published in 2003. Another milestone was reached in 2012 when the Gaborone Botswana Stake was organized on November 4 with Clement Mosiami Matswagothata as president. On April 5, 2025, Matswagothata was sustained as a General Authority Seventy during the Church’s annual general conference."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/botswana?lang=eng","asOf":"2025-12-31","stakes":null,"districts":1,"familySearchCenters":4,"id":"botswana","kind":"country","firstMissionaries":{"year":1990,"said":"Latter-day Saints living in Botswana were organized into an official congregation in 1990, and missionaries arrived the same year."},"began":null,"lat":-23.168178,"lng":24.592874},{"name":"Burundi","members":2070,"congregations":12,"wards":0,"branches":12,"missions":null,"stakes":null,"districts":null,"familySearchCenters":1,"temples":null,"history":[],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/burundi","asOf":"","id":"burundi","kind":"country","continent":"Africa","firstMissionaries":null,"began":null,"lat":-3.426449,"lng":29.932452},{"name":"Cameroon","members":3673,"congregations":20,"wards":5,"branches":15,"missions":1,"temples":0,"capital":"Yaoundé","languages":"French","continent":"Africa","summary":["Beginning in 1991, Cameroonian Latter-day Saints who had joined the Church elsewhere began gathering in Yaoundé. The Bastos Branch was formed in 1993, and the first full-time missionaries from Cameroon began proselytizing in Côte d’Ivoire the following year."],"history":["Many citizens of Cameroon joined The Church of Jesus Christ of Latter-day Saints in other countries and then returned home. Beginning in 1991, these local members gathered together to form the core of the Church in Yaoundé, meeting and initiating the process for official government recognition. In 1993, the Bastos Branch was organized, with Zang Gervais Gerard as president and Ngo Peggy as Relief Society president, and the Church received legal recognition. The following year, the first three full-time missionaries from Cameroon began service in the Ivory Coast Abidjan Mission.","The Church presence in Cameroon continued to grow, both in terms of the expanding Latter-day Saint congregations and an increasing number of humanitarian projects that served all members of local society. A temple trip in 2005 was memorable not only because of the obstacles members overcame as they journeyed to the house of the Lord but also because of the energy and enthusiasm this shared experience subsequently brought to local Church culture. Local members shouldered the responsibility of leading Cameroon’s numerous branches, responding to the words of the Lord’s timeless call: “Gather my saints together unto me; those that have made a covenant with me by sacrifice” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/cameroon?lang=eng","asOf":"2025-12-31","id":"cameroon","kind":"country","firstMissionaries":{"year":1991,"said":"Beginning in 1991, Cameroonian Latter-day Saints who had joined the Church elsewhere began gathering in Yaoundé. The Bastos Branch was formed in 1993, and the first full-time missionaries from Cameroon began proselytizing in Côte d’Ivoire the following year."},"began":null,"lat":4.612552,"lng":13.153581},{"name":"Cape Verde","members":16334,"congregations":41,"wards":27,"branches":14,"missions":1,"temples":0,"capital":"Praia","languages":"Portuguese (Brazil)","continent":"Africa","summary":["In 1989, Latter-day Saints in Praia formed a branch shortly after welcoming missionaries to their island country. As their nation transitioned to a democratic government, Church members began sharing the gospel more freely. Cape Verdean Saints now have four stakes and a temple, which was dedicated in 2022."],"history":["Beginning in the late 1980s, many Cape Verdean Saints were baptized in Portugal before returning to their homeland, where they began building the Church in Cape Verde. In 1989, shortly after missionaries arrived that March, Church meetings began in the home of Policarpo and Ofelia Gomes, even before the Gomeses had been baptized. In June 1989, the Praia branch was organized.","As their nation transitioned to a democratic government, the members began sharing the gospel more freely. The Church continued to grow, and soon branches were also organized on the islands of São Vincente and Fogo. A district was organized in November 1992.","Throughout their history, the Cape Verdean Saints have reached out in service. In 1995, Relief Society sisters in Praia provided clothing and food to 1,000 people displaced by volcanic eruptions on the island of Fogo. In the years since, the Cape Verdean Saints have “press[ed] forward” with a “perfect brightness of hope, and a love of God and of all men” as they have served one another and their community (","). Through the years, members organized career and education fairs, contributed to Church welfare services, and donated supplies to other faiths.","In October 2012, the Praia Cape Verde Stake was organized, with additional stakes in Assamada São Felipe on Fogo organized soon after. On October 7, 2018, the Cape Verdean Saints celebrated the announcement of a temple in Praia."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/cape-verde?lang=eng","asOf":"2021-12-31","id":"cape-verde","kind":"country","firstMissionaries":{"year":1989,"said":"In 1989, Latter-day Saints in Praia formed a branch shortly after welcoming missionaries to their island country."},"began":null,"lat":16.000055,"lng":-24.008395},{"name":"Central African Republic","members":null,"congregations":3,"wards":0,"branches":3,"missions":null,"stakes":null,"districts":null,"familySearchCenters":null,"temples":null,"history":["The first known member living in Central Africa Republic was a returned missionary with the United States Peace Corps in 1991. She shared the gospel with many of her associates and in September 1991 was set apart as a district missionary.","In September 1992, 20 converts were baptized and two branches (small congregations) organized in Bangui. A few months later a French missionary couple arrived.","For Journalist Use Only","Sean Donnelly Phone: 27-11-645-1565"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/central-african-republic","asOf":"","id":"central-african-republic","kind":"country","continent":"Africa","firstMissionaries":{"year":1991,"said":"The first known member living in Central Africa Republic was a returned missionary with the United States Peace Corps in 1991."},"began":null,"lat":7.03236,"lng":19.998123},{"name":"Cote d'Ivoire","members":71182,"congregations":274,"wards":174,"branches":100,"missions":4,"stakes":null,"districts":9,"familySearchCenters":57,"temples":1,"history":["In 1980 Ivorians Lucien Affoué joined the Church in France, and Philippe Assard joined in Germany. A few years later, both their families felt prompted to return to their homeland and that the Lord would be with them (see Genesis 31:3 ). Church leaders asked Assard to be a shepherd to the handful of Ivorian Saints who had also been baptized abroad and then returned. In 1987 Côte d’Ivoire was dedicated for the preaching of the gospel, and the first baptisms in the country took place that same year. By the early 1990s, many Ivorian youth were serving missions or preparing to serve. In 1993 over 300 attended the first youth conference in the country. The Church grew quickly in Côte d’Ivoire: the first stake was organized in 1997, and the 12th stake was organized just 20 years later.","Initially many Ivorian Saints sacrificed to travel to Switzerland or South Africa to make temple covenants. After the Accra Ghana Temple was dedicated in 2004, Ivorian Saints stood out for their dedication to family history and temple work. They organized regular group temple trips, bringing their own family names and their own ordinance workers. In 2015 President Thomas S. Monson announced that a temple would be built in Abidjan.","For Journalist Use Only","Sadia Zouzou","Phone: +225 0315 3980","Email"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/cote-d-ivoire","asOf":"","id":"cote-d-ivoire","kind":"country","continent":"Africa","firstMissionaries":{"year":1987,"said":"In 1987 Côte d’Ivoire was dedicated for the preaching of the gospel, and the first baptisms in the country took place that same year."},"began":null,"lat":7.989737,"lng":-5.567946},{"name":"Democratic Republic of the Congo","members":159771,"congregations":431,"wards":322,"branches":109,"missions":7,"temples":1,"capital":"Kinshasa","languages":"French","continent":"Africa","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","The Church in Democratic Republic of the Congo","The Democratic Republic of the Congo first recognized the Church as a legal entity in 1986, when the country was known as Zaire. Since then, the Church has grown quickly while Congolese Latter-day Saints have worked to serve others in their communities. The first temple in a French-speaking African country was dedicated in Kinshasa in 2019."],"history":["In the 1960s, several Congolese converts who had been baptized elsewhere returned to their homeland and began petitioning Church headquarters to send missionaries to the Democratic Republic of the Congo. In 1979, after receiving several letters Church President Spencer W. Kimball sent Oscar McConkie, a Church attorney, to explore the possibility of organizing the Church in Zaïre (later renamed the Democratic Republic of the Congo).","Although legal registration took nearly seven years, early converts met together in small groups and shared their faith with neighbors. When the first missionaries, Ralph and Jean Hutchings, arrived in February 1986, there were several groups meeting each week. In June 1986 a district was organized, and the following year a mission was created in Kinshasa. On August 30, 1987, Elder Marvin J. Ashton of the Quorum of the Twelve Apostles traveled to Kinshasa and dedicated the Congo for the preaching of the gospel.","Though the mission briefly closed in the early 1990s, members continued to share the gospel. In 1996 the first stake in Kinshasa was created, and in 1997 the first stake in Lubumbashi was formed. Church members kept the faith and ministered to each other through the conflict of the late 1990s and early 2000s. During the October 2011 general conference, Church President Thomas S. Monson announced plans for a temple to be built in Kinshasa. It was dedicated in 2019."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/democratic-republic-of-the-congo?lang=eng","asOf":"2025-12-31","id":"democratic-republic-of-the-congo","kind":"country","firstMissionaries":{"year":1986,"said":"When the first missionaries, Ralph and Jean Hutchings, arrived in February 1986, there were several groups meeting each week."},"began":null,"lat":-2.981434,"lng":23.822264},{"name":"Ethiopia","members":2626,"congregations":10,"wards":0,"branches":10,"missions":1,"stakes":null,"districts":2,"familySearchCenters":2,"temples":null,"history":["The first members in Ethiopia were expatriates attached to embassies who held Church meetings in homes in Addis Ababa. In March 1985 Church Apostle Elder M. Russell Ballard and Elder Glenn L. Pace of the Seventy visited Addis Ababa with Church relief supplies. The Church donated some $2.8 million for famine relief and irrigation development in Ethiopia and neighboring countries, such as Sudan.","The Kenya Nairobi Mission, which includes Ethiopia, was created in 1991, and the first official Church meeting was held in Addis Ababa in August 1992. In 1993 the Church was legally registered and the first missionary couple arrived. In February 1993 the first missionaries arrived, Elder Eugene and Sister Ruth Hilton. The Church was legally registered on 16 September 1993.","The Addis Ababa Branch (a small congregation) was created in January 1994 and was presided over by Girma Denisa. He was the first Ethiopian to serve the Church as a full-time missionary.","A representative from Ethiopia attended the lighting ceremony for the 1995 Festival of Lights at the Washington D.C. Temple Visitors' Center in 1995. Ethiopia was among some 50 nations represented at the widely publicized event.","Members from Ethiopia traveled to Nairobi, Kenya, to see President Gordon B. Hinckley when he visited there on 17 February 1998. In 2003 the Church donated several thousand tons of food to famine victims in Ethiopia.","For Journalist Use Only","Getachew Biru Baye Mobile: 251 911 402 517"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/ethiopia","asOf":"","id":"ethiopia","kind":"country","continent":"Africa","firstMissionaries":{"year":1993,"said":"In 1993 the Church was legally registered and the first missionary couple arrived."},"began":null,"lat":10.21167,"lng":38.65212},{"name":"Ghana","members":122978,"congregations":401,"wards":216,"branches":185,"missions":6,"temples":1,"capital":"Accra","languages":"English","continent":"Africa","summary":["Ghana initially received the restored gospel in the 1960s when Ghanaians discovered literature about the Church, believed the doctrines they found, and began sharing their new faith. They petitioned the Church to send missionaries so they could be baptized, and the first missionaries arrived in 1978. West Africa’s first temple, the Accra Ghana Temple, was dedicated in 2004."],"history":["Latter-day Saints in Ghana exemplified incredible patience by continuing in faith even amidst opposition. In the 1960s, several Ghanaians read the Book of Mormon, gained testimonies, and began to petition Church leaders to organize branches in Ghana. A policy preventing priesthood ordination for men of Black African descent made it difficult to provide sufficient leadership for branches in West Africa. Undeterred, local believers, including R. A. F. Mensah, J. W. B. Johnson, and Rebecca Mould, established independent congregations and awaited the day when the Church would organize branches in Ghana.","In 1978, Church President Spencer W. Kimball received a revelation extending priesthood ordination to all worthy men and directed that missionaries be sent to Ghana. Hundreds of believers were baptized, branches were organized, and a mission was established. For the next decade, the Church grew in Ghana at an accelerated pace.","In 1989–90, the government banned the activities of several religious organizations, including the Church. For more than a year, Ghanaian Saints continued to practice their faith in their homes. After the freeze ended, Saints continued to work to share the gospel and to build the Church. In 1998, Church President Gordon B. Hinckley visited Ghana and announced that a temple—the first in West Africa—would be built in Accra. The Accra Ghana Temple was dedicated in 2004."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/ghana?lang=eng","asOf":"2025-12-31","id":"ghana","kind":"country","firstMissionaries":{"year":1978,"said":"They petitioned the Church to send missionaries so they could be baptized, and the first missionaries arrived in 1978."},"began":null,"lat":8.030028,"lng":-1.080027},{"name":"Kenya","members":24547,"congregations":102,"wards":23,"branches":79,"missions":2,"temples":1,"capital":"Nairobi","languages":"Swahili","continent":"Africa","summary":["In 1979, one year after the revelation extending priesthood ordination to men of African descent, many Kenyans began to show interest in the Church. After years of effort, the Church received recognition in February 1991 and began to grow quickly. The Nairobi Kenya Temple, the first in East Africa, was dedicated in 2025."],"history":["Beginning in the late 1960s, American expatriate Latter-day Saints in Kenya held Church services in their homes. This practice continued over the next 20 years, with Saints occasionally inviting their friends and neighbors to their meetings, sharing Church literature, and teaching the gospel in small, private ways. During this time, Kenyans living abroad also encountered Latter-day Saints, and a few were baptized.","In 1979, one year after the revelation extending the full blessings of the restored gospel to persons of African descent, many Kenyans began to investigate the Church. Many who embraced the restored gospel sought baptism. However, some local authorities were hostile to the new religious group and would not allow the Church to perform ordinances. For many years, these Saints patiently practiced their faith in private, fasted and prayed in hope of recognition, and diligently petitioned officials. Finally, in February 1991, the Church received recognition. Through this trial, Kenyan Saints found “glory in tribulations” and reason to “rejoice in hope of the glory of God” (see","After securing recognition, the Church grew quickly. The three branches in the Nairobi area in 1991 soon developed into many, as members invited their friends and neighbors to join them, and new converts were baptized throughout the country. In September 2001, the Nairobi Kenya Stake was organized.","Through their faithful service, Kenyan Saints have worked alongside their neighbors to build communities, increase access to resources, and share the light of the gospel.","The construction of the Nairobi Kenya Temple was announced during the April 2017 general conference."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/kenya?lang=eng","asOf":"2025-12-31","id":"kenya","kind":"country","firstMissionaries":null,"began":{"year":1979,"said":"In 1979, one year after the revelation extending priesthood ordination to men of African descent, many Kenyans began to show interest in the Church."},"lat":0.279317,"lng":37.516494},{"name":"Lesotho","members":2278,"congregations":8,"wards":0,"branches":8,"missions":null,"stakes":null,"districts":null,"familySearchCenters":2,"temples":null,"history":["Scattered Church families from the United States lived in Lesotho during the 1980s. In July 1988, at a meeting attended by 15 people, the Maseru Branch (a small congregation) was organized at the home of expatriates. The Church was registered in July 1989 and the first missionaries entered in September. As the branch grew, facilities were rented in a local school. Later a home was purchased to be remodeled into a church building.","A seminary program for young people aged 14-18 functioned in the country as early as 1991. The first full-time young missionary from Lesotho began serving in the Durban mission in 1993.","On February 18, 1996, members from Lesotho were among some 5,000 who attended the Johannesburg Regional Conference---the largest Church gathering assembled to this point in South Africa."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/lesotho","asOf":"","id":"lesotho","kind":"country","continent":"Africa","firstMissionaries":{"year":1989,"said":"The Church was registered in July 1989 and the first missionaries entered in September."},"began":null,"lat":-29.603927,"lng":28.335019},{"name":"Liberia","members":25767,"congregations":86,"wards":51,"branches":35,"missions":1,"temples":0,"capital":"Monrovia","languages":"English","continent":"Africa","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Thanks to the dedication of Liberians who had accepted the teachings of the Book of Mormon, Latter-day Saint missionaries arrived in Liberia in the late 1980s and found many ready to be baptized. The faithful Saints ministered to each other during Liberia’s civil wars, which were fought between 1989 and 2003. In 2000 the first stake in Liberia was created."],"history":["In 1985 Joe C. Jarwleh read the Book of Mormon and shared it with fellow members of the Temple of Christ Church, a group interested in early Christianity. When senior missionaries came to Liberia two years later, many members of this group were baptized. By 1989 a district was organized in Monrovia, but that December the First Liberian Civil War began.","During the civil war, many members were scattered or killed. Some fled to other nations and built up the Church there. Others stayed and found ways to minister to one another through the conflict. Even when severely tried, the Saints were determined to follow the example of Nephi and “go and do” the things the Lord commanded (see","The Saints endured faithfully through the conflict, and in 2000 the first stake in Liberia was created. Members there have consistently joined other West African Saints in annual days of service, conferences, and historical commemorations. In 2015 Latter-day Saints helped provide food, cooking oil, and sanitation supplies to people in need during the Ebola outbreak. By 2017 there were four stakes in Liberia and numerous Liberian Latter-day Saints around the world."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/liberia?lang=eng","asOf":"2025-12-31","id":"liberia","kind":"country","firstMissionaries":null,"began":{"year":1985,"said":"In 1985 Joe C. Jarwleh read the Book of Mormon and shared it with fellow members of the Temple of Christ Church, a group interested in early Christianity."},"lat":5.749972,"lng":-9.365852},{"name":"Madagascar","members":20395,"congregations":52,"wards":30,"branches":22,"missions":2,"temples":0,"capital":"Antananarivo","languages":"Malagasy","continent":"Africa","summary":["Malagasy Latter-day Saints who had been baptized abroad began returning home in the 1970s and shared the gospel they had embraced. They formed the first official congregation in 1990."],"history":["The Church announced that it would send missionaries to Madagascar in March 1979. However, plans changed because of government reluctance to grant permission to an unknown church. Instead, Malagasy men and women who were baptized while living abroad laid the foundation for the Church in their country. Perhaps the first was Mamy Raoelijaona, a student living in France who was baptized in 1971. He returned to Madagascar the next year but did not know of any other Latter-day Saints in the country and had no contact with the Church. He married and had four children before returning to France in 1981, partly so he and his family could participate in the Church.","Dominique Andriamanantoa was baptized in Toulouse, France, in 1985. In 1986 he was called to the California Anaheim Mission, becoming the first Malagasy Latter-day Saint to serve a full-time mission.","After joining the Church in France, Razanapanala Ramianadrisoa returned to Madagascar in 1988, began teaching others about the Church, and held unofficial church services in his father’s home. One of those whom Razanapanala taught was Jean-Claude Rafenonirina, who on November 9, 1988, became the first person baptized in Madagascar . An official branch of the Church was organized on September 23, 1990, with Razanapanala as president.","The first missionaries the Church sent to Madagascar, Fred and Eileen Forsgren, arrived in March 1991 to support the new branch. Proselytizing missionaries Elders Jeffry Gifford and Jason Tarbet came in September 1992. Despite missionaries initially teaching in French rather than the more widely understood Malagasy language, many Malagasies responded enthusiastically to their message. There were enough Latter-day Saints to organize a district on April 14, 1996. Missionaries eventually began teaching in Malagasy, and a Malagasy translation of the Book of Mormon was published in 2000. That same year, the first stake was organized on September 17, with Dominique Andriamanantoa as president.","In addition to sending missionaries who spread the message about the gospel of Jesus Christ, the Church provided development and humanitarian assistance in Madagascar, including funds for a small birthing hospital and for shelters for those displaced by natural disasters. On October 3, 2021, Church President Russell M. Nelson announced a temple would be built in Madagascar. Ground was broken and construction officially began on March 15, 2025."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/madagascar?lang=eng","asOf":"2025-12-31","stakes":null,"districts":1,"familySearchCenters":16,"id":"madagascar","kind":"country","firstMissionaries":{"year":1979,"said":"The Church announced that it would send missionaries to Madagascar in March 1979."},"began":null,"lat":-18.92496,"lng":46.441642},{"name":"Malawi","members":7857,"congregations":21,"wards":10,"branches":11,"missions":0,"temples":0,"capital":"Lilongwe","languages":"English","continent":"Africa","summary":["Malawians encountered the Church as early as the 1970s. Some established unofficial congregations, leading to the organization of the first official congregation in 1999."],"history":["In 1978, McDunstan A. Minikwa met missionaries from The Church of Jesus Christ of Latter-day Saints in Toulouse, France. Minikwa believed their message but returned home to Malawi without being baptized. He returned to France and became the first Malawian to be baptized on July 10, 1979. Also in 1978, McFarlane Phiri was given a copy of the book","by a friend who was not a Latter-day Saint. He subsequently began a long correspondence with Church leaders while sharing with others the knowledge and materials he received, including the Book of Mormon.","Phiri and his associates established an unofficial congregation in Sitima Village. In early July 1992, missionaries arrived and baptized Phiri and 32 others during a brief visit. A few other Latter-day Saint Malawians who had been baptized while living abroad were scattered about the country. Some of them met with expatriate Latter-day Saints living around Lilongwe. The Sitima Village congregation was officially organized into the first branch, with Phiri as its president, on May 23, 1999. Missionaries also arrived that year to begin formal proselytizing in Blantyre, holding church services in their home. These services were attended by Leonard and Mary Nchika, two Malawians who had been baptized while living in Zimbabwe and returned to their native country in 1998.","On July 30, 2000, the group in Blantyre was organized into a branch, with Raymond Chisamboas branch president. The group in Lilongwe became a branch on August 14, 2007, led by Lyson Jerson Ntholowa. New congregations were created as membership grew. On April 10, 2011, the branches around Blantyre were organized into Malawi’s first district with Peter Chinyumba as president. Elder Russell M. Nelson of the Quorum of the Twelve Apostles dedicated Malawi for the preaching of the gospel on October 25, 2011. A translation of the Book of Mormon in Chewa, Malawi’s most widely spoken language, was published in 2023. The Lilongwe and Blantyre districts became stakes in June 2024, with Gregory V. Yohanne as president of the Lilongwe stake and Gabriel Chinomwe as president of the stake in Blantyre."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/malawi?lang=eng","asOf":"2025-12-31","stakes":null,"districts":null,"familySearchCenters":3,"id":"malawi","kind":"country","firstMissionaries":{"year":1978,"said":"In 1978, McDunstan A. Minikwa met missionaries from The Church of Jesus Christ of Latter-day Saints in Toulouse, France."},"began":null,"lat":-13.26872,"lng":33.930196},{"name":"Mauritius","members":612,"congregations":3,"wards":0,"branches":3,"missions":0,"temples":0,"capital":"Port Louis","languages":"English","continent":"Africa","summary":["Although the restored gospel was first preached in Mauritius in the mid-1850s, a lasting presence began in the 1970s. Latter-day Saints who joined the Church abroad wanted to share the gospel with their brothers and sisters at home. In the 1980s the Church received legal recognition, the first branch was organized, and the first missionaries from Mauritius were called."],"history":["In 1856 George F. W. Kershaw preached in Mauritius, but no lasting Church presence was established at the time. The modern history of the Church in Mauritius began in the 1970s, when Mauritians who joined the Church abroad felt a desire to “impart the word of God to their brethren [and sisters]” (",") and wrote to Church leaders, asking for missionaries to be sent to relatives living in Mauritius. In 1981, after the first missionaries were sent, Harold Essoo, Rowen Narraidoo, Gerard Goder, Alain Kheeroo, Jayprakash Mohabeer, and Jocelyn Lenette became the first Mauritians baptized on the island. In the 1980s, the first branch was organized, the Church received official legal recognition, and the first missionaries from Mauritius were called.","In 1988 Elder Marvin J. Ashton visited Mauritius to offer a dedicatory prayer. “We know this land is a link between Western and Eastern cultures,” he noted in the prayer, referring to the melting pot of African, Indian, Chinese, and European ancestry and cultures in the country. “We dedicate this beautiful island … in accordance with Thy present and future plans for not only the growth, but the prosperity and peace that the gospel can bring.” In 2017, with branches in Rose Hill, Phoenix, and Flacq, the first district in Mauritius was organized."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/mauritius?lang=eng","asOf":"2025-12-31","id":"mauritius","kind":"country","firstMissionaries":{"year":1856,"said":"In 1856 George F. W. Kershaw preached in Mauritius, but no lasting Church presence was established at the time."},"began":null,"lat":-20.275945,"lng":57.570357},{"name":"Mozambique","members":39282,"congregations":90,"wards":59,"branches":31,"missions":2,"temples":0,"capital":"Maputo","languages":"Portuguese (Brazil)","continent":"Africa","summary":["Mozambicans and others who had been baptized while living abroad shared their faith and established the first congregation in 1992."],"history":["While studying in Germany, Chico Mapenda met missionaries from The Church of Jesus Christ of Latter-day Saints on Christmas Day, 1989. He was baptized less than three weeks later, on January 14, 1990. By the end of that year, he was back in his native Mozambique, sharing his newfound faith with friends and family, including his brother Gimo. When Church leaders visited Mozambique in 1991, they found that the Mapenda brothers were leading several unofficial congregations of up to 150 persons around Beira, one of Mozambique’s largest cities.","In the midst of a devastating drought, the Church sent more than one million pounds of food and other items to Mozambique in 1992. That same year Samo P. Gonçlaves was baptized while studying in Portugal. Upon his return to Mozambique, he found other Mozambican and Brazilian Latter-day Saints around the capital, Maputo, who had also been baptized while living abroad. Gonçlaves was called to lead the first official congregation when it was organized in Maputo in 1994. Meanwhile, the mostly unbaptized believers around Beira waited for their own official congregation, which was organized in 1996. Missionaries from the South Africa Johannesburg Mission arrived in June 1999, and Elder Richard G. Scott, an apostle, dedicated Mozambique for the preaching of the Gospel on October 29.","After receiving a request from Chico Mapenda’s father-in-law, Francisco Dique Sousa, the Church sent four missionaries to Marromeu in May 2000. Fifty-five persons were baptized over the next three months, and a branch was organized, led by Dique Sousa. With rapid Church growth, districts were established in Beira and Maputo in 2003. The growing Church units served as bases for programs benefitting Mozambican communities, such as HIV/AIDS awareness and prevention initiatives and vaccination campaigns for measles and polio. On December 20, 2004, a new mission was created with headquarters in Maputo. The Beira and Maputo Districts became stakes in 2015 and other stakes followed. On April 4, 2021, Church President Russell M. Nelson announced a temple would be built in Beira during the Church’s annual general conference. He announced a temple for Maputo on October 6, 2024."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/mozambique?lang=eng","asOf":"2025-12-31","stakes":null,"districts":3,"familySearchCenters":18,"id":"mozambique","kind":"country","firstMissionaries":{"year":1989,"said":"While studying in Germany, Chico Mapenda met missionaries from The Church of Jesus Christ of Latter-day Saints on Christmas Day, 1989."},"began":null,"lat":-19.302233,"lng":34.914498},{"name":"Namibia","members":1492,"congregations":5,"wards":0,"branches":5,"missions":0,"temples":0,"capital":"Windhoek","languages":"English","continent":"Africa","summary":["From 1930 to 1990 Latter-day Saint missionaries and other members occasionally came to Namibia and met in small groups, but no lasting Church presence was established. After Namibia gained independence in 1990, the new government allowed the Church to be registered. There are now several branches in Namibia."],"history":["In 1924, Lawrence and Maud Ratcliff, members of the Church from South Africa, established a small branch in Karibib in present-day Namibia. Soon afterward, the Ratcliffs moved to the United States, and the branch closed. From 1930 to 1990, missionaries and members occasionally came to the country for work and met in small groups, but no lasting presence was established.","After Namibia gained independence, the new government, which allowed freedom of worship, allowed the Church to be registered quickly. Shortly after, missionaries, led by a senior missionary couple, were sent to the country, and Namibian Saints who had joined the Church in other places began to return. The Windhoek Branch soon had many members attending weekly meetings. The Relief Society sisters began teaching childcare lessons to the community, and seminary classes began.","Namibian Saints quickly became “anxiously engaged” in building the Church in their communities and “bring[ing] to pass much righteousness” in their country (","). Members in Namibia have supported one another in long and expensive journeys to attend the temple in Johannesburg, South Africa; invited the elderly to an evening of food and entertainment; and contributed to the expansion of community gardens. There are now three branches in Windhoek, one branch in Swakopmund, and a growing group of members in Ongwediva."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/namibia?lang=eng","asOf":"2025-12-31","id":"namibia","kind":"country","firstMissionaries":{"year":1930,"said":"From 1930 to 1990 Latter-day Saint missionaries and other members occasionally came to Namibia and met in small groups, but no lasting Church presence was established."},"began":null,"lat":-23.23355,"lng":17.323111},{"name":"Nigeria","members":274043,"congregations":880,"wards":569,"branches":311,"missions":11,"temples":1,"capital":"Abuja","languages":"English","continent":"Africa","summary":["In the mid-20th century, many Nigerians learned about the Church from literature or friends and family. They believed and were faithful, despite the government’s refusal to allow missionaries into the country and the Church’s practice of restricting men of African descent from priesthood ordination. The Church was established in Nigeria following the 1978 revelation extending the priesthood to all worthy males."],"history":["In response to letters from Nigerians who had read about the Church and organized unofficial congregations, Church leaders attempted to establish a mission in Nigeria in the early 1960s. Because the Church was unable to obtain missionary visas and, at the time, did not ordain men of African descent to the priesthood, plans were eventually put on hold. After the Nigerian Civil War, Ime Eduok, Anthony Obinna, and others ministered to those who still longed to join the Church, waiting in faith and patience to inherit the promises of the gospel (see","Following President Spencer W. Kimball’s 1978 revelation extending priesthood ordination and temple blessings to worthy Church members of African descent, the Church was finally established in Nigeria. Many people had long looked forward to that day and were finally able to be baptized and invite relatives and friends to join the Church. Ten years later, the first stake in Nigeria was organized.","Saints in Nigeria have served their communities in many ways, practicing integrity and goodwill in their own lives and participating in organized Church efforts. Relief Society sisters took the lead on a literacy effort that aimed to help women become more self-reliant and gain personal testimonies of the Book of Mormon. Saints of all ages have participated in the Church’s annual All-Africa Mormon Helping Hands Day. In 2005, a temple was dedicated in Aba. By 2018, 40 years after the first converts were baptized there, more than 160,000 Saints lived in Nigeria."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/nigeria?lang=eng","asOf":"2025-12-31","id":"nigeria","kind":"country","firstMissionaries":null,"began":{"year":1978,"said":"The Church was established in Nigeria following the 1978 revelation extending the priesthood to all worthy males."},"lat":9.600036,"lng":7.999972},{"name":"Republic of the Congo","members":15482,"congregations":43,"wards":32,"branches":11,"missions":1,"temples":0,"capital":"Brazzaville","languages":"French","continent":"Africa","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","A few Congolese Latter-day Saints joined the Church in Europe in the 1980s and returned to what was then the People’s Republic of Congo. Around the same time, others in the Congo wrote letters to missions in other parts of the world requesting literature and missionaries. The first congregation was organized in 1991, a few months before missionaries arrived."],"history":["In the 1980s Latter-day Saints who had been baptized abroad began returning to the Republic of the Congo. In 1991 those in Brazzaville gathered together and, under the direction of the mission president across the Congo River in Kinshasa, began organizing the Church in the Republic of the Congo. The first baptisms took place in June 1991, and the government recognized the Church in October. By the time Elders Russell M. Nelson and Richard G. Scott of the Quorum of the Twelve Apostles visited in 1992 to dedicate the country for the preaching of the gospel, the first district had already been organized.","Although civil unrest later in the 1990s often disrupted the work of full-time missionaries, Latter-day Saints in the Republic of the Congo heeded the scriptures’ call to do the Lord’s work and share the gospel with their neighbors (see","). Even in times of violence, members helped and strengthened each other, often sharing what little they had. In 2003 the first stake in the country was organized in Brazzaville.","Saints in the Congo have worked to serve each other and their communities, offering self-reliance workshops for the economic advancement of members as well as offering training in other health and welfare causes. As members have gained experience, the Church has become more firmly established: by 2019 there were nearly 8,000 members living in two stakes."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/republic-of-the-congo?lang=eng","asOf":"2025-12-31","id":"republic-of-the-congo","kind":"country","firstMissionaries":{"year":1991,"said":"The first congregation was organized in 1991, a few months before missionaries arrived."},"began":null,"lat":-0.726433,"lng":15.641915},{"name":"Reunion","members":859,"congregations":4,"wards":0,"branches":4,"missions":0,"temples":0,"capital":"","languages":"Continent","continent":"Africa","summary":["In 1969, Alain and Danièle Chion-Hock returned to Réunion after being baptized in France. For years, they were the only members in Réunion until others arrived after being baptized abroad. In 1979, a branch was formed, and missionaries arrived in 1984."],"history":["In May of 1969 Alain and Danièle Chion-Hock returned with their family to Réunion after being baptized a month earlier in France. After living for years as the only Latter-day Saints on the island, they began meeting in the late 1970s with others who had joined the Church abroad and returned to Réunion. The first branch was organized in 1979, just after the arrival of Joseph T. and Ruth Edmunds, the first senior missionary couple on the island.","The small group of Réunionnais Latter-day Saints maintained their faith together, meeting in the Chion-Hock home and ministering to each other. The first proselytizing missionaries arrived in 1984; the next year, Nelly Lycurgue became the first member called from Réunion to serve a full-time mission. During the late 1980s and early 1990s, additional branches were established in Saint-Pierre, Le Port, and Sainte-Marie as people from the wide range of backgrounds that make up the population of Réunion joined the Church, coming together “in the unity of the faith” ("],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/reunion?lang=eng","asOf":"2024-12-31","id":"reunion","kind":"country","firstMissionaries":{"year":1979,"said":"In 1979, a branch was formed, and missionaries arrived in 1984."},"began":null,"lat":-21.130933,"lng":55.526577},{"name":"Rwanda","members":3625,"congregations":10,"wards":0,"branches":10,"missions":1,"temples":0,"capital":"","languages":"Continent","continent":"Africa","summary":["During the 1980s and 1990s a few Latter-day Saints were living in Rwanda, though there was no official Church organization. They began meeting regularly in the capital city, Kigali, in the early 2000s. The first congregation was organized in 2008, with Rwandans who had returned after joining the Church in other countries. The Church received government recognition in 2013."],"history":["In the 1980s and 1990s Church records listed up to seven members of the Church living in Rwanda, but individual Latter-day Saints were living without a Church organization in the country. In the early 2000s that changed as members began meeting regularly in Kigali. Nelson and Sapna Samuel, two returned missionaries from Bangalore, India, who had migrated to Rwanda, hosted early group meetings. When the first branch was organized in 2008, many of the members—including Fabien Hatangimbabazi, Yvonne Martin, Jean Marie and Agathe Rumanyika, and Ruth Opar—were Rwandans who had joined the Church in other countries and returned to their home country.","Though the Rwandan government put a moratorium on the registration of new churches that same year, Church members and leaders pressed forward in faith to prepare for the future. In 2009 Jeffrey R. Holland of the Quorum of the Twelve Apostles dedicated Rwanda for the preaching of the gospel, and in 2010 the country accepted a humanitarian missionary couple. Over the next few years, a wider range of Church programs was introduced, translation of Church literature to Kinyarwanda began, and Jackson Ndayambaje became the first missionary called from Rwanda. The Church finally received government recognition in 2013. By 2019 there were four branches in the Kigali Rwanda District."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/rwanda?lang=eng","asOf":"2025-12-31","id":"rwanda","kind":"country","firstMissionaries":{"year":2009,"said":"In 2009 Jeffrey R. Holland of the Quorum of the Twelve Apostles dedicated Rwanda for the preaching of the gospel, and in 2010 the country accepted a humanitarian missionary couple."},"began":null,"lat":-2.000205,"lng":30.000396},{"name":"Sierra Leone","members":41775,"congregations":118,"wards":78,"branches":40,"missions":2,"temples":0,"capital":"Freetown","languages":"English","continent":"Africa","summary":["Between 1981 and 1988 Sierra Leonean Latter-day Saints who had been baptized while living abroad began gathering in unofficial congregations. Missionaries arrived, and a branch formed in 1988. From 1991 to 1992, Latter-day Saints met to worship in their homes rather than in public due to civil unrest. In 2019 the Church announced that a temple would be built in Freetown."],"history":["In the 1980s, several Sierra Leoneans joined the Church while living in other countries. After returning to Sierra Leone and finding that the Church had not yet been established there, these faithful converts—including Michael Samura, Bai Sama Sankoh, Elizabeth Judith Bangura, Monica Orleans, and Christian George—worked independently to build the Church in the country. In 1988 the first missionaries arrived in Sierra Leone, and a branch in Freetown was soon established.","When war spilled over from Liberia into Sierra Leone in 1991, missionaries were evacuated. Just over 1,000 members were living in the country at the time. For nearly 11 years, as they endured violence and hunger, members put their trust in God and were “supported in their trials, and their troubles, and their afflictions” (","). They continued to meet often, support and uplift one another, and preach the gospel to their neighbors. By the end of the war in 2002, Church membership had grown more than fourfold to nearly 5,000.","In the decade after the war—despite ongoing regional conflict and the Ebola epidemic—growth continued and a stake was created in Freetown. Just five years later, nearly 20,000 members of the Church were living in five stakes and four districts in Sierra Leone."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/sierra-leone?lang=eng","asOf":"2025-12-31","id":"sierra-leone","kind":"country","firstMissionaries":{"year":1988,"said":"Missionaries arrived, and a branch formed in 1988."},"began":null,"lat":8.640035,"lng":-11.840027},{"name":"South Africa","members":78689,"congregations":197,"wards":112,"branches":85,"missions":4,"temples":2,"capital":"Cape Town, Pretoria, Bloemfontein","languages":"Afrikaans","continent":"Africa","summary":["Latter-day Saint missionaries first preached in South Africa in 1852. A few South Africans were baptized by subsequent missionaries, establishing a foothold on the continent. Growth was slow until a revelation in 1978 ended the practice of restricting priesthood ordination for men of African descent. Church membership now reflects the country’s racial diversity."],"history":["In 1852 Brigham Young called three missionaries to preach in the Cape of Good Hope. Over the next three years, they established six branches in and around Cape Town, where members kept the faith in the face of intense local opposition. Most early members ultimately emigrated, but a few were still in South Africa when missionaries returned in 1903 after a long absence. Over the next three decades, members established Church programs in their branches and shared the gospel in their communities and in other parts of southern Africa.","In the 1850s and early 1900s, there were a handful of members of the Church in South Africa who were of mixed race despite the Church’s restriction on priesthood ordination for black men, but after apartheid began in 1948, Church contact with non-white South Africans became increasingly rare. In the 1960s, as members in Johannesburg laid the foundation for the country’s first stake, a group of black believers in the Book of Mormon who had not yet been baptized met on their own in Soweto. Racial integration of congregations and official Church activity in townships began only after the 1978 revelation extending priesthood and temple blessings without regard to race.","Black, white, mixed-race, and Asian members celebrated the dedication of the Johannesburg South Africa Temple together in 1985. Members have brought the unique strengths of their diverse life experience to the Church, “endeavouring to keep the unity of the Spirit in the bond of peace” (","). In 2016, as the Church continued to grow, ground was broken in Durban for the country’s second temple."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/south-africa?lang=eng","asOf":"2025-12-31","id":"south-africa","kind":"country","firstMissionaries":{"year":1852,"said":"Latter-day Saint missionaries first preached in South Africa in 1852."},"began":null,"lat":-28.816624,"lng":24.991639},{"name":"Swaziland","members":2598,"congregations":6,"wards":0,"branches":6,"missions":null,"stakes":null,"districts":null,"familySearchCenters":2,"temples":null,"history":["In 1984 there were several families of non-African Church members living in Swaziland. The Mbabane Branch (a small congregation) was organized in 1985. In 1987 the government recognized the Church, the first missionaries arrived, and converts came into the Church.","By 1990 converts were serving full-time missions, and of the 115 members, only the branch president and his family were non-Africans. Swaziland's first Church building was dedicated in 1993 in a ceremony attended by government representatives and presided over by Elder Richard P. Lindsay of the Seventy, who was president of the Africa Area. At that time membership had grown to 650.","In 1996 members from Swaziland joined some 5,000 others at the Johannesburg regional conference, and in 1998 members in Swaziland traveled to Johannesburg to hear President Gordon B. Hinckley speak.","For Journalist Use Only","Watson Bheki Mamba Swaziland Phone: 09 268 404 2321 Phone: 09 268 404 2663 Mobile: 09 268 624 8265 Phone: 09 268 404 2661 Phone: 09 268 404 2664 Phone: 09 268 404 2662"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/swaziland","asOf":"","id":"swaziland","kind":"country","continent":"Africa","firstMissionaries":{"year":1987,"said":"In 1987 the government recognized the Church, the first missionaries arrived, and converts came into the Church."},"began":null,"lat":-26.562481,"lng":31.399132},{"name":"Tanzania","members":6259,"congregations":45,"wards":4,"branches":41,"missions":1,"stakes":null,"districts":3,"familySearchCenters":1,"temples":null,"history":["Two families from the United States and Canada living in Dar-es-Salaam began holding meetings in 1991. Tanzania was included in the newly formed Kenya Nairobi Mission, which was created in July 1991, and in 1992 the Church was legally recognized in Tanzania.","In February 1992 the first missionary couple arrived, and in December of that year a branch (a small congregation) was created in Dar-es-Salaam. Today there are three branches there. Members from Tanzania traveled to Nairobi, Kenya, in February 1998 to hear President Gordon B. Hinckley speak.","In March 2002 members of the Church in Tanzania made a 68-hour bus trip to the Johannesburg South Africa Temple, a trip that had been in the planning stages since July 2001.","For Journalist Use Only","Mpho Mokgare Phone: 00267 391 2667 Mobile: 00267 7279 6550"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/country/tanzania","asOf":"","id":"tanzania","kind":"country","continent":"Africa","firstMissionaries":{"year":1992,"said":"In February 1992 the first missionary couple arrived, and in December of that year a branch (a small congregation) was created in Dar-es-Salaam."},"began":null,"lat":-6.524712,"lng":35.787844},{"name":"Togo","members":8349,"congregations":31,"wards":19,"branches":12,"missions":0,"temples":0,"capital":"Lomé","languages":"French","continent":"Africa","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","Togo is a country in West Africa on the Gulf of Guinea. The organization of the Church began in 1997, with a branch being formed in 1999. In 2000, the Church gained legal recognition from Togo’s government. By 2014, the Church grew large enough to organize its first stake."],"history":["In the 1980s, a few dozen Togolese people joined the Church while living abroad. It was not until the mid-1990s, however, that a man named Dieudonné Attiogbe brought those who had returned to Togo into contact with each other. As a result of their efforts, the first Church group in Togo was officially organized in 1997. With encouragement and support from Saints in Ghana and Côte d’Ivoire, the group developed into a branch by 1999. The next year, the Church gained legal recognition from Togo’s government.","The first district in Togo was organized in Lomé in 2009; just four years later it became a stake. “Where rapid growth sometimes comes at the cost of maturity and depth, that is not the case in Lomé,” Elder Terence M. Vinson of the Africa West Area Presidency observed at the time. Saints in Togo heeded the scriptural call for Zion to “strengthen [its] stakes and enlarge [its] borders” (","), and as a result, a second stake was organized in 2017."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/togo?lang=eng","asOf":"2025-12-31","id":"togo","kind":"country","firstMissionaries":null,"began":{"year":1997,"said":"The organization of the Church began in 1997, with a branch being formed in 1999."},"lat":8.780026,"lng":1.019977},{"name":"Uganda","members":26304,"congregations":62,"wards":26,"branches":36,"missions":1,"temples":0,"capital":"Kampala","languages":"Swahili","continent":"Africa","summary":["Beginning in February 1990, Ugandan Latter-day Saints who had been baptized while living abroad began worshipping together. Later that year, the first Ugandan was baptized in the country. A congregation was officially organized in the capital city of Kampala on March 3, 1991."],"history":["Though home-based meetings were held by Latter-day Saints living in Uganda as early as 1969, no permanent establishment of the Church occurred until much later. Beginning in the late 1980s, Ugandans living in Europe and the United States learned the restored gospel, converted, and later returned to their homeland bearing the message. In February 1990, a small group of Saints and their neighbors began holding regular meetings. A branch was organized in Kampala the following year.","After the first branch was organized, missionaries and members began sharing the gospel with friends, family, and neighbors throughout the country. Within two years, districts had been organized in Kampala and Jinja, and branches were being organized throughout the country. In 2010, the Kampala Uganda Stake was organized.","Ugandan Saints have sought opportunities to build stronger communities by applying the principles of the gospel. They seek to help one another learn the gospel and diligently act in the callings they receive (see","). They have participated in service projects to clean and build their communities. This has included innovative thinking. Footraces and special drives have been organized to encourage donations to those in need. Community projects have cleaned and painted public spaces, and special classes focused on the needs of specific groups have been organized."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/uganda?lang=eng","asOf":"2025-12-31","id":"uganda","kind":"country","firstMissionaries":null,"began":{"year":1969,"said":"Though home-based meetings were held by Latter-day Saints living in Uganda as early as 1969, no permanent establishment of the Church occurred until much later."},"lat":1.533355,"lng":32.216658},{"name":"Zambia","members":7823,"congregations":20,"wards":6,"branches":14,"missions":1,"temples":0,"capital":"Lusaka","languages":"English","continent":"Africa","summary":["Latter-day Saints moved to present-day Zambia from South Africa and Zimbabwe in the 1940s. They organized congregations and built meetinghouses, but the government of the newly independent Zambia stopped granting missionary visas, and many of the Latter-day Saints left the country in the 1960s. Church operations fully resumed in the 1990s."],"history":["Latter-day Saints first arrived in the Copperbelt region of Zambia in the 1940s. Branches in Luanshya and Kitwe were established before 1964, when Northern Rhodesia became the independent Republic of Zambia. By 1969 the branches had been dissolved and missionary work in the country ended. Despite occasional petitions to reestablish the Church in the country, little Church activity occurred in Zambia for the next two decades.","However, many Zambians living outside of the country found the restored gospel, joined the Church, and began to return to Zambia. By 1991 several converts who had returned to various places in Zambia were asked to help register the Church and prepare for missionaries to return. In 1992, when a branch was organized in Lusaka, Johnson Makombé was called as the branch president.","The Church in Zambia has grown steadily since that first branch as Zambian Saints have “[served] the Lord with gladness” (Psalm 100:2). Since 1995 Zambian Saints have made long bus trips to the temple in Johannesburg, South Africa, to perform ordinances for themselves and their ancestors. Members in Zambia have also volunteered countless hours to serve their neighbors. For example, in 2012 Church members assisted with a national campaign to provide measles vaccines to Zambian children.","The first stake in Zambia was organized in Lusaka in March 2015. Today, there are more than 4,000 Latter-day Saints in Zambia."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/zambia?lang=eng","asOf":"2025-12-31","id":"zambia","kind":"country","firstMissionaries":{"year":1969,"said":"By 1969 the branches had been dissolved and missionary work in the country ended."},"began":null,"lat":-14.518912,"lng":27.558988},{"name":"Zimbabwe","members":52430,"congregations":123,"wards":77,"branches":46,"missions":2,"temples":0,"capital":"Harare","languages":"English","continent":"Africa","summary":["f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","f.family.startsWith('Ensign')?f.display='swap':'')\"/>","South African Latter-day Saints settled in present-day Zimbabwe in the 1920s, but the lack of official missionaries and the restriction on priesthood ordination for men of African descent slowed growth. The end of those restrictions and the achievement of political independence led to increased growth in the 1980s, and a temple in the capital of Harare was dedicated in 2025."],"history":["The beautiful land of Zimbabwe has been home to Latter-day Saints since the 1930s. In the early decades of establishing the Church, European settlers traveled long distances to meet with each other in centers such as Salisbury (later Harare), Bulawayo, and Gweru and occasionally made even longer journeys to attend church conferences in South Africa.","The removal of racial restrictions on Church participation in 1978 brought an era of transition. Latter-day Saints of diverse backgrounds strove to create a space for unity amid racial and political tensions. In the 1980s and 1990s, the Church grew among local populations of Zimbabweans speaking primarily Shona and English. In 1999 the Book of Mormon was published in Shona, and the first stake in Zimbabwe was established in Harare. In times of hardship, Latter-day Saints reached out through congregational networks to support each other.","Beginning in 1985, Latter-day Saints traveled to Johannesburg for temple ordinances. In 2020 ground was broken for the Harare Zimbabwe Temple.","The resilience and perseverance of the Latter-day Saints in Zimbabwe, along with the good fruits of their efforts, bring to mind the Savior’s promise: “Blessed are they which do hunger and thirst after righteousness: for they shall be filled” (Matthew 5:6)."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/zimbabwe?lang=eng","asOf":"2025-12-31","id":"zimbabwe","kind":"country","firstMissionaries":null,"began":{"year":1978,"said":"The removal of racial restrictions on Church participation in 1978 brought an era of transition."},"lat":-18.455496,"lng":29.746841},{"name":"Alabama","members":41252,"congregations":75,"wards":47,"branches":28,"missions":1,"temples":1,"capital":"Montgomery","languages":"","continent":"North America","summary":["Since its establishment in 1843, the Church in Alabama has grown substantially, with a temple dedicated in Birmingham in 2000."],"history":["The 1843 experience of missionary John Brown in Alabama is typical of early missionaries for The Church of Jesus Christ of Latter-day Saints. Community members assumed the 17-year-old in ragged clothing was “a simple cotton picker.” They gathered to hear him speak one day, eager to mock the young preacher. However, after he began the crowd members grew quiet and “as motionless as statues of marble.” In the days following Brown’s sermon, people treated him with respect and the Church started to grow in the state . In early 1844, there were approximately 120 members of the Church in Alabama organized in three congregations. Three months later, in areas including Mississippi, there were approximately 190 members in seven congregations.","Many of these early converts eventually left Alabama to join the main body of Latter-day Saints in the Utah Territory, but missionary work in the state continued. In 1930, there were approximately 2,500 members of the Church in Alabama. The Church in Alabama also benefited from an influx of members who came to the state as a result of their employment by the military and the National Aeronautics and Space Administration. In 1968 the first stake in Alabama was formed in Huntsville.","Today, there are more than 35,000 Church members living in Alabama organized into eight stakes. In 2000 the Church dedicated a temple in Birmingham. When Alabama was affected by natural disasters in recent years, such as the series of tornadoes that destroyed property throughout the state in March 2021, Church members partnered with community leaders to assist in cleanup efforts."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/alabama?lang=eng","asOf":"2025-12-31","stakes":null,"districts":13,"familySearchCenters":44,"id":"alabama","kind":"state","country":"United States","firstMissionaries":{"year":1843,"said":"The 1843 experience of missionary John Brown in Alabama is typical of early missionaries for The Church of Jesus Christ of Latter-day Saints."},"began":null,"lat":33.258882,"lng":-86.829534},{"name":"Alaska","members":33574,"congregations":82,"wards":59,"branches":23,"missions":1,"temples":1,"capital":"Juneau","languages":"","continent":"North America","summary":["The Church began to be established in Alaska in 1927, with the first stake in the state organized in 1961. The Anchorage Alaska Temple was dedicated in 1999."],"history":["In 1898, Dr. Edward G. Cannon, a 79-year-old Latter-day Saint convert, moved to Nome, Alaska, seeking his fortune in the gold rush. For several years, Cannon traveled to many of the small towns throughout the Seward Peninsula in his “tabernacle,” a mobile meetinghouse where he taught locals the Church’s message. On June 25, 1902, Kedzie N. Winnie became the first known convert to join the Church in Alaska when Cannon baptized him in the Bering Sea. Together, Cannon and Winnie preached the gospel, organized a school to teach English to the local Indigenous peoples, and continued to hold regular worship services.","After Cannon’s death in 1910, Winnie continued preaching and distributing literature until 1913, when he moved to Utah. Afterwards, no official effort was made to establish the Church in the territory until 1927, when missionaries began preaching in many Alaskan towns and regions, including Juneau, Anchorage, Fairbanks, and the Matanuska-Susitna Valley. In July 1938, a branch was organized in Fairbanks in the home of Erastus Peterson, and a Sunday School was organized in Anchorage under the leadership of Otto Vaughn. In 1961, when the Anchorage Alaska Stake was organized, there were 3,050 members of the Church organized into three congregations in Alaska.","Church growth continued at a similar pace to Alaska’s overall population growth in the late 1960s. Spurred by rebuilding efforts following the 1964 Great Friday Earthquake, the discovery of oil in 1968, and the availability of land for homesteading, Latter-day Saints from the “lower 48” migrated to Alaska in large numbers.","Alaskan Saints have found unique ways to adapt their worship to the extremes of distance and weather. Several congregations have utilized teleconferencing for regular meetings for decades. Additionally, in the 1980s, congregations began to build meetinghouses specially designed for the Arctic weather.","The Anchorage Alaska Temple was dedicated in 1999, and today it serves members from across the state."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/alaska?lang=eng","asOf":"2025-12-31","stakes":null,"districts":13,"familySearchCenters":15,"id":"alaska","kind":"state","country":"United States","firstMissionaries":{"year":1910,"said":"After Cannon’s death in 1910, Winnie continued preaching and distributing literature until 1913, when he moved to Utah."},"began":null,"lat":64.445961,"lng":-149.680909},{"name":"Arizona","members":442094,"congregations":892,"wards":806,"branches":86,"missions":6,"stakes":null,"districts":3,"familySearchCenters":74,"temples":6,"history":["Beginning in the 1850s, Latter-day Saints occasionally traveled from the Utah Territory to preach the restored gospel and to explore the possibility of permanent settlements in Arizona. Beginning in 1854, Jacob Hamblin, called to preside over missionary efforts to the Indigenous peoples in the area, made frequent trips to Arizona. In 1876, Latter-day Saint settlers began building forts and establishing a series of communities along the Little Colorado River Valley in northeastern Arizona. Additional Latter-day Saint communities were soon established near St. Johns and in the Gila River, Salt River, and San Pedro valleys. In 1877, Daniel Webster Jones and Henry Clay Rogers established Fort Utah in the Salt River Valley. Over the next two years, with the help of wagon companies arriving from Utah and Idaho, Fort Utah grew into a well-established farming community. Eventually renamed Mesa, this settlement became the center of the first stake in Arizona, the Maricopa Stake. The Mesa Arizona Temple, the first in Arizona, was dedicated on October 23, 1927. There are now five temples in Arizona.","The Saints of Arizona have made significant contributions both to the Church and to their local communities throughout their history. In 1973, Spencer W. Kimball, a native of Thatcher, Arizona, became the Church’s 12th President. In recent years, Latter-day Saints have joined a coalition of more than 40 churches to help migrant refugees and asylum seekers and assisted in providing clean water to the Navajo Nation. With support from Saints in Arizona, Latter-day Saint Charities has made significant donations to charitable organizations throughout the state and nation."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/arizona","asOf":"","id":"arizona","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1854,"said":"Beginning in 1854, Jacob Hamblin, called to preside over missionary efforts to the Indigenous peoples in the area, made frequent trips to Arizona."},"began":null,"lat":34.395342,"lng":-111.763275},{"name":"Arkansas","members":38035,"congregations":79,"wards":55,"branches":24,"missions":2,"temples":1,"capital":"Little Rock","languages":"","continent":"North America","summary":["Missionaries first began preaching in Arkansas in 1835, and although many of the early Saints moved to Utah in the 19th century, the Church in the state has grown to include several dedicated members and a temple in Bentonville."],"history":["The first meeting of The Church of Jesus Christ of Latter-day Saints in Arkansas occurred in 1835 under the direction of missionaries Wilford Woodruff and Henry Brown. Missionaries continued to preach in Arkansas after the main body of Church members moved to Utah Territory in the late 1840s. In 1857, Parley P. Pratt, a member of the Church's Quorum of the Twelve Apostles, was murdered near Van Buren, Arkansas.","During the American Civil War and in its immediate aftermath, the Church’s presence in Arkansas was severely limited. Then, in 1875, missionaries baptized nearly 90 people in the Des Arc area — “many of the best citizens of the region,” it was reported. In 1877, the Des Arc congregations moved approximately 27 families and 125 people to Utah by wagon. In 1969 the Church formed its first stake in Arkansas, centered in Little Rock. Elder David A. Bednar of the Church’s Quorum of the Twelve Apostles was a prominent member of the Church in Arkansas during the 1980s and 1990s. Bednar was on the faculty of the University of Arkansas and served as a stake president.","There are currently more than 30,000 Church members living in Arkansas organized into seven stakes. In October 2019, the Church announced its plans to construct a temple in Bentonville."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/arkansas?lang=eng","asOf":"2025-12-31","stakes":null,"districts":13,"familySearchCenters":25,"id":"arkansas","kind":"state","country":"United States","firstMissionaries":{"year":1835,"said":"Missionaries first began preaching in Arkansas in 1835, and although many of the early Saints moved to Utah in the 19th century, the Church in the state has grown to include several dedicated members and a temple in Bentonville."},"began":null,"lat":35.204888,"lng":-92.447911},{"name":"California","members":725648,"congregations":1085,"wards":946,"branches":139,"missions":16,"temples":8,"capital":"Sacramento","languages":"","continent":"North America","summary":["Since first settling in 1846 in what is today known as San Francisco, Latter-day Saints in California now make up a large and diverse part of the Church."],"history":["Latter-day Saint immigrants first arrived in Yerba Buena (now San Francisco) on a ship called the Brooklyn in 1846. They settled in an agricultural community called New Hope, the first farm in the San Joaquin Valley. In January 1847, the Mormon Battalion, a group of Latter-day Saints who had volunteered for U.S. military service in the Mexican-American War, arrived in San Diego. Several Battalion members eventually traveled north to join other Latter-day Saints around San Francisco, and later that year, Latter-day Saints erected San Francisco’s first public schoolhouse in what is now Portsmouth Square.","Around this time a group of Latter-day Saints were employed at the sawmill of Captain John A. Sutter. The crew’s cook, a Latter-day Saint named Elizabeth Jane “Jennie” Wimmer, had lived among the gold mines of Georgia. When the men complained that the water in their dinner glasses often had a heavy sediment in it, she suggested, based on her experience from the South, that the sediment could be gold. No one believed her. However, eventually, on January 24, 1848, the crew at Sutter’s Mill found metallic flakes in water flowing out of the mill, setting off the Gold Rush.","In 1851, Latter-day Saints purchased a sizeable portion of cattle ranch land and established the settlement of San Bernardino. At its peak as a majority Latter-day Saint community in 1856, San Bernadino contained more than 2,500 Church members. Latter-day Saints continued to settle in other areas of California, and the first temple in California was built in Los Angeles in 1956. Today, the state is home to nine temples.","Californian Latter-day Saints are a diverse group, with hundreds of congregations conducting worship services and activities in languages other than English, including Spanish, Samoan, Tongan, Fijian, Chinese, Hmong, Cambodian, Vietnamese, and Tagalog. Many of these Latter-day Saints have cooperated to prepare for emergencies and provide relief for communities after earthquakes, fires, and floods. California natives David A. Bednar and Gerrit W. Gong are members of the Church’s Quorum of the Twelve Apostles."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/california?lang=eng","asOf":"2025-12-31","stakes":null,"districts":13,"familySearchCenters":228,"id":"california","kind":"state","country":"United States","firstMissionaries":null,"began":{"year":1846,"said":"Since first settling in 1846 in what is today known as San Francisco, Latter-day Saints in California now make up a large and diverse part of the Church."},"lat":36.701463,"lng":-118.755997},{"name":"Colorado","members":148945,"congregations":315,"wards":279,"branches":36,"missions":4,"temples":3,"capital":"Denver","languages":"","continent":"North America","summary":["The Church was first established in the land later known as Colorado in 1846 by 43 members in a wagon train. Today, the state has a considerable population of Latter-day Saints."],"history":["In August 1846, a wagon train of 43 members of The Church of Jesus Christ of Latter-day Saints from Mississippi created a temporary camp near present-day Pueblo, Colorado. The group planned to join Latter-day Saints then fleeing Nauvoo, Illinois, and to build a new gathering place with them in the Great Basin. That winter, several groups of converts from the Southern United States and others from the Mormon Battalion joined them. While some of these Saints eventually settled in Utah, many moved to the San Luis Valley where they established Latter-day Saint settlements in Pueblo, Manassa, Ephraim, and Richfield. A steady stream of converts, primarily from the Southern United States, soon gathered, and the Conejos Stake, the first in Colorado, was organized in 1883. A mission was established with headquarters in Denver in 1896, and additional Latter-day Saint communities were established along the Mancos River near Fort Lewis.","By 1930, congregations had been organized in Fort Collins, Englewood, and Pueblo. The Church dedicated its first temple in Colorado in Denver in 1986, and in 2009 the Mormon Tabernacle Choir (now known as the Tabernacle Choir at Temple Square) concluded a 13-city tour with a concert at the famed Red Rocks Amphitheater. Governor Bill Ritter served as the guest conductor of the choir and orchestra in an encore number.","Church members in Colorado frequently partner with civic and community leaders in humanitarian efforts in the state."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/colorado?lang=eng","asOf":"2025-12-31","stakes":null,"districts":13,"familySearchCenters":64,"id":"colorado","kind":"state","country":"United States","firstMissionaries":null,"began":{"year":1846,"said":"The Church was first established in the land later known as Colorado in 1846 by 43 members in a wagon train."},"lat":38.725178,"lng":-105.607716},{"name":"Connecticut","members":16442,"congregations":31,"wards":25,"branches":6,"missions":null,"temples":1,"capital":"Hartford","languages":"","continent":"North America","summary":["Most early members of the Church in Connecticut moved westward after 1844, but local branches began to be established in the early 20th century. In the 21st century, the state has a large body of members and a temple in Hartford."],"history":["In 1832, a few citizens of Connecticut joined The Church of Jesus Christ of Latter-day Saints in Connecticut. The next year, Wilford Woodruff, who later became a well-known missionary and Church President, joined the Church. In 1838, Woodruff returned to his hometown of Farmington and shared his faith with his family members. Afterward, Woodruff’s father, stepmother, and sister, as well as three others, were baptized and formed part of a small congregation in Farmington. In the years following the death of Church founder and President Joseph Smith in 1844, many Latter-day Saints on the East Coast migrated westward to join with the body of Church members traveling to the Great Basin. But near the end of the 19th century, Latter-day Saint missionaries once again traveled to the Eastern United States to establish congregations.","Church membership in Connecticut in 1930 consisted of 198 Saints. Connecticut’s first meetinghouse was completed in Hartford in 1952. Other congregations began to form, such as a branch in Ashford, which was established in 1977 and which dedicated a meetinghouse in 1982. In 2016, the Hartford Connecticut Temple, located in Farmington, was dedicated. Several Latter-day Saints on the faculty of Yale University have helped to build the Beinecke Library’s collection of Latter-day Saint historical documents, which is one of the largest outside of Utah.","Church members in Connecticut have regularly engaged in service within their communities in a variety of ways. For instance, in 1982, the Ashford Branch planted 100 blueberry bushes to serve as a resource for the hungry. More recently, Latter-day Saints can be seen participating in activities to improve schools, parks, and other community resources."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/connecticut?lang=eng","asOf":"2025-12-31","stakes":null,"districts":13,"familySearchCenters":10,"id":"connecticut","kind":"state","country":"United States","firstMissionaries":null,"began":{"year":1832,"said":"In 1832, a few citizens of Connecticut joined The Church of Jesus Christ of Latter-day Saints in Connecticut."},"lat":41.65002,"lng":-72.734216},{"name":"Delaware","members":6018,"congregations":10,"wards":9,"branches":1,"missions":null,"temples":null,"capital":"Dover","languages":"","continent":"North America","summary":["After local Church converts in Delaware emigrated westward in the 1840s, the Church was again established in the state in 1941. Members in Delaware thrive and serve together to this day."],"history":["Missionaries for The Church of Jesus Christ of Latter-day Saints arrived in the Delaware Valley in 1837. Joseph Smith, the Church’s founder, traveled through the Wilmington area in 1839. Local converts established small congregations in Wilmington, Centerville and Christiana. In the 1840s, many church members left Delaware to gather with the main body of Latter-day Saints in Nauvoo, Illinois. After the death of Joseph Smith in 1844, many remaining Latter-day Saints joined the mass exodus to the west. Church activity in Delaware ceased for around 100 years.","In 1941, a branch was organized, and in 1945 missionary work recommenced. In 1974, the Wilmington Stake was formed. Latter-day Saints in Delaware formed a tight-knit community with activities such as basketball tournaments and dances for young women and young men, scouting, and outdoor camps. Today, church members in Delaware regularly engage in projects to serve the community, such as the 2013 “Saturday in the Park” park cleanup events held in Delaware, Pennsylvania, Maryland, New York, and Ohio. Currently there are over 5,500 Latter-day Saints in Delaware in 12 congregations."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/delaware?lang=eng","asOf":"2025-12-31","stakes":null,"districts":13,"familySearchCenters":3,"id":"delaware","kind":"state","country":"United States","firstMissionaries":{"year":1837,"said":"Missionaries for The Church of Jesus Christ of Latter-day Saints arrived in the Delaware Valley in 1837."},"began":null,"lat":38.692045,"lng":-75.401331},{"name":"District of Columbia","members":3648,"congregations":4,"wards":12821,"branches":1820,"missions":120,"stakes":null,"districts":13,"familySearchCenters":1,"temples":101,"history":["In 1839, Joseph Smith, President of The Church of Jesus Christ of Latter-day Saints, visited the nation’s capital with Elias Higbee to seek redress of grievances suffered by Church members in Missouri. In response, United States President Martin Van Buren reportedly said, “Your cause is just, but I can do nothing for you.”","Early Church members paid occasional visits to Washington, D.C., as they sought statehood for their newly established communities in the Great Basin. Church leader Reed Smoot was elected to the United States Senate in 1903 and seated in 1907 after a series of hearings that brought publicity to the Church.","Around the turn of the 20th century, the area’s Latter-day Saint missionary work and congregations were revived. Utah had become a state in 1896, and in Washington, D.C., Church members often met for worship in the homes of Utah members of Congress. Growing congregations built meetinghouses such as the Washington Chapel, dedicated in 1933. In 1940, the first stake in Maryland was established around Washington, D.C.","In 1933, a large granite chapel was completed in the area. Future Church president Ezra Taft Benson worked in Washington, D.C., as secretary of agriculture in the Eisenhower administration from 1953 to 1961. In 1974, a temple was completed in Kensington, Maryland. Ambassadors and diplomats visit the temple's annual lighting ceremonies during the Christmas holiday.","President Gordon B. Hinckley, along with 26 other religious leaders from across the nation, visited the Capitol after the tragic events of September 11, 2001, and met with U.S. President George W. Bush."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/district-of-columbia","asOf":"","id":"district-of-columbia","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1839,"said":"In 1839, Joseph Smith, President of The Church of Jesus Christ of Latter-day Saints, visited the nation’s capital with Elias Higbee to seek redress of grievances suffered by Church members in Missouri."},"lat":38.895098,"lng":-77.036385},{"name":"Florida","members":178456,"congregations":287,"wards":227,"branches":60,"missions":5,"stakes":null,"districts":13,"familySearchCenters":84,"temples":3,"history":["Possibly the first missionary for The Church of Jesus Christ of Latter-day Saints in Florida was Phineas Young, who served a two-month mission in 1845. The first missionaries were not well-received. From 1869 to 1929 law officers met each train arriving in Tallahassee and prevented Latter-day Saint elders from getting off. As late as 1895, history notes that two elders were arrested and given the choice to leave or pay a $200 fine. In 1898, one Church congregational leader was murdered. In spite of such persecution, missionaries continued to preach in Florida. The state's first official Church congregation was created in Jefferson County in 1897. By 1904 there were 1,230 Church members in Florida.","Church growth in Florida was slow until Latter-day Saints from the West moved to Florida, drawn by a strong commerce and the aerospace industry."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/florida","asOf":"","id":"florida","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1845,"said":"Possibly the first missionary for The Church of Jesus Christ of Latter-day Saints in Florida was Phineas Young, who served a two-month mission in 1845."},"began":null,"lat":27.756767,"lng":-81.463983},{"name":"Georgia","members":92581,"congregations":163,"wards":135,"branches":28,"missions":2,"stakes":null,"districts":13,"familySearchCenters":44,"temples":1,"history":["Missionaries for The Church of Jesus Christ of Latter-day Saints arrived in Georgia in 1843 to preach and to campaign for Church President Joseph Smith's United States presidential bid. After Joseph Smith was martyred one year later, missionary efforts slowed. Activity resumed in the late 1870s when the Southern States Mission was headquartered in Rome, Georgia. One early convert to the Church donated land and built a chapel at Mormon Springs in Haralson County.","Missionaries left the state for a decade following the murder of one missionary in July 1879. By 1908, Church membership in Georgia was approximately 6,800. In 1930, membership was 4,311. The first temple to be built in the Southern states was completed in 1983 in Atlanta, Georgia.","Atlanta Latter-day Saints gave disaster relief to the community after the 1992 Hurricane Andrew in Albany and the flooding in 1994, when some 6,000 Church volunteers assisted homeowners."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/georgia","asOf":"","id":"georgia","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1843,"said":"Missionaries for The Church of Jesus Christ of Latter-day Saints arrived in Georgia in 1843 to preach and to campaign for Church President Joseph Smith's United States presidential bid."},"began":null,"lat":32.329381,"lng":-83.113737},{"name":"Hawaii","members":75827,"congregations":146,"wards":131,"branches":15,"missions":2,"temples":2,"capital":"Honolulu","languages":"","continent":"North America","summary":["Latter-day Saint missionaries first arrived in Hawai‘i in 1850. When the Book of Mormon was translated into Hawaiian in 1855, it was the work’s first non-European language translation. By the 1870s there were more than 4,000 Hawaiian Latter-day Saints, and in 1919 the first Latter-day Saint temple outside of North America was dedicated in Lā‘ie."],"history":["In 1850, when the first Latter-day Saint missionaries reached Hawai‘i, the islands were still an independent kingdom with a mostly native Hawaiian population. George Q. Cannon, one of the early missionaries to the islands, was particularly eager to learn the Hawaiian language. In the early 1850s he and an early Hawaiian convert, Jonathan Nāpela, worked together to translate the Book of Mormon into Hawaiian, which was the first time the book was translated into a non-European language.","Many Hawaiians embraced the gospel. By the 1870s, more than 4,000 Hawaiians were Latter-day Saints. Because the death of many Hawaiians due to disease had led to laws restricting emigration, instead of gathering to Utah the Hawaiian Saints established gathering places on the islands—first in Lāna‘i, then in Lā‘ie, where the first temple outside North America was dedicated in 1919. The first stake outside North America was organized on O‘ahu in 1935.","As Hawai‘i’s population became more diverse, so did general Church membership. In the early 20th century, for example, a Japanese mission was established in Hawai‘i, and work among Japanese Hawaiians flourished. In the 1950s the Church established a college—now Brigham Young University–Hawaii—in Lā‘ie with a mission to bring together students from around the world. A second temple, in Kona, was dedicated in 2000. By 2018 there were nearly 75,000 Latter-day Saints in Hawai‘i, organized into 16 stakes."],"source":"https://www.churchofjesuschrist.org/learn/facts-statistics/hawaii?lang=eng","asOf":"2025-12-31","id":"hawaii","kind":"state","country":"United States","firstMissionaries":{"year":1850,"said":"Latter-day Saint missionaries first arrived in Hawai‘i in 1850."},"began":null,"lat":19.593802,"lng":-155.42837},{"name":"Idaho","members":482905,"congregations":1323,"wards":1275,"branches":48,"missions":3,"stakes":null,"districts":13,"familySearchCenters":70,"temples":6,"history":["In 1855, Church President Brigham Young asked 26 early members of The Church of Jesus Christ of Latter-day Saints to settle among the Native Americans on the Salmon River. They established Fort Lemhi in June 1855, and left in 1858 after problems with the natives. Latter-day Saint settlers came to the Franklin area in 1860. They dug canals in the winter snows to be ready for summer irrigation. Franklin is Idaho's oldest permanent settlement. Other members colonized in Bear Lake Valley and in south central Idaho. Construction of the Utah Northern Railroad line brought settlement in the upper Snake River Valley in 1879. Church members taught agriculture, preached the gospel, and shared supplies with the Native Americans. A prominent chief, Shoshone Chief Washakie, was baptized during the early colonization efforts.","When Idaho was given statehood in 1890, Latter-day Saints comprised about one-fifth of the state's population. A few Church Presidents have been natives of Idaho: Presidents Harold B. Lee, Ezra Taft Benson, and Howard W. Hunter.","Ricks Academy, founded in 1888, later became a junior college that was renamed Ricks College. In 2001 the school became a four-year university and was renamed Brigham Young University-Idaho."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/idaho","asOf":"","id":"idaho","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1855,"said":"In 1855, Church President Brigham Young asked 26 early members of The Church of Jesus Christ of Latter-day Saints to settle among the Native Americans on the Salmon River."},"lat":43.644764,"lng":-114.015407},{"name":"Illinois","members":58832,"congregations":121,"wards":90,"branches":31,"missions":1,"stakes":null,"districts":13,"familySearchCenters":42,"temples":2,"history":["Thousands of early members of The Church of Jesus Christ of Latter-day Saints fled from Missouri to western Illinois in 1839 to escape persecution, including a literal extermination order given by Missouri governor Lilburn W. Boggs. The Latter-day Saints drained swamplands on the eastern banks of the Mississippi and established the thriving community of Nauvoo. The city, whose name means \"beautiful place,\" grew to rival Chicago in size and became a hub of Church activity and commerce in Illinois.","Unfortunately, the peace which Latter-day Saints had initially enjoyed in Illinois lessened with time as the number of Church members grew. Church founder Joseph Smith was martyred by a mob in the neighboring city of Carthage in 1844. By 1846, the Latter-day Saints were compelled to abandon Nauvoo for their own safety, thus launching one of the largest forced migrations in American history and the birth of the Mormon Trail. Over the next two decades, approximately 70,000 Latter-day Saints would move through Illinois on their way to the Valley of the Great Salt Lake, 1300 miles to the west. With the arrival of missionaries from Utah territory in 1870, the Church once again began to establish a presence in Illinois.","In July 1889, Chicago became the mission headquarters for all northern states. In 1962, the Church began to restore Church historical sites in Nauvoo. Since that time, some 1,000 acres have been repurchased. Church members now present Nauvoo's annual pageant entitled \"City of Joseph\" in August. Nearly 130 years after the first temple in Illinois was destroyed, another temple was constructed in Chicago. The six-spired edifice was completed in 1985.","In 2002 the rebuilt Nauvoo Temple was dedicated by President Gordon B. Hinckley. In 2004, an Illinois delegation led by Lt. Gov. Pat Quinn expressed \"official regret\" for the 1844 murder of Joseph Smith Jr. and the violence that forced the Latter-day Saints from the state."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/illinois","asOf":"","id":"illinois","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1870,"said":"With the arrival of missionaries from Utah territory in 1870, the Church once again began to establish a presence in Illinois."},"began":null,"lat":40.079661,"lng":-89.433729},{"name":"Indiana","members":48878,"congregations":102,"wards":80,"branches":22,"missions":1,"stakes":null,"districts":13,"familySearchCenters":40,"temples":1,"history":["In 1831, missionaries for The Church of Jesus Christ of Latter-day Saints preached in Madison, Unionville and Vienna, Indiana. They also organized congregations. Church President Joseph Smith visited Greenville for one month in 1832.","Congregations in Ohio and Missouri were much larger than those in Indiana, but in time, congregations sprouted up along the travel routes to those two states. By 1843, there were branches of the Church in 30 Indiana counties. After the death of Joseph Smith in 1844, many Indiana members joined a mass exodus to the Great Basin.","Around the turn of the 20th century, a small number of Indiana Latter-day Saints still met in homes. In 1913, Church members in Indianapolis rented a hall. In 1927, members built a meetinghouse in Indianapolis, which was dedicated by Church President Heber J. Grant.","Following World War II, many Latter-day Saint service members, funded by the GI Bill, moved to Indiana to attend the state's many colleges and universities. The Indianapolis stake was created in 1959. The Indianapolis Indiana Temple was dedicated in 2015.","Latter-day Saints are engaged citizens and regularly gather to serve their communities. After catastrophic floods in southern Indiana in 2008, Latter-day Saint volunteers mobilized to distribute essential supplies and clear debris. After tornadoes in 2012, Church members helped with cleanup efforts in Bloomington, New Albany, Perkin, Borden and Henryville. Currently, there are over 45,000 Church members in over 100 congregations across the state."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/indiana","asOf":"","id":"indiana","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1831,"said":"In 1831, missionaries for The Church of Jesus Christ of Latter-day Saints preached in Madison, Unionville and Vienna, Indiana."},"began":null,"lat":40.327013,"lng":-86.174693},{"name":"Iowa","members":29981,"congregations":69,"wards":44,"branches":25,"missions":1,"stakes":null,"districts":13,"familySearchCenters":30,"temples":101,"history":["After early members of The Church of Jesus Christ of Latter-day Saints left Nauvoo, Illinois, to escape persecution in 1846, they embarked on likely the most difficult part of the journey westward: it took 131 days for the first pioneer company to cross the 300 miles of Iowa. Difficult terrain, lack of food, disorganized camps, severe winter weather, and sickness all lengthened the journey. However, these early Church members found merriment in occasional music and dancing. The Nauvoo brass band provided entertainment and also earned money by playing concerts for the settlers in Iowa. Church President Brigham Young said the early settlers \"were patient, and endured all their privations without murmuring.\"","Nearly 200 Latter-day Saint pioneers established a small community named Garden Grove where they planted crops and built cabins for the pioneer companies who would follow them. Other communities were built at Mount Pisgah and Council Bluffs. When the United States declared war with Mexico in the spring of 1846, President Polk authorized the recruiting of five hundred Latter-day Saint volunteers. These volunteers constituted the Mormon Battalion, coming from the pioneer companies in Mount Pisgah, Garden Grove, and Council Bluffs. The Mormon Battalion accomplished the longest infantry march in the history of the United States. In Council Bluffs (Kanesville), Brigham Young became the official President of the Church in December 1847. He sent an epistle for members to gather in the Great Basin of the Rocky Mountains. From 1856-57, pioneers used handcarts to cross Iowa. Two to three hundred of these 2,500 handcart pioneers died on the trail. During the summer of 1996, communities in Iowa celebrated the sesquicentennial of the Mormon Pioneer trek west by reenacting the event with their own wagon trains."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/iowa","asOf":"","id":"iowa","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1846,"said":"After early members of The Church of Jesus Christ of Latter-day Saints left Nauvoo, Illinois, to escape persecution in 1846, they embarked on likely the most difficult part of the journey westward: it took 131 days for the first pioneer company to cross the 300 miles of Iowa."},"lat":41.921673,"lng":-93.31227},{"name":"Kansas","members":39838,"congregations":75,"wards":60,"branches":15,"missions":1,"stakes":null,"districts":13,"familySearchCenters":29,"temples":101,"history":["Members of the Shawnee and Delaware tribes in the Kansas area welcomed missionaries from the Church of Jesus Christ of Latter-day Saints in 1831. Church members who volunteered in 1846 for U.S. military service in the Mormon Battalion were trained and equipped in Fort Leavenworth, Kansas. For Church members emigrating from Europe, the Atchison, Kansas, area became a layover site on the journey to the Salt Lake Valley. In 1855, at a camp called Mormon Grove, more than 100 acres of crops were cultivated for future immigrants later that year.","In 1882, missionaries arrived in Kansas and organized the Meridian Branch on the border between Dickinson and Salina counties. Missionaries left Kansas temporarily after mob threats but returned in 1887.","The first stake in Kansas was organized in June 1962, and today there are seven stakes with over 38,000 members. Church members regularly contribute to humanitarian and disaster relief efforts across the state."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/kansas","asOf":"","id":"kansas","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1831,"said":"Members of the Shawnee and Delaware tribes in the Kansas area welcomed missionaries from the Church of Jesus Christ of Latter-day Saints in 1831."},"began":null,"lat":38.27312,"lng":-98.582187},{"name":"Kentucky","members":39792,"congregations":83,"wards":51,"branches":32,"missions":1,"stakes":null,"districts":13,"familySearchCenters":28,"temples":1,"history":["Joseph Smith, the first President of The Church of Jesus Christ of Latter-day Saints, likely preached in Louisville, Kentucky, on his way to Missouri. He stayed in the city for three days and later revisited in 1832. An Indiana convert began the first congregation in Licking River. In 1835, two missionaries baptized 22 people. The first group of Kentucky Saints to join other Church members in the West left for Missouri in September 1836. In July 1843, Church leaders Brigham Young and Wilford Woodruff preached in Kentucky. Though persecution existed, some 1,170 members of the Church lived in the state in 1900.","Automobiles and road improvements caused Bradfordsville, Kentucky, to become a main gathering place for Church members. One traditional Church-sponsored activity in Bradfordsville was a July 4th fish fry with fiddle and banjo music and food for up to 200 people, including many who were not members of the Church."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/kentucky","asOf":"","id":"kentucky","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1835,"said":"In 1835, two missionaries baptized 22 people."},"began":null,"lat":37.572603,"lng":-85.155141},{"name":"Louisiana","members":29913,"congregations":52,"wards":32,"branches":20,"missions":1,"stakes":null,"districts":13,"familySearchCenters":15,"temples":1,"history":["In 1841, Joseph Smith, the first President of The Church of Jesus Christ of Latter-day Saints, received a letter from Church members in New Orleans who needed leadership. \"Send us Peter, or an Apostle to preach unto us Jesus,\" they wrote, and they enclosed $10 to help defray expenses. Smith sent Harrison Sagers. Although Sagers faced opposition from the community, those who called for him offered defense, including a group of courageous women who once encircled him as protection from mobs.","In November 1841, New Orleans became the main port of arrival for nearly 17,500 Latter-day Saints emigrating from Europe. They traveled up the Mississippi River to Nauvoo, Illinois; St. Louis, Missouri; or other river ports. After 1846, these port cities were the starting points for their long trek westward. 1","Twenty-four Church missionaries labored in Louisiana in 1898, and 110 individuals joined the Church that year. Local Church members continued to labor alongside missionaries in New Orleans for decades before organizing the state’s first official congregation in 1924. The first stake in Louisiana was established in New Orleans in 1955, and the Church continued to grow throughout the state. In 2000, the Church dedicated its first temple in the state, located in Baton Rouge. There are now seven stakes and approximately 30,000 church members in the state. As Louisiana has experienced devastation from hurricanes and flooding in recent years, the state's Latter-day Saints have routinely partnered with community leaders in clean-up efforts, and thousands of Church members from neighboring states have traveled to Louisiana to assist. 2"],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/louisiana","asOf":"","id":"louisiana","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1898,"said":"Twenty-four Church missionaries labored in Louisiana in 1898, and 110 individuals joined the Church that year."},"began":null,"lat":30.870388,"lng":-92.007126},{"name":"Maine","members":11275,"congregations":26,"wards":17,"branches":9,"missions":120,"stakes":null,"districts":13,"familySearchCenters":10,"temples":101,"history":["Arriving by canoe, missionaries for The Church of Jesus Christ of Latter-day Saints crossed the Piscataqua River to Maine in 1832. They traveled from town to town, preaching. In Saco, Timothy Smith was convinced by the missionaries’ message and accepted baptism on October 31, 1832. 1 A branch of the Church was established in Saco. Later that year, the pastor and thirty members of the Freewill Baptist Church in the vicinity of Lake Umbagog also became Latter-day Saints. In the mid-1830s, more individuals and families joined the Church in Bethel and Newry. In August 1837, Latter-day Saint missionaries Wilford Woodruff and Jonathan Hale arrived in the Fox Islands, currently known as Vinalhaven and North Haven. By that winter, the Church established branches on both islands, with about 100 members total. 2 After 1844, when most Church members joined a mass exodus to the west to escape persecution, Church activity slowed in Maine.","In 1904, missionary efforts and Church activities in Maine resumed. Local Latter-day Saints hosted worship services and activities in their homes. On May 15, 1921, around 60 Church members attended a conference held at Bangor. In 1957, meetinghouses were dedicated in Portland and Bangor. On June 23, 1968, the Maine Stake was organized. It was notable compared to other Latter-day Saint regional units in New England at the time because it was led by a stake president and two counselors who were all locals, as opposed to transplants from the intermountain West.","Currently, there are over 10,000 Church members living in Maine. They are engaged citizens who regularly partner with local civic organizations to serve in their communities.","[1] “Saco, Maine,” The Joseph Smith Papers, The Church Historian’s Press, accessed July 19, 2022, https://www.josephsmithpapers.org/place/saco-maine .","[2] “Fox Islands, Maine,” The Joseph Smith Papers, The Church Historian’s Press, accessed July 19, 2022, https://www.josephsmithpapers.org/place/fox-islands-maine ."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/maine","asOf":"","id":"maine","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1832,"said":"Arriving by canoe, missionaries for The Church of Jesus Christ of Latter-day Saints crossed the Piscataqua River to Maine in 1832."},"began":null,"lat":45.709097,"lng":-68.85902},{"name":"Maryland","members":44671,"congregations":84,"wards":65,"branches":19,"missions":2,"stakes":null,"districts":13,"familySearchCenters":14,"temples":1,"history":["In the 1830s and 1840s, a few Latter-day Saint families lived in the town of Leitersburg in western Maryland. In 1841, Latter-day Saint missionary John Murdock arrived in Baltimore, and in 1842, the Mormon Expositor , a Church paper in Baltimore, launched. In the first half of 1844, Latter-day Saint leaders representing Joseph Smith’s U.S. presidential campaign held their own nominating convention and attended the conventions of the Whig and Democratic parties in Baltimore. Following the martyrdom of Smith in June 1844, the majority of Latter-day Saints moved far to the west, and the Church’s presence in Maryland dwindled.","Around the turn of the 20th century, Latter-day Saint missionary work and congregations revived in the area. Utah became a state in 1896, and in Washington, D.C. Church members often met for worship in the homes of Utah members of Congress. In 1914, women of the Baltimore Branch Relief Society organized to collect and mend clothes and make quilts for the needy. Growing congregations built meetinghouses such as the Washington Chapel, dedicated in 1933, and the Baltimore Chapel, dedicated in 1935. 1 In 1940, the first stake in Maryland centered on Washington, D.C. 2 In 1963, the Church created a congregation in Annapolis. Between 1958 and 1984, Maryland’s Latter-day Saints contributed volunteer labor to run a dairy farm at Trappe, producing dairy products for the poor and needy. 3","The Washington D.C. Temple in Kensington was completed in 1974 and is a prominent landmark on the Capital Beltway. Maryland Church members have contributed many volunteer hours to soup kitchens, blood drives, schools, parks, hospice and other community resources. 4","[1] “Washington chapel [history],” The Church of Jesus Christ of Latter-day Saints, accessed July 20, 2022, https://catalog.churchofjesuschrist.org/assets/6b96efd5-2cc1-4c5a-b9a3-0d6b2f8d88eb/0/8 ; A History of the Baltimore Maryland Stake of the Church of Jesus Christ of Latter-day Saints, 1974-1999 (United States: Gateway Press, 2003), 8."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/maryland","asOf":"","id":"maryland","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1841,"said":"In 1841, Latter-day Saint missionary John Murdock arrived in Baltimore, and in 1842, the Mormon Expositor , a Church paper in Baltimore, launched."},"began":null,"lat":39.51624,"lng":-76.938207},{"name":"Massachusetts","members":29541,"congregations":56,"wards":42,"branches":14,"missions":1,"stakes":null,"districts":13,"familySearchCenters":18,"temples":1,"history":["The nightly preachings of George J. Adams brought an audience of some 1,200 in Charlestown, Massachusetts, in 1843. At that time, there were some 14 branches (small congregations) of The Church of Jesus Christ of Latter-day Saints in the Boston area. Eleven years prior, the first missionaries for the Church arrived in Boston to organize congregations. Church President Joseph Smith passed through Boston on his way to Washington, D.C., in 1839. After President Smith was martyred in 1844, several members in Massachusetts joined the mass exodus west, and missionary work in the state slowed.","In 1894, one year after the area was reopened to missionaries, Church membership was 96. A decade later, missionaries encountered hostilities toward the Church during the highly-publicized United States Senate hearings on Church leader and Senator-elect Reed Smoot, and police disallowed missionaries to hold open-air meetings. By 1930, membership was nearly 360, some of whom were recently-returned missionaries studying at Harvard University. Cambridge, Massachusetts, became the headquarters for the New England States Mission. A Church building was dedicated in the area in 1956.","The Church completed and dedicated the Boston Massachusetts Temple in 2000, marking the 100th operating temple in the Church."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/massachusetts","asOf":"","id":"massachusetts","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1843,"said":"The nightly preachings of George J. Adams brought an audience of some 1,200 in Charlestown, Massachusetts, in 1843."},"began":null,"lat":42.378877,"lng":-72.032366},{"name":"Michigan","members":47105,"congregations":100,"wards":61,"branches":39,"missions":2,"stakes":null,"districts":1,"familySearchCenters":43,"temples":1,"history":["Lucy Mack Smith, mother of Church President Joseph Smith, traveled to Michigan in 1831, just one year after the organization of The Church of Jesus Christ of Latter-day Saints. She visited her brother in Pontiac, preached, and warned one unfriendly pastor that one-third of his flock would soon be Latter-day Saints. When Joseph Smith sent men to Pontiac, they baptized 22 people from the pastor's congregation, including the deacon. The Church President visited Michigan in 1834. He was later murdered by mobs in Illinois in 1844, thus ending a period of Church advancement in the state. Several Church members began the trek westward with other Saints. One apostate, James J. Strang, claimed to be Joseph Smith's successor as Church President. Although he was denounced by leaders, he formed a group that settled on Beaver Island in Lake Michigan before disbanding.","In December 1928, the Church's first building in Detroit was completed. In 1939, missionaries— who had been recalled from foreign areas because of World War II— formed a chorus that performed public concerts."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/michigan","asOf":"","id":"michigan","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1939,"said":"In 1939, missionaries— who had been recalled from foreign areas because of World War II— formed a chorus that performed public concerts."},"began":null,"lat":43.621195,"lng":-84.682435},{"name":"Minnesota","members":34002,"congregations":77,"wards":56,"branches":21,"missions":1,"stakes":null,"districts":13,"familySearchCenters":29,"temples":1,"history":["In 1854, Latter-day Saint missionaries preached in Minnesota in places such as Spring Grove and Morristown. Some of the earliest Latter-day Saints to live permanently in Minnesota were Eli Houghton and Margaret McMean Houghton. The Houghtons left Nauvoo along with many other Latter-day Saints in 1846 but traveled north to Monticello, Minnesota, where their three sons were living. In 1875, when Latter-day Saint missionaries arrived in the area, the Houghton family became the nucleus of the first branch in Monticello. Later, Latter-day Saint branches were organized in Freeborn County and Mille Lac County.","In 1900, Sunday Schools were organized in Minneapolis and St. Paul. Converts also joined the Church in places such as Duluth, Brainerd, Aitkin, Rodgers, Rochester, Virginia, and Springvale. A Twin Cities branch of the Church was established in 1912. The first purpose-built Church meetinghouse was in Minneapolis, dedicated October 25–26, 1924.","Following World War II, many Latter-day Saints from Utah migrated to Minnesota for education or employment. One major draw for Latter-day Saint students was a core of Latter-day Saint professors as the University of Minnesota, including Andrew T. Rasmussen, a researcher in neuroanatomy since 1921, and Frank “Doc” Whiting, head of the theater department for thirty years. The University of Minnesota Medical School, which pioneered heart surgery after World War II, trained many prominent Latter-day Saint surgeons and doctors, including future Church President Russell M. Nelson. As a medical student, Nelson worked with Dr. Clarence Dennis to pioneer the artificial heart-lung machine.","In 1960, the Minnesota Stake was established. The St. Paul Minnesota Temple was dedicated in 2000.","Latter-day Saints are engaged citizens, regularly organizing to serve in their communities. For example, in April 2009 Latter-day Saint volunteers helped respond to the Red River flooding in Moorhead, and in November 2021 Latter-day Saint congregations donated 25,000 pounds of canned goods to the Food Group in New Hope."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/minnesota","asOf":"","id":"minnesota","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1854,"said":"In 1854, Latter-day Saint missionaries preached in Minnesota in places such as Spring Grove and Morristown."},"began":null,"lat":45.989659,"lng":-94.611329},{"name":"Mississippi","members":22000,"congregations":49,"wards":30,"branches":19,"missions":120,"stakes":null,"districts":13,"familySearchCenters":20,"temples":101,"history":["The first missionaries of The Church of Jesus Christ of Latter-day Saints to Mississippi arrived in 1839. They preached in Tishomingo County and baptized 13 people. However, early Church members faced staunch opposition from their neighbors, and in 1842 nearly 90 Church members left the state to settle in Nauvoo, Illinois. Though it was small, the Church continued to have a presence in Mississippi, and local members formed a congregation in Monroe County in 1843. In 1846 many of those Monroe County members determined to join the main body of the Latter-day Saints travelling westward under the leadership of Brigham Young. However, they advanced more quickly than Young and company and spent that winter in an area now part of Colorado before meeting the other Saints. Missionary efforts in the state ceased during and after the Civil War but resumed in the late 1870s.","The Church established the first two stakes in Mississippi in 1965 in Hattiesburg and Jackson. Today there are more than 20,000 Church members organized in four stakes. Church members in the state have partnered with civic leaders in responding to the aftermath of recent natural disasters. The Mississippi Saints have similarly welcomed opportunities to assist other community organizations, such as the NAACP."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/mississippi","asOf":"","id":"mississippi","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1839,"said":"The first missionaries of The Church of Jesus Christ of Latter-day Saints to Mississippi arrived in 1839."},"began":null,"lat":32.971528,"lng":-89.73485},{"name":"Missouri","members":84311,"congregations":181,"wards":153,"branches":28,"missions":2,"stakes":null,"districts":13,"familySearchCenters":51,"temples":2,"history":["In 1831, Joseph Smith, first President of The Church of Jesus Christ of Latter-day Saints, told Church members that Independence, Jackson County, Missouri, was to be the gathering spot for the Church. The influx of members to the county raised concern among area settlers, who ordered the 1,200 members to leave. Church leaders were unsuccessful in their attempts to seek protection from the courts. Mobs drove Church members out of the area. In 1834, Joseph Smith and 150-200 armed men, called Zion's Camp, arrived to protect the members. A storm prevented the confrontation and the camp was later disbanded.","Latter-day Saint refugees found refuge in Clay, Caldwell, and Daviess Counties. By 1838, Far West had become Church headquarters with homes, hotels, a printing house, and school. Violence erupted in Gallatin in August 1838, when members were prevented from voting. Mob raids began, and Elder David W. Patten, the next Apostle in line to be Church President, was killed. The exaggerated rumors about Church members ultimately led to the literal extermination order from Gov. Lilburn W. Boggs in 1838. Eighteen men and boys were killed at Haun's Mill by an unauthorized militia. On 31 October, Joseph Smith was arrested and the next day sentenced to death, but Brig. Gen. A.W. Doniphan refused to carry out the order. Between 12,000 - 15,000 Church members fled to western Illinois in 1839 and established the city of Nauvoo on the Mississippi River. Several others moved to the more tolerant St. Louis, where many more members eventually came from Nauvoo. In the late 1850s, many members left for Utah to gather with the Saints. In June 1976, Governor Christopher S. Bond signed an executive order rescinding the extermination order issued 138 years earlier by Governor Boggs."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/missouri","asOf":"","id":"missouri","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1831,"said":"In 1831, Joseph Smith, first President of The Church of Jesus Christ of Latter-day Saints, told Church members that Independence, Jackson County, Missouri, was to be the gathering spot for the Church."},"lat":38.760481,"lng":-92.561787},{"name":"Montana","members":52050,"congregations":140,"wards":97,"branches":43,"missions":2,"stakes":null,"districts":13,"familySearchCenters":50,"temples":2,"history":["Prior to the Montana gold rush of the 1860s, a few members of The Church of Jesus Christ of Latter-day Saints traded with Flathead Indians and settled in the area. Others were acquainted with Montana by following the Montana Trail from the Church's Fort Lemhi settlement on the Salmon River. The gold discovery, followed by the overland railway completion in 1869, attracted some Church members to Montana. In 1896, the Montana Mission was organized. In October 1897, Church leaders in Montana received the promise of religious freedom from Governor John E. Rickards. A meeting of 75 people was held in Anaconda, and a gathering of 300 met in Butte later that spring.","The Billings Montana Temple was dedicated in 1999."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/montana","asOf":"","id":"montana","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1869,"said":"The gold discovery, followed by the overland railway completion in 1869, attracted some Church members to Montana."},"lat":47.375267,"lng":-109.638757},{"name":"Nebraska","members":26199,"congregations":57,"wards":42,"branches":15,"missions":1,"stakes":null,"districts":13,"familySearchCenters":18,"temples":1,"history":["Beginning in 1846, thousands of early members of The Church of Jesus Christ of Latter-day Saints made camps in Native American country along the banks of the Missouri River in what is now Nebraska. The first Winter Quarters camps provided critical winter respite for pioneers who had been driven from their homes in Nauvoo, Illinois, and were on their way to the Great Basin. Still, several hundred died there from exposure, poor nutrition, and poor sanitation. Later camps, like the one in the hamlet of Wyoming, Nebraska, served as outfitting posts for the continuing migration of Latter-day Saints to the Salt Lake Valley. As the railroad extended westward, most of these settlements were abandoned or absorbed into other communities.","Several monuments and historic markers honor early Latter-day Saints’ migration through Nebraska. In 1997, the Church dedicated the Mormon Trail Center at Winter Quarters to educate the public about the contribution to westward expansion made by Latter-day Saint pioneers who traveled through Nebraska. In April 2001, the Church dedicated the Winter Quarters Nebraska Temple on ground adjacent to the Mormon Pioneer Cemetery.","The Church grew slowly in Nebraska with sporadic proselytizing and had only a few members there until 1896, when the first congregation was organized. In 1916, a Sunday School was established in Lincoln, but it was not until 1960 that a stake was created in Lincoln — the first in the Cornhusker State. There are currently stakes in Kearney and Lincoln and three in Omaha.","Church members regularly provide community aid and help in disaster cleanup efforts. Examples include cleaning up after a devastating storm in Blair, Nebraska , and helping refugee resettlement ."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/nebraska","asOf":"","id":"nebraska","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1846,"said":"Beginning in 1846, thousands of early members of The Church of Jesus Christ of Latter-day Saints made camps in Native American country along the banks of the Missouri River in what is now Nebraska."},"lat":41.737023,"lng":-99.587382},{"name":"Nevada","members":181842,"congregations":339,"wards":304,"branches":35,"missions":4,"stakes":null,"districts":13,"familySearchCenters":34,"temples":3,"history":["In 1851, Latter-day Saints from Utah established a trading post in western Nevada, just east of Lake Tahoe. This trading post became known as Mormon Station, and Nevada’s first non-Native-American settlement grew up around it. Elder Orson Hyde, an apostle, named the community Genoa.","In 1855, 30 Latter-day Saints from Utah traveled to the Meadows ( Las Vegas ) alongside the spring and creek flowing through the Las Vegas valley and built a fort there. This fort later became the site of a ranch, and after the arrival of the railroad in 1905, which sparked a development boom, the ranch and surrounding lands became downtown Las Vegas.","In 1864, a group of Latter-day Saints established a settlement in Panaca. By 1869, there were also Latter-day Saint settlements in the Muddy River area, including St. Joseph, Overton, West Point and Junction City. In 1883 a branch was organized at Overton, and in 1912 Overton became the headquarters of Nevada’s first permanent stake, the Moapa Stake.","In the late 1920s, many Latter-day Saints moved from Utah to Nevada in search of better economic conditions. The Las Vegas Stake was created in 1954. Church members also moved to northern Nevada, particularly Elko and Ely. Currently there are over 180,000 Latter-day Saints in Nevada. Some prominent Nevada Latter-day Saints include U.S. Sen. Harry Reid, who served from 1987 to 2017, and musician Brandon Flowers.","The Las Vegas Nevada Temple was dedicated in 1989. In 2000, the Reno Nevada Temple was dedicated. In 2021, a third temple was announced for Elko."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/nevada","asOf":"","id":"nevada","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1851,"said":"In 1851, Latter-day Saints from Utah established a trading post in western Nevada, just east of Lake Tahoe."},"lat":39.515882,"lng":-116.853722},{"name":"New Hampshire","members":8575,"congregations":18,"wards":14,"branches":4,"missions":1,"stakes":null,"districts":13,"familySearchCenters":6,"temples":101,"history":["In 1811, the family of Joseph Smith, Jr. moved to Lebanon (now West Lebanon) and rented a home there for two years. During this period in Lebanon, young Joseph, who was about 6 or 7 years old, suffered a severe bone infection in his leg. Five miles away was Dr. Nathan Smith, founder of Dartmouth Medical School, who was ahead of his time in terms of treating this particular ailment. Dr. Smith was able to save Joseph’s leg.","In 1832, Joseph Smith, now leader of a fledgling religious movement, received a revelation calling Orson Pratt and Lyman E. Johnson on missions to the eastern United States. Within that same year, they arrived in New Hampshire, staying for 26 days and initially baptizing 20 people. In the 1840s, several Latter-day Saint congregations were meeting together in New Hampshire. One missionary working in the state, Eli P. Maginn, wrote that he could not “fill from one to twenty of the calls for preaching; there is the greatest excitement in this country that I ever beheld.”","Missionary work in New Hampshire lessened after the 1844 murder of Joseph Smith and the subsequent mass movement west by Church members. Around the turn of the 20th century, Latter-day Saints once again began to establish congregations in New Hampshire. The first stake in New Hampshire was created in Manchester in 1970.","Notable local Latter-day Saints include Dick Swett, who grew up in New Hampshire. He represented the 2nd Congressional District in the U.S. House of Representatives from 1991 to 1995 and served as ambassador to Denmark from 1998 to 2001."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/new-hampshire","asOf":"","id":"new-hampshire","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1844,"said":"Missionary work in New Hampshire lessened after the 1844 murder of Joseph Smith and the subsequent mass movement west by Church members."},"began":null,"lat":43.484913,"lng":-71.655399},{"name":"New Jersey","members":36632,"congregations":61,"wards":42,"branches":19,"missions":1,"stakes":null,"districts":13,"familySearchCenters":20,"temples":101,"history":["Orson Pratt and Lyman E. Johnson, missionaries of The Church of Jesus Christ of Latter-day Saints, preached in New Jersey in 1832. In 1838, missionary Benjamin Winchester arrived in the Pine Barrens region and local congregations began to form. In 1840 a local Latter-day Saint, Alfred Wilson, informed church leaders that there were about 100 members in the village of Cream Ridge. That same year, Joseph Smith visited a number of the congregations in the state. By 1848, there were 21 congregations in New Jersey, most of them in Monmouth and Burlington counties.","The communities of Toms River and Hornerstown had a number of Latter-day Saints from prominent local families around this time. This group from Toms River included members who became influential Latter-day Saints. In the Ivins family, Anthony W. Ivins became a member of the Church’s Quorum of the Twelve Apostles in Nauvoo, and Rachel Ivins Grant was a local leader of the women’s Relief Society from 1868 to 1903 and the mother of Church President Heber J. Grant. In 1850, Toms River members had built a meetinghouse. In the 1850s, many converts to the Church in New Jersey joined the Latter-day Saints’ westward trek. Around the turn of the 20th century, Latter-day Saint congregations in New Jersey began growing again.","In 1960, the Morristown New Jersey Stake was created. The sesquicentennial of the Church in New Jersey was celebrated in 1988, with several local and state dignitaries participating. In 2011, around 850 Latter-day Saints worked to help communities in New Jersey clean up in the aftermath of Hurricane Irene. Currently the state is home to over 34,000 Church members."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/new-jersey","asOf":"","id":"new-jersey","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1832,"said":"Orson Pratt and Lyman E. Johnson, missionaries of The Church of Jesus Christ of Latter-day Saints, preached in New Jersey in 1832."},"began":null,"lat":40.075738,"lng":-74.404162},{"name":"New Mexico","members":68699,"congregations":137,"wards":104,"branches":33,"missions":2,"stakes":null,"districts":13,"familySearchCenters":31,"temples":2,"history":["In 1846, members of the Mormon Battalion, a force of men, women, and children who had volunteered to support the United States in the Mexican-American War, passed through Wagon Mound and Santa Fe on their way to California.","In 1876, over 100 Zuni in the Ramah area received missionaries from The Church of Jesus Christ of Latter-day Saints and joined the Church. Missionary work among Indigenous tribes became the basis for growing settlements of Latter-day Saints, including increasing numbers of white colonists in Ramah and Fruitland. However, Latter-day Saint settlement in the region led to displacement of Indigenous populations and introduced disease.","During the Mexican Revolution in 1912, many Church settlements in New Mexico absorbed refugees from the Latter-day Saint colonies in Mexico. Beginning in the 1930s, both Spanish-speaking and English-speaking Latter-day Saint congregations flourished in Albuquerque, Carlsbad, Española, Las Cruces, Las Vegas, Llano, Raton, Roswell, Silver City, Taos, and Valecitos.","In the 1930s, during the Great Depression, Latter-day Saint communities in Farmington developed projects to produce the necessities of life for those in need. The projects included construction of a storehouse, operation of a large farm, and the planting of a few acres of tomatoes, beans, corn, or wheat. In 1981 and 1984, the Church built large storehouses to house and distribute these welfare goods in Albuquerque and Farmington, respectively. Smaller, auxiliary storehouses were organized in Las Cruces and Roswell. The diverse congregations of Latter-day Saints in New Mexico have worked to serve the poor and needy in their communities.","On March 5, 2000, the first Latter-day Saint temple in New Mexico was dedicated in Albuquerque. In April 2021, another temple in Farmington was announced."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/new-mexico","asOf":"","id":"new-mexico","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1876,"said":"In 1876, over 100 Zuni in the Ramah area received missionaries from The Church of Jesus Christ of Latter-day Saints and joined the Church."},"began":null,"lat":34.580207,"lng":-105.996047},{"name":"New York","members":92133,"congregations":144,"wards":96,"branches":48,"missions":2,"stakes":null,"districts":1,"familySearchCenters":65,"temples":2,"history":["The earliest founding events of The Church of Jesus Christ of Latter-day Saints took place in the state of New York. In 1820, a 14-year-old boy named Joseph Smith Jr. experienced a vision of God the Father and Jesus Christ in a grove of trees near his family’s farm in Palmyra. In 1823, an angel directed Joseph to a hill in Manchester, where Joseph found a set of golden plates containing the Book of Mormon, a record of ancient peoples who had believed in Jesus Christ.Between April and June 1829, Joseph produced a translation of the Book of Mormon, which was first offered for sale in Egbert Grandin’s printing shop in Palmyra in March 1830.","On April 6, 1830, people who believed Joseph had been called by God to restore Christian truths gathered at the home of Mary and Peter Whitmer in Fayette, New York, to formally establish the “Church of Christ.” As the Church (officially named The Church of Jesus Christ of Latter-day Saints in 1838) grew, its center of gravity shifted westward. But New York still retained significance as the site of early Church history and as an international point of entry for an increasingly global Church membership.","On April 6, 2000, 170 years after the Church was organized, the Palmyra New York Temple was dedicated. The temple overlooks the Sacred Grove and other historic sites. The first temple in New York City, the Manhattan New York Temple, was dedicated on June 13, 2004.","Church members in New York are engaged members of their communities. In 2012, following Hurricane Sandy, church members formed teams of Helping Hands volunteers and helped clear away debris from homes and community structures damaged by flooding."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/new-york","asOf":"","id":"new-york","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1830,"said":"In 1823, an angel directed Joseph to a hill in Manchester, where Joseph found a set of golden plates containing the Book of Mormon, a record of ancient peoples who had believed in Jesus Christ.Between April and June 1829, Joseph produced a translation of the Book of Mormon, which was first offered for sale in Egbert Grandin’s printing shop in Palmyra in March 1830."},"lat":40.712728,"lng":-74.006015},{"name":"North Carolina","members":98483,"congregations":192,"wards":145,"branches":47,"missions":2,"stakes":null,"districts":13,"familySearchCenters":51,"temples":1,"history":["Some of the earliest meetings of The Church of Jesus Christ of Latter-day Saints in North Carolina “caused the greatest stirs imaginable,” recalled missionary Elder John Eldridge about his time in the state in 1844. “I never thought that one poor mortal could make such a stir.”","The first missionary to North Carolina, Jedediah M. Grant, had traveled to the state five years before Eldridge. By 1845, missionaries had organized seven congregations of more than 200 Church members. When Grant left the state, membership had increased to 350. Missionary work was interrupted in the late 1840s as many Church members traveled west to escape persecution, and it came to a halt in the state during the Civil War and in its immediate aftermath before resuming in the mid-1870s.","In November 1894, Church leaders encouraged members to stay in their state rather than migrating west to Utah. During the next five years, nearly 700 people were baptized, seven Church buildings constructed, 30 Sunday Schools organized, and 20 congregations established. Despite this growth, opposition to the Church did not fully subside. A newly completed meetinghouse on Harker’s Island was burned and missionaries were driven out by a mob in 1906. Harsh attitudes gradually moderated in the 20th century, and missionaries discovered more freedom to preach.","In 1948, the Church began a five-year construction project in North Carolina resulting in 16 new Church buildings. By 1973, North Carolina had nearly 16,400 members in 53 congregations with a growth rate of nearly 400 new members per year. In 1999, the Church dedicated a temple in Raleigh. Today, there are more than 95,000 Church members in North Carolina organized into 20 stakes. The Church and its members in the state are engaged in ongoing service to the communities in which they live, including efforts to provide food for those experiencing food insecurity ."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/north-carolina","asOf":"","id":"north-carolina","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1844,"said":"Some of the earliest meetings of The Church of Jesus Christ of Latter-day Saints in North Carolina “caused the greatest stirs imaginable,” recalled missionary Elder John Eldridge about his time in the state in 1844."},"began":null,"lat":35.672964,"lng":-79.039292},{"name":"North Dakota","members":11807,"congregations":27,"wards":20,"branches":7,"missions":1,"stakes":null,"districts":13,"familySearchCenters":7,"temples":1,"history":["In 1883, four missionaries for The Church of Jesus Christ of Latter-day Saints went from house to house across the farmlands of the Dakotas. Missionaries were warned that Fargo's mayor would try to inhibit them. However, local newspapers gave positive reports of the missionaries. In 1899, the missionaries transferred to South Dakota \"as very little good was being done in North Dakota.\" A Native American chief began corresponding with the missionaries, and when missionaries came to Shell Village in the summer of 1914, they taught 108 natives and baptized seven converts.","Church buildings were constructed in Sully Lake (1919) and Grand Forks (1930). With the organization of the Fargo North Dakota Stake in August 1977, every state in the union had a stake (diocese) within its boundaries."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/north-dakota","asOf":"","id":"north-dakota","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1883,"said":"In 1883, four missionaries for The Church of Jesus Christ of Latter-day Saints went from house to house across the farmlands of the Dakotas."},"began":null,"lat":47.620146,"lng":-100.540737},{"name":"Ohio","members":65991,"congregations":132,"wards":99,"branches":33,"missions":2,"stakes":null,"districts":13,"familySearchCenters":46,"temples":1,"history":["In January 1831, people of the Delaware Nation graciously received traveling missionaries of the fledgling Church of Christ (established in 1830 and later renamed The Church of Jesus Christ of Latter-day Saints) and listened to their message. Around the same time, Ohio minister Sidney Rigdon and much of his congregation in Mentor, Ohio, encountered the same missionaries and joined the Church. Nearby Kirtland became Church headquarters from 1831 to 1838. In its heyday, the Latter-day Saint community in northern Ohio included over 2,000 members.","In 1831, Church President Joseph Smith, his wife Emma Smith, and their children moved to Kirtland. Church members sacrificed their time and resources to build a house of worship, the Kirtland Temple. In 1836, after three years of labor, the temple was complete. Two years later, tensions in the community compelled church members to leave Kirtland and gather with another body of Latter-day Saints in Missouri.","Beginning in the late 1970s, Latter-day Saints in northern Ohio reorganized congregations. The Church has since restored historic sites in Kirtland and Hiram, including a store, a sawmill, an ashery, and Joseph and Emma Smith’s home. The Kirtland Temple is a national historical landmark under the management of the Community of Christ, another denomination historically rooted in the teachings of Joseph Smith.","In 1999, Latter-day Saints hosted members of the community for an open house of the Columbus Ohio Temple prior to its dedication. In 2010, a team of Church archivists worked with the Geauga County Archives Department to digitally preserve historical documents and to share with the Archives Department copies of other documents needed to fill gaps in its collection. Church members work to be engaged members of their local communities, contributing to civic life and serving those in need."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/ohio","asOf":"","id":"ohio","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1830,"said":"In January 1831, people of the Delaware Nation graciously received traveling missionaries of the fledgling Church of Christ (established in 1830 and later renamed The Church of Jesus Christ of Latter-day Saints) and listened to their message."},"began":null,"lat":40.225357,"lng":-82.68814},{"name":"Oklahoma","members":53890,"congregations":98,"wards":80,"branches":18,"missions":1,"stakes":null,"districts":13,"familySearchCenters":30,"temples":1,"history":["Some of the first members of The Church of Jesus Christ of Latter-day Saints in Oklahoma did construction work in the Cherokee Nation in 1847. They preached about the Church until antagonism forced one Church member to leave the area. In June 1855, the Church established its missionary headquarters for the Native American territory. As early as July, missionaries preached to some 400 Native Americans living there. Many missionaries suffered from illnesses such as malaria from serving in the area, and at least four died. By 1860, most missionaries and many Church members left Oklahoma for Utah Territory. The Civil War scattered many of the state’s members and leaders.","In 1877, a few missionaries returned to Oklahoma, and soon thereafter missionary publications were translated into the Cherokee language. In 1892, the first meetinghouse was erected in Manard, Cherokee County. In 1921, a congregation was created in Gore, Oklahoma, with 113 members. The first stakes in Oklahoma were established in 1960, one in Tulsa and the other in Oklahoma City. In 2000, the Church dedicated a temple in Oklahoma City. That temple was renovated and rededicated in 2019.","There are now approximately 53,000 Church members in Oklahoma organized in 11 stakes. In 2021 the Church donated $2 million to the First Americans Museum in Oklahoma City to advance education about Native American tribes and their ancestral roots. Church members in Oklahoma regularly partner with civic and community leaders in humanitarian efforts, including the coordination of cleanup efforts in the aftermath of storms and natural disasters."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/oklahoma","asOf":"","id":"oklahoma","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1855,"said":"In June 1855, the Church established its missionary headquarters for the Native American territory."},"began":null,"lat":34.955082,"lng":-97.268406},{"name":"Oregon","members":148062,"congregations":278,"wards":233,"branches":45,"missions":3,"stakes":null,"districts":13,"familySearchCenters":76,"temples":2,"history":["When Church President Joseph Smith visited Washington, D.C. in 1838, Henry Clay, \"the great compromiser,\" suggested that Joseph Smith take members of The Church of Jesus Christ of Latter-day Saints to Oregon Territory. Joseph Smith did not take Clay seriously. Although the territory was claimed by both America and Great Britain, Church members from both countries were denied governmental support to settle there.","After Oregon obtained statehood, Church members found more favorable conditions. Latter-day Saint settlement largely began with the arrival of Latter-day Saint businessmen in 1887. They built a lumber mill on North Powder River and persuaded several hundred Latter-day Saint families to migrate to Oregon. Migration continued with the purchase of land for sugar beet farms. By June 1901, enough members had migrated that a stake (diocese) was created in Oregon. Two years later, the five original congregations had grown to twelve, \"all in excellent working order.\" By 1930, Church membership in Oregon was 3,230. When the Portland Oregon Temple was dedicated in 1989, more than 300,000 visitors toured the edifice."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/oregon","asOf":"","id":"oregon","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1838,"said":"When Church President Joseph Smith visited Washington, D.C. in 1838, Henry Clay, \"the great compromiser,\" suggested that Joseph Smith take members of The Church of Jesus Christ of Latter-day Saints to Oregon Territory."},"lat":43.97928,"lng":-120.737257},{"name":"Pennsylvania","members":54354,"congregations":105,"wards":75,"branches":30,"missions":2,"stakes":null,"districts":13,"familySearchCenters":46,"temples":2,"history":["Two years prior to the organization of The Church of Jesus Christ of Latter-day Saints in 1830, Joseph Smith and Emma Hale Smith moved to a farm in Harmony, Pennsylvania (present-day Oakland), and lived in the home of Emma’s parents, Elizabeth and Isaac Hale. After a few weeks, Emma and Joseph moved to a cabin adjacent to the farm. In this cabin, with Emma sometimes acting as his scribe, Joseph Smith translated most of the Book of Mormon, a sacred scripture that Latter-day Saints view as another testament of Jesus Christ.","Latter-day Saints believe that on May 15, 1829, Joseph Smith and his fellow Church leader Oliver Cowdery were visited by John the Baptist and shortly thereafter by Christ’s apostles Peter, James and John, and that through these visitations Joseph Smith received priesthood authority to administer Christ’s church.","A total of 12 congregations were organized in Pennsylvania in the 1830s, prior to the gatherings of Church members to Ohio, Missouri and Illinois. One prominent congregation in Philadelphia, established by Joseph Smith on December 23, 1839, had more than 200 members before 1840, and 8 to 10 new members were baptized weekly. One of those baptized in 1840 was Edward Hunter, who later served as Presiding Bishop of the Church from 1851 to 1883. That same year Benjamin Winchester, the presiding Church leader in Philadelphia, began publishing a church periodical, the Gospel Reflector . Despite large-scale immigration to the West after the death of Joseph Smith in 1844, Philadelphia was the port of entry for many Latter-day Saint immigrants from Europe and the British Isles, and during the mid-1850s it flourished, due in part to the influx of converts.","Around the end of the 19th century, conferences of the Church in eastern and western Pennsylvania were organized. In 1904 members of the Fairview Branch built a stone meetinghouse in Waynesboro, the first Latter-day Saint structure in the state. In 1960, the Philadelphia Stake was organized, and in 1969, the Pittsburgh Stake was organized. The Philadelphia Pennsylvania Temple was dedicated in 2016. The state is currently home to over 53,000 Church members. Church members regularly engage in service in their communities, including helping clean up after Hurricane Sandy in 2012."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/pennsylvania","asOf":"","id":"pennsylvania","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1830,"said":"Two years prior to the organization of The Church of Jesus Christ of Latter-day Saints in 1830, Joseph Smith and Emma Hale Smith moved to a farm in Harmony, Pennsylvania (present-day Oakland), and lived in the home of Emma’s parents, Elizabeth and Isaac Hale."},"lat":40.969989,"lng":-77.727883},{"name":"Rhode Island","members":5025,"congregations":9,"wards":8,"branches":1,"missions":120,"stakes":null,"districts":13,"familySearchCenters":1,"temples":101,"history":["As early as 1832, two Rhode Islanders in Providence joined The Church of Jesus Christ of Latter-day Saints, but a Providence branch was not formed until four years later. Missionaries baptized two converts in Rhode Island before opposition drove them out in 1832. In 1844 a congregation was formed in Newport with 221 members. During the late 1840s and 1850s, many converts immigrated west to gather with fellow Church members in the Great Basin. Some Latter-day Saints coming from the British Isles stopped in Rhode Island on their way west. In 1876, Erastus Snow wrote that he and another missionary met with Saints in Pawtucket who were on their way to the Great Basin from England. In the late 19th century, Latter-day Saint missionaries again began to do the work of preaching and organizing congregations in the eastern United States.","The congregation in Providence met irregularly until 1937, when the Providence Branch began meeting in members’ homes. Members eventually purchased and remodeled a private library that they dedicated as a meetinghouse on June 14, 1944. This library space served as a meetinghouse until 1960. In 1977 the Providence Stake was created. Currently there are over 4,000 Latter-day Saints in eight congregations in Rhode Island. Latter-day Saints in Rhode Island are engaged members of their communities, volunteering service such as cleanup efforts in the aftermath of Hurricane Sandy in 2012."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/rhode-island","asOf":"","id":"rhode-island","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1832,"said":"Missionaries baptized two converts in Rhode Island before opposition drove them out in 1832."},"began":null,"lat":41.796241,"lng":-71.599237},{"name":"South Carolina","members":46753,"congregations":89,"wards":71,"branches":18,"missions":2,"stakes":null,"districts":13,"familySearchCenters":23,"temples":1,"history":["Lysander M. Davis, a missionary for The Church of Jesus Christ of Latter-day Saints, arrived in South Carolina in 1839, just nine years after the Church was organized in New York. Expecting to find little or no acquaintance with the Church, Davis was surprised to find several people were prepared for baptism, taught by Emmanual Masters Murphy, a new convert to the Church in the area. Murphy had reportedly spoken with Church President Joseph Smith in the late 1830s, and was told to warn South Carolinians of the destruction soon to hit their state, \"the wars that will shortly come to pass, beginning at the rebellion of South Carolina, which will eventually terminate in the death and misery of many souls . . . the Southern states will call on other nations, even the nation of Great Britain. . . .\" This warning saw reality in 1861, when the Confederates attacked Fort Sumter, and the Civil War commenced.","With the united efforts of Murphy and Davis, Church membership grew, but at the same time, so did opposition. Members were persecuted for their beliefs, and Davis was briefly jailed. In 1897, mobs burned one of South Carolina's first Latter-day Saint meetinghouses in Centerville. It was rebuilt and burned again in 1899. Since then, the Church has enjoyed happier times and wide acceptance. Community support was evidenced in the 1990s when Church and community members worked together to provide relief after storms ripped through the South.","A temple in Columbia was dedicated on 16 October 1999."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/south-carolina","asOf":"","id":"south-carolina","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1839,"said":"Lysander M. Davis, a missionary for The Church of Jesus Christ of Latter-day Saints, arrived in South Carolina in 1839, just nine years after the Church was organized in New York."},"began":null,"lat":33.687439,"lng":-80.436374},{"name":"South Dakota","members":12064,"congregations":31,"wards":14,"branches":17,"missions":120,"stakes":null,"districts":13,"familySearchCenters":13,"temples":101,"history":["Leaders of The Church of Jesus Christ of Latter-day Saints who sought refuge from mob activity in the 1840s considered the Native American country of the Dakotas a possible site for settlement. Without the full consent of the Church President, volunteer colonizers established a settlement at Fort Vermillion on the Missouri River. They built cabins, planted crops, and preached to members of the Sioux tribe. Relations with Native Americans were sometimes fraught. The leader of the settlement, James Emmett, returned to Nauvoo in the summer of 1845 to seek favor with the Church. He was accepted in full fellowship and returned to Fort Vermillion with two missionaries to rebaptize the settlers. In 1846, the settlement was abandoned as members followed Church President Brigham Young’s directions to gather west.","In May 1883, missionaries from Minnesota began to preach in the Dakota states. By 1950, Sunday Schools were organized at Mitchell, Aberdeen, Brookings, Ft. Thompson and Huron."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/south-dakota","asOf":"","id":"south-dakota","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1883,"said":"In May 1883, missionaries from Minnesota began to preach in the Dakota states."},"began":null,"lat":44.647176,"lng":-100.348761},{"name":"Tennessee","members":61991,"congregations":121,"wards":93,"branches":28,"missions":2,"stakes":null,"districts":13,"familySearchCenters":35,"temples":2,"history":["When missionaries for The Church of Jesus Christ of Latter-day Saints arrived in Tennessee in October 1834, they preached at a Campbellite church meeting and baptized seven converts. Another 24 were baptized later. These missionaries were joined by future Church President Wilford Woodruff in 1835, who preached to several large audiences. During the ensuing months, the missionaries baptized 20 converts. By the end of the year, Woodruff had traveled 3,248 miles and baptized 43 people — three of whom were Protestant Christian preachers.","In 1844, Joseph Smith invited the Tennessee state assemblyman Solomon Copeland to run as his vice-presidential candidate in that year’s presidential election. Copeland, the husband of a Latter-day Saint, never replied to Smith’s invitation.","Tragedy struck the Church in Tennessee on August 10, 1884, when more than a dozen mobbers attacked a Latter-day Saint worship service near Cane Creek and shot to death two missionaries and two local church members. B.H. Roberts, who was in charge of the mission at that time, donned a disguise, traveled to the tense area and retrieved the bodies of the slain missionaries. Tension increased in the years that followed and, in 1888, a group of 177 Church members left Chattanooga and moved to Colorado and Utah. By the 1890s, public opinion in Tennessee became more tolerant toward the Church, and it once again continued to grow. The oldest existing Church building in the southeastern United States was dedicated in Northcutts Cove in 1909. The first stake in the state was established in Memphis in 1965.","Two temples were dedicated in Tennessee in 2000, one in Nashville and the other in Memphis. There are currently more than 50,000 Church members in the state organized into 12 stakes."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/tennessee","asOf":"","id":"tennessee","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1834,"said":"When missionaries for The Church of Jesus Christ of Latter-day Saints arrived in Tennessee in October 1834, they preached at a Campbellite church meeting and baptized seven converts."},"began":null,"lat":35.773008,"lng":-86.282008},{"name":"Texas","members":395964,"congregations":756,"wards":633,"branches":123,"missions":12,"stakes":null,"districts":1,"familySearchCenters":138,"temples":5,"history":["In the mid-1800s, Joseph Smith, the first President of The Church of Jesus Christ of Latter-day Saints, and other Church leaders considered moving Church members to land in what was then the Republic of Texas to escape mounting persecution in Illinois. Negotiations to buy large tracts of land in Texas were abandoned when Smith was murdered in 1844.","In 1845, apostle Lyman Wight led a company of Latter-day Saints to central Texas. He and his settlement made favorable impressions on their neighbors. Missionaries preached in Texas in the 1850s, and nearly 1,000 converts immigrated to Utah from Texas when missionary work came to a halt there prior to the Civil War.","Proselytizing resumed in 1875, but membership grew slowly through the end of the century. In the early 20th century, settlements were established in several southern states as gathering places for Church members. Examples in Texas include Odom and Kelsey. Membership eventually spread to larger urban areas like Dallas, Houston, and San Antonio. During the Mexican Revolution, members living in Ciudad Juarez relocated to Church branches in El Paso. The first stake in Texas was organized there in 1952. In October 1984, the Church dedicated the Dallas Texas Temple, the first in the Lone Star state. Since then, nine more have been dedicated or announced.","On October 14, 1993, astronaut Richard A. Searfoss of League City, Texas, became the first Latter-day Saint to pilot a space shuttle.","Church members in Texas regularly assist in humanitarian efforts and disaster cleanup. Examples of their efforts include responding to flooding in 1994 and to hurricanes Ike (2008) and Harvey (2017) and tropical storm Imelda (2019). The Church operates a 65,000-square-foot Deseret Industries thrift store and employment center in Houston. In June 2021, working in partnership with the National Association of Christian Churches, Catholic Charities, YMCA International Services, Texas Adventist Community Services and local food banks, the Church opened the Houston Family Transfer Center . It serves families who have been cleared at the border and need food, hygiene facilities and other assistance."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/texas","asOf":"","id":"texas","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1844,"said":"Negotiations to buy large tracts of land in Texas were abandoned when Smith was murdered in 1844."},"lat":31.26389,"lng":-98.545612},{"name":"Utah","members":2206370,"congregations":5365,"wards":5046,"branches":319,"missions":13,"stakes":null,"districts":7,"familySearchCenters":170,"temples":24,"history":["On July 24, 1847, when the first wagon company of Latter-day Saints arrived in the Salt Lake Valley, Church President Brigham Young declared it the “right place” for the Saints to establish themselves once more. Two days later, as they surveyed the valley, Young planted his cane in the fork of a small creek and said, “Here shall stand the temple of our God.” Salt Lake City quickly became the global headquarters of The Church of Jesus Christ of Latter-day Saints. By 1859, more than 60,000 Latter-day Saints, many of them recent converts from Europe, made the journey to Utah. These Latter-day Saints established more than 350 communities in Utah and the surrounding states.","Latter-day Saint communities, then as now, looked to the temple as a place of peace where sacred ordinances can be performed. The Salt Lake Temple, built at the location Brigham Young designated, took more than 40 years to complete. In the meantime, Temples were dedicated in St. George (1877), Logan (1884) and Manti (1888). The Salt Lake Temple, which has been designated a National Historic Landmark, was dedicated on April 6, 1893. There are now 31 temples in Utah.","In the nineteenth century, many Latter-day Saint women in Utah participated in the national campaign for women’s suffrage. The Woman’s Exponent, a Church-supported periodical edited by Latter-day Saint women, was among the leading voices in the fight to secure the right to vote for women in the United States. In 1870, Utah became the first territory in the United States in which women legally cast ballots.","As the headquarters of The Church of Jesus Christ of Latter-day Saints, Utah is closely associated with the Church in the minds of most people. For generations, Saints have gathered to Utah to pursue education, serve in the Church or be near the state’s many temples. In 2002, the Church and Utah were on full display for all the world when Utah hosted the Winter Olympic Games."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/utah","asOf":"","id":"utah","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1847,"said":"On July 24, 1847, when the first wagon company of Latter-day Saints arrived in the Salt Lake Valley, Church President Brigham Young declared it the “right place” for the Saints to establish themselves once more."},"lat":39.422519,"lng":-111.714358},{"name":"Vermont","members":4685,"congregations":9,"wards":7,"branches":2,"missions":120,"stakes":null,"districts":13,"familySearchCenters":8,"temples":101,"history":["Church founder Joseph Smith was born in Sharon, Vermont in 1805. In all, about a dozen of the early leaders of The Church of Jesus Christ of Latter-day Saints were born in Vermont, including Brigham Young. In 1831, one year after the Church was organized, Church member Jared Carter taught and baptized 27 converts in his hometown of Benson. Many of these early Latter-day Saints migrated to Ohio in 1833. In 1843, when the Church was facing intense persecution in Missouri and Illinois, Joseph Smith published a pamphlet appealing to the patriotic legacy of Vermont and its heralded Green Mountain Boys to help defend the citizenship rights of the Latter-day Saints.","In December 1905, Church President Joseph F. Smith, a nephew of the founding prophet, dedicated a 100-ton, 38-foot granite monument—one foot for each year of his life—to commemorate the centennial of Joseph Smith’s birth. During the Christmas season, lights adorn the monument’s surroundings. About 70,000 visitors come to the site annually.","The Montpelier Vermont Stake was created in 1976. Vermont is currently home to approximately 4,500 Latter-day Saints in 10 congregations. Latter-day Saints are engaged citizens who frequently partner with civic organizations to build their communities."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/vermont","asOf":"","id":"vermont","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1831,"said":"In 1831, one year after the Church was organized, Church member Jared Carter taught and baptized 27 converts in his hometown of Benson."},"lat":44.599072,"lng":-72.500261},{"name":"Virginia","members":99973,"congregations":212,"wards":177,"branches":35,"missions":2,"stakes":null,"districts":13,"familySearchCenters":46,"temples":1,"history":["Jedediah M. Grant, an early missionary for The Church of Jesus Christ of Latter-day Saints, discovered a high level of curiosity about the Church when he arrived in Virginia in 1839. He received three speaking invitations for every one he could fill. In 1841, there were some 80 members of the Church in Virginia. After Grant and his brother left the state in 1842, another missionary, R.H. Kinnamon, traveled to nine counties and baptized more than 100 people. When Church President Joseph Smith was murdered by a mob in 1844, Church membership in Virginia was likely more than 350. Many of these early members migrated to Utah Territory.","The Church stopped sending missionaries to Virginia during the Civil War, but resumed missionary work in the state during the 1870s. The Church grew gradually during the ensuing decades, and new congregations were formed throughout the state. In 1883, missionaries J. Golden Kimball and Charles Welch baptized Peter Mason and his family in Rockbridge County. The Mason family was Native American and their conversion led to the conversion of others in the Rockbridge Native American community and the establishment of a Church congregation in the central Blue Ridge region of the state.","In 1957, in Richmond, the Church established its first stake in Virginia. The Church grew rapidly in the state during the 1970s and 1980s, establishing 10 new stakes during those decades. In 1974, the Church dedicated the Washington D.C. Temple (in Kensington, Maryland). At that time, it was the only temple in the United States east of the Mississippi River. As such, it served thousands of church members living in the eastern United States, including those residing in Virginia. The Church began a major renovation of the temple in 2018, and it was rededicated in August 14, 2022.","In 2018, the Church announced the construction of a temple in the Richmond area. There are now more than 90,000 Church members in Virginia organized into 22 stakes. In 2021, President Dallin H. Oaks, First Counselor in the Church’s First Presidency, delivered a landmark address on religious freedom at the University of Virginia."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/virginia","asOf":"","id":"virginia","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1839,"said":"Jedediah M. Grant, an early missionary for The Church of Jesus Christ of Latter-day Saints, discovered a high level of curiosity about the Church when he arrived in Virginia in 1839."},"began":null,"lat":37.123224,"lng":-78.492772},{"name":"Washington","members":278576,"congregations":473,"wards":425,"branches":48,"missions":7,"stakes":null,"districts":13,"familySearchCenters":97,"temples":4,"history":["In 1854, four missionaries for The Church of Jesus Christ of Latter-day Saints serving in California were sent to labor in the Washington and Oregon territories. Enough converts joined to form a congregation along the Lewis River. During those early years, animosity against the Church members was so strong in Washington that when one convert died in 1911, her grave was dedicated secretly at night.","Many Church members helped with Washington's railroad construction for the Northern Pacific Oregon Short Line in the 1880s. In 1930, Church membership in Washington was 1,900 in eight congregations, with chapels in Everett, Spokane, Seattle, and Olympia. Many members flocked to the state with the completion of the Grand Coulee Dam on the Columbia River in the early 1940s. A temple was completed in Seattle in 1980.","The Spokane and Columbia River Washington Temples were completed and dedicated in 1999 and 2001, respectively."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/washington","asOf":"","id":"washington","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1854,"said":"In 1854, four missionaries for The Church of Jesus Christ of Latter-day Saints serving in California were sent to labor in the Washington and Oregon territories."},"began":null,"lat":38.895098,"lng":-77.036385},{"name":"West Virginia","members":17663,"congregations":39,"wards":25,"branches":14,"missions":1,"stakes":null,"districts":13,"familySearchCenters":14,"temples":101,"history":["In 1832, Joseph Smith, first President of The Church of Jesus Christ of Latter-day Saints, visited the portion of Virginia that later became West Virginia to purchase paper for the Church’s printing press. That same year, two missionaries for the Church baptized 40 converts in that part of the state. Missionaries continued to preach in the area during the 1830s, resulting in hundreds of men and women joining the Church. Many of these converts eventually moved from the area to gather with the main body of Church members in Far West, Missouri. One convert, Bathsheba Wilson Bigler Smith, who was baptized in 1837, said, “The spirit of gathering with the Saints in Missouri came upon me. . . . About this time my father sold his farm in West Virginia and we started for Far West.” Smith later served as a Churchwide leader of the women’s organization, the Relief Society. During the 1840s, missionaries frequently stopped to preach in Wheeling on their journeys to Washington, D. C.","In 1884, a congregation of 26 people was organized in the state. The first stake in West Virginia was created in 1970. Church membership in West Virginia has grown by 70% since 1989. There are now more than 17,000 Church members in the state organized across four stakes. The Church has frequently partnered with civic and community leaders on humanitarian causes in West Virginia."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/west-virginia","asOf":"","id":"west-virginia","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1832,"said":"In 1832, Joseph Smith, first President of The Church of Jesus Christ of Latter-day Saints, visited the portion of Virginia that later became West Virginia to purchase paper for the Church’s printing press."},"lat":38.475841,"lng":-80.840841},{"name":"Wisconsin","members":28950,"congregations":69,"wards":49,"branches":20,"missions":1,"stakes":null,"districts":13,"familySearchCenters":29,"temples":101,"history":["The first missionaries of The Church of Jesus Christ of Latter-day Saints in Wisconsin Territory preached during the 1830s. Then, in 1841, the state became the primary source of wood for the construction of a temple in Nauvoo, Illinois. Church leaders dispatched more than 100 men to Wisconsin where they set up six logging camps, known as the pineries, and operated four mills in the vicinity of the Black River. Between 1841 and 1845 these Church members sent an estimated 1.5 million board feet of milled lumber down the Mississippi River to Nauvoo.","When persecution forced the Latter-day Saints to leave Nauvoo in 1846 many Wisconsin members joined the trek to the Great Basin. Missionary efforts resumed in the state in 1878, with a congregation formed in Milwaukee in 1899 and a chapel built in 1907. After World War I, many German Church members immigrating to Wisconsin settled in Milwaukee. Their intent was to stay long enough to earn money to continue to Utah, but many settled in Wisconsin instead. In 1963, the first stake in Wisconsin was established in Milwaukee.","There are now more than 25,000 Church members in Wisconsin organized across six stakes. Latter-day Saints in the state frequently partner in humanitarian efforts with civic and community leaders throughout the state, and with those in other states throughout the Great Lakes region."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/wisconsin","asOf":"","id":"wisconsin","kind":"state","continent":"North America","country":"United States","firstMissionaries":{"year":1878,"said":"Missionary efforts resumed in the state in 1878, with a congregation formed in Milwaukee in 1899 and a chapel built in 1907."},"began":null,"lat":44.430898,"lng":-89.688464},{"name":"Wyoming","members":66665,"congregations":173,"wards":143,"branches":30,"missions":120,"stakes":null,"districts":13,"familySearchCenters":46,"temples":2,"history":["Throughout the latter half of the nineteenth century, members of The Church of Jesus Christ of Latter-day Saints gathering to the Western United States traveled through Wyoming. Between 1847 and 1859, tens of thousands of Saints followed the Oregon Trail between Fort Laramie and Fort Bridger before heading south to the Salt Lake Valley. In 1855, Church members purchased Fort Bridger and Fort Supply and created permanent settlements that helped resupply travelers on both the Mormon and Oregon Trails. Most pioneer companies traveled through Wyoming without incident. However, the Willie and Martin handcart companies of 1857 started later in the year and became trapped in the winter snows. Approximately 200 of the 1,075 in the companies died. Others were saved by rescue parties dispatched from Salt Lake City. Historic sites along Interstate 80 in Wyoming commemorate many of the events of Latter-day Saint overland migration including the tragic events of 1857.","In the second half of the nineteenth century, a rapid influx of Latter-day Saints gathering to the west from other parts of the United States and Europe led members to create several communities in Wyoming. In 1877, Church members began settling in the Star Valley area, and the following year, Church President Brigham Young dedicated the spot as a gathering place for members. Additional settlements were formed in the Teton, Bear, and Bridger Valleys and the Bighorn Basin. In 1892, the first stake of the Church in Wyoming was organized in Star Valley. Stakes are now organized in every major city in Wyoming.","Saints in Wyoming have partnered with their local communities to provide service and aid in times of need. In 2015, 270 members of the Casper Wyoming Stake, including 120 youth, volunteered to assist in the cleanup of Lusk, Wyoming, after much of the community was destroyed by floods. During the COVID-19 pandemic, Latter-day Saint Charities partnered with the Black 14 Philanthropy to provide assistance in African American communities throughout the United States.","In 2016, the Star Valley Wyoming Temple was dedicated in Afton, Wyoming. Two additional temples are now under construction in Casper and Cody."],"source":"https://newsroom.churchofjesuschrist.org/facts-and-statistics/state/wyoming","asOf":"","id":"wyoming","kind":"state","continent":"North America","country":"United States","firstMissionaries":null,"began":{"year":1847,"said":"Between 1847 and 1859, tens of thousands of Saints followed the Oregon Trail between Fort Laramie and Fort Bridger before heading south to the Salt Lake Valley."},"lat":43.170026,"lng":-107.568534}],"notListed":["Afghanistan","Algeria","Azerbaijan","Bangladesh","Belarus","Bhutan","Brunei","Burkina Faso","Chad","Comoros","Cuba","Djibouti","Egypt","Equatorial Guinea","Eritrea","Gabon","Gambia","Guinea","Guinea-Bissau","Iran","Iraq","Jordan","Kosovo","Kyrgyzstan","Laos","Lebanon","Libya","Liechtenstein","Maldives","Mali","Mauritania","Monaco","Morocco","Myanmar","Nepal","Niger","North Korea","North Macedonia","Oman","Pakistan","Palestine","Qatar","Saint Vincent and the Grenadines","San Marino","Sao Tome and Principe","Saudi Arabia","Senegal","Seychelles","Somalia","South Sudan","Sudan","Syria","Tajikistan","Timor-Leste","Tunisia","Turkmenistan","Uzbekistan","Vatican City","Vietnam","Yemen"],"noMissionBased":["American Samoa","Andorra","Antigua and Barbuda","Aruba","Austria","Bahamas","Bahrain","Belgium","Belize","Bosnia and Herzegovina","Cook Islands","Estonia","Greece","Iceland","Ireland","Kiribati","Lithuania","Macau","Malawi","Malaysia","Malta","Mauritius","Micronesia","Namibia","New Caledonia","Reunion","Serbia","Slovakia","Slovenia","Switzerland","Togo","Trinidad and Tobago"],"changes":[{"on":"2026-10-08","id":"texas","what":"missions","note":"Texas now has 12 missions (it had 120)."},{"on":"2026-10-07","id":"texas","what":"missions","note":"Texas now has 120 missions (it had 12)."},{"on":"2026-10-03","id":"united-states","what":"closed","note":"United States is no longer listed among the places the Church reports."},{"on":"2026-10-03","id":"united-states","what":"opened","note":"United States is now listed among the places the Church reports."}],"sources":["https://newsroom.churchofjesuschrist.org/facts-and-statistics/","https://www.churchofjesuschrist.org/learn/facts-statistics?lang=eng"]};
